#pragma once
#include <array>
#include <cstdint>
#include <limits>

namespace coop::elapsed {
enum class Channel : std::uint32_t {
    move_before,buttons_before,move_after,buttons_after,camera_before,camera_after,hud_after
};
enum class Category : std::uint32_t { self,native_helper,graphics,lock_wait };
inline constexpr unsigned channel_count=7,category_count=4,capacity=32;
inline constexpr std::array<std::uint64_t,12> upper_us{
    0,50,100,250,500,1000,2000,5000,10000,50000,100000,2000000};
inline constexpr unsigned bin_count=static_cast<unsigned>(upper_us.size())+1;
struct Ticket {
    std::uint64_t serial{},parent_serial{},root_serial{};
    std::uint32_t depth{},kind{},parent_kind{};
};
struct ScopeTicket {Ticket value{};explicit operator bool() const{return value.serial!=0;}};
struct CategoryTicket {Ticket value{};explicit operator bool() const{return value.serial!=0;}};
struct Histogram {
    std::array<std::uint64_t,bin_count> bins{};
    std::uint64_t count{};
};
struct ChannelStats {
    std::uint64_t calls{},wall_ticks{},child_ticks{},max_wall_ticks{},max_self_ticks{};
    std::array<std::uint64_t,category_count> category_ticks{};
    std::array<std::uint64_t,category_count> category_entries{};
    Histogram wall_us{},self_us{};
};
// Pointer-free cumulative values. Histograms use inclusive ceil-rounded us edges.
// An invalid root contributes failures only; no channel accounting survives it.
struct Batch {
    std::uint64_t frequency{},valid_roots{},invalid_roots{},overflows{},mismatches{};
    std::uint64_t clock_failures{},rollbacks{},invalid_channels{},invalid_categories{},configuration_failures{};
    std::array<ChannelStats,channel_count> channels{};
    std::uint32_t saturated{};
};

class Tracker {
public:
    // Caller serializes this object (normally one tracker per callback thread).
    // Configuration never clears a pending batch; frequency cannot change later.
    bool configure(std::uint64_t frequency) {
        if(depth_ || !frequency || frequency>maximum/1000000 || (frequency_ && frequency_!=frequency)) {
            failure(&Batch::configuration_failures);return false;
        }
        frequency_=frequency;batch_.frequency=frequency;return true;
    }
    std::uint32_t depth() const {return depth_;}
    ScopeTicket beginScope(Channel channel,std::uint64_t tick) {
        if(!frequency_)return {};
        if(!depth_) {root_={};root_.frequency=frequency_;invalid_=false;}
        checkClock(tick);
        if(static_cast<unsigned>(channel)>=channel_count) {
            if(depth_)failure(&Batch::invalid_channels);
            else {add(root_.invalid_channels,1,root_);invalid_=true;}
        }
        if(!invalid_ && current_scope_)closeSegment(frames_[current_scope_-1],tick);
        const auto ticket=push(scope_kind);
        if(!ticket.serial)return {};
        if(ticket.depth<=capacity) {
            auto& frame=frames_[ticket.depth-1];frame={};frame.ticket=ticket;frame.channel=channel;
            frame.start=tick;frame.segment=tick;frame.parent_scope=current_scope_;
            frame.entries[0]=1;
            current_scope_=ticket.depth;
        }
        return {ticket};
    }
    bool endScope(ScopeTicket ticket,std::uint64_t tick) {return end(ticket.value,scope_kind,tick);}
    CategoryTicket enterCategory(Category category,std::uint64_t tick) {
        if(!frequency_ || !depth_)return {};
        checkClock(tick);
        if(static_cast<unsigned>(category)>=category_count)failure(&Batch::invalid_categories);
        if(!invalid_)closeSegment(frames_[current_scope_-1],tick);
        const auto ticket=push(category_kind);
        if(!ticket.serial)return {};
        if(ticket.depth<=capacity) {
            auto& frame=frames_[ticket.depth-1];frame={};frame.ticket=ticket;
            frame.parent_scope=current_scope_;
            auto& scope=frames_[current_scope_-1];frame.previous=scope.category;
            if(static_cast<unsigned>(category)<category_count) {
                scope.category=category;
                if(!invalid_)add(scope.entries[static_cast<unsigned>(category)],1,root_);
            }
            scope.segment=tick;
        }
        return {ticket};
    }
    bool exitCategory(CategoryTicket ticket,std::uint64_t tick) {return end(ticket.value,category_kind,tick);}
    void invalidateClock() {
        if(frequency_)failure(&Batch::clock_failures);
    }
    // Never consumes/clears a batch while an outer game callback remains active.
    Batch takeBatch() {
        if(depth_)return {};
        const auto out=batch_;batch_={};batch_.frequency=frequency_;return out;
    }
private:
    static constexpr auto maximum=std::numeric_limits<std::uint64_t>::max();
    static constexpr std::uint32_t scope_kind=1,category_kind=2;
    struct Frame {
        Ticket ticket{};Channel channel{};Category category{},previous{};
        std::uint64_t start{},segment{},child{};
        std::array<std::uint64_t,category_count> ticks{};
        std::array<std::uint64_t,category_count> entries{};
        std::uint32_t parent_scope{};
    };
    std::array<Frame,capacity> frames_{};
    Batch batch_{},root_{};
    std::uint64_t frequency_{},serial_{},top_serial_{},root_serial_{},clock_{};
    std::uint32_t depth_{},top_kind_{},current_scope_{};
    bool invalid_{},clock_seen_{};
    static void add(std::uint64_t& target,std::uint64_t value,Batch& owner) {
        if(value>maximum-target) {target=maximum;owner.saturated=1;}else target+=value;
    }
    void failure(std::uint64_t Batch::*counter) {
        auto& owner=depth_?root_:batch_;add(owner.*counter,1,owner);
        if(depth_)invalid_=true;
    }
    void checkClock(std::uint64_t tick) {
        if(clock_seen_ && tick<clock_) {
            // First scope starts before depth grows: its failure belongs to root_.
            if(depth_)failure(&Batch::rollbacks);
            else {add(root_.rollbacks,1,root_);invalid_=true;}
        } else {clock_=tick;clock_seen_=true;}
    }
    Ticket push(std::uint32_t kind) {
        if(serial_==maximum || depth_==std::numeric_limits<std::uint32_t>::max()) {
            failure(&Batch::overflows);return {};
        }
        Ticket ticket{++serial_,top_serial_,depth_?root_serial_:serial_,depth_+1,kind,top_kind_};
        depth_=ticket.depth;top_serial_=ticket.serial;top_kind_=kind;root_serial_=ticket.root_serial;
        if(depth_>capacity)failure(&Batch::overflows);
        return ticket;
    }
    static bool same(const Ticket& a,const Ticket& b) {
        return a.serial==b.serial && a.parent_serial==b.parent_serial && a.root_serial==b.root_serial &&
            a.depth==b.depth && a.kind==b.kind && a.parent_kind==b.parent_kind;
    }
    bool end(const Ticket& ticket,std::uint32_t expected,std::uint64_t tick) {
        if(!frequency_)return false;
        if(!depth_ && !ticket.serial)return false; // Category helpers outside scopes are inert.
        if(!depth_ || !ticket.serial || ticket.depth!=depth_ || ticket.serial!=top_serial_ ||
           ticket.root_serial!=root_serial_ || ticket.kind!=expected || top_kind_!=expected ||
           (depth_<=capacity && !same(ticket,frames_[depth_-1].ticket))) {
            failure(&Batch::mismatches);return false;
        }
        checkClock(tick);
        if(depth_<=capacity) {
            auto& frame=frames_[depth_-1];
            if(expected==scope_kind) {
                if(!invalid_) {
                    closeSegment(frame,tick);recordScope(frame,tick-frame.start);
                    if(frame.parent_scope)add(frames_[frame.parent_scope-1].child,tick-frame.start,root_);
                }
                current_scope_=frame.parent_scope;
                if(current_scope_)frames_[current_scope_-1].segment=tick;
            } else {
                auto& scope=frames_[frame.parent_scope-1];
                if(!invalid_)closeSegment(scope,tick);
                scope.category=frame.previous;scope.segment=tick;
            }
        }
        --depth_;top_serial_=ticket.parent_serial;top_kind_=ticket.parent_kind;
        const bool valid=!invalid_;
        if(!depth_) {
            if(invalid_) {
                root_.channels={};add(root_.invalid_roots,1,root_);
            } else add(root_.valid_roots,1,root_);
            merge(root_);root_={};root_serial_=0;current_scope_=0;invalid_=false;
        }
        return valid;
    }
    void closeSegment(Frame& frame,std::uint64_t tick) {
        add(frame.ticks[static_cast<unsigned>(frame.category)],tick-frame.segment,root_);frame.segment=tick;
    }
    std::uint64_t microseconds(std::uint64_t ticks) {
        const auto whole=ticks/frequency_,remainder=ticks%frequency_;
        if(whole>maximum/1000000) {root_.saturated=1;return maximum;}
        auto out=whole*1000000;const auto scaled=remainder*1000000;
        const auto fraction=scaled/frequency_+(scaled%frequency_?1u:0u);
        if(fraction>maximum-out) {root_.saturated=1;return maximum;}
        out+=fraction;return out;
    }
    void histogram(Histogram& histogram,std::uint64_t ticks) {
        const auto us=microseconds(ticks);unsigned bin{};
        while(bin<upper_us.size() && us>upper_us[bin])++bin;
        add(histogram.count,1,root_);add(histogram.bins[bin],1,root_);
    }
    void recordScope(const Frame& frame,std::uint64_t wall) {
        auto& stats=root_.channels[static_cast<unsigned>(frame.channel)];
        add(stats.calls,1,root_);add(stats.wall_ticks,wall,root_);add(stats.child_ticks,frame.child,root_);
        for(unsigned i=0;i<category_count;++i) {
            add(stats.category_ticks[i],frame.ticks[i],root_);
            add(stats.category_entries[i],frame.entries[i],root_);
        }
        if(wall>stats.max_wall_ticks)stats.max_wall_ticks=wall;
        if(frame.ticks[0]>stats.max_self_ticks)stats.max_self_ticks=frame.ticks[0];
        histogram(stats.wall_us,wall);histogram(stats.self_us,frame.ticks[0]);
    }
    void merge(const Batch& source) {
        batch_.saturated|=source.saturated;
        add(batch_.valid_roots,source.valid_roots,batch_);add(batch_.invalid_roots,source.invalid_roots,batch_);
        add(batch_.overflows,source.overflows,batch_);add(batch_.mismatches,source.mismatches,batch_);
        add(batch_.clock_failures,source.clock_failures,batch_);add(batch_.rollbacks,source.rollbacks,batch_);
        add(batch_.invalid_channels,source.invalid_channels,batch_);add(batch_.invalid_categories,source.invalid_categories,batch_);
        add(batch_.configuration_failures,source.configuration_failures,batch_);
        for(unsigned i=0;i<channel_count;++i) {
            auto& out=batch_.channels[i];const auto& in=source.channels[i];
            add(out.calls,in.calls,batch_);add(out.wall_ticks,in.wall_ticks,batch_);add(out.child_ticks,in.child_ticks,batch_);
            if(in.max_wall_ticks>out.max_wall_ticks)out.max_wall_ticks=in.max_wall_ticks;
            if(in.max_self_ticks>out.max_self_ticks)out.max_self_ticks=in.max_self_ticks;
            for(unsigned j=0;j<category_count;++j) {
                add(out.category_ticks[j],in.category_ticks[j],batch_);
                add(out.category_entries[j],in.category_entries[j],batch_);
            }
            add(out.wall_us.count,in.wall_us.count,batch_);add(out.self_us.count,in.self_us.count,batch_);
            for(unsigned j=0;j<bin_count;++j) {
                add(out.wall_us.bins[j],in.wall_us.bins[j],batch_);
                add(out.self_us.bins[j],in.self_us.bins[j],batch_);
            }
        }
    }
};
} // namespace coop::elapsed

