struct Snapshot { bool active{}; Resources resources; Aim aim; skills::Palette palette; BoonAim boon; IngleAim ingle; FrazilHint frazil; SeparationHint separation; unsigned vocation_notice{}; bool startup_notice{}; std::uint64_t epoch{},generation{}; unsigned player_notice{}; bool player_notice_managed{}; Partners partners; CollectHint collect; player_feedback::SharedLife life; overhead::Frame overhead; }; // 0 hidden, 1 unsupported, 2 released/checking, 3 explicit rejoin.
