    unsigned size{sizeof(SkillHudStatus)},version{1},visible{},mode{},blocked{};
    int ids[3]{-1,-1,-1};
    char names[3][256]{};
};
static_assert(sizeof(SkillHudStatus)==800);
struct BoonHudStatus {
    unsigned size{sizeof(BoonHudStatus)},version{1},visible{},ready{},target_valid{},target_kind{},projected{};
