#pragma once
#include "coop/elapsed_tracker.hpp"
#include <cstdint>
#include <type_traits>

namespace coop::performance {
using Channel=elapsed::Channel;
using Category=elapsed::Category;
using Span=elapsed::ScopeTicket;
using Section=elapsed::CategoryTicket;

// These plain tickets require explicit finally cleanup at callback boundaries.
// All seven channels are elapsed spans, not CPU execution or frame attribution.
Span begin(Channel channel) noexcept;
void end(const Span& span) noexcept;
Section enter(Category category) noexcept;
void leave(const Section& section) noexcept;

struct Status {
    std::uint32_t size{sizeof(Status)},version{1},state{},coverage_mask{0x7f};
    std::uint64_t frequency{},admitted_roots{},completed_roots{},active_roots{};
    std::uint64_t clock_failures{},start_failures{};
    elapsed::Batch totals{};
};
static_assert(std::is_standard_layout_v<Status> && std::is_trivially_copyable_v<Status>);
static_assert(sizeof(elapsed::Histogram)==112 && sizeof(elapsed::ChannelStats)==328);
static_assert(sizeof(elapsed::Batch)==2384 && sizeof(Status)==2448);
// Internal measurement controls. Only runtime exports may authorize game use.
bool begin_session() noexcept;
bool seal_session() noexcept;
Status snapshot() noexcept;
#ifdef COOP_PERFORMANCE_TESTING
// Compiled only into the isolated adapter test executable, never the runtime.
using Clock=bool(*)(std::uint64_t&);
bool set_test_clocks(Clock frequency,Clock ticks) noexcept;
#endif
} // namespace coop::performance

