include/coop/session.hpp.text:
#pragma once
#include <array>
#include <cmath>
#include <cstdint>
#include "coop/input_router.hpp"
#include "coop/input_roles.hpp"

namespace coop {
constexpr std::uint16_t start_button = 0x10;
constexpr std::uint16_t back_button = 0x20;
constexpr std::uint16_t swap_buttons = back_button | 0x40 | 0x80; // View + LS + RS
constexpr std::uint16_t swap_prefix_buttons = 0x40 | 0x80; // LS + RS, then View
struct DeviceSample {
    bool connected{};
    std::uint32_t packet{};
    std::uint16_t buttons{};
    std::int16_t lx{}, ly{}, rx{}, ry{};
    std::uint8_t lt{}, rt{};
};
// Only the native P1 role has a virtual neutral sample. Invalid controller
// roles remain disconnected; callers cannot accidentally index slot4.
inline DeviceSample role_sample(const std::array<DeviceSample,4>& pads,int role) {
    return controller_slot(role)?pads[static_cast<unsigned>(role)]:DeviceSample{role==keyboard_mouse_role};
}
// Use the same shapes as gameplay: radial movement, per-axis camera deadzone.
// Shared by assignment/recovery and its notice so idle drift cannot disagree.
inline bool controls_released(const DeviceSample& pad, float movement_deadzone=0.245f,
                              float camera_deadzone=0.24f, bool allow_start=false) {
    if(!std::isfinite(movement_deadzone) || movement_deadzone<0.05f || movement_deadzone>0.45f ||
       !std::isfinite(camera_deadzone) || camera_deadzone<0.05f || camera_deadzone>0.45f)return false;
    const auto buttons=allow_start?static_cast<std::uint16_t>(pad.buttons&~start_button):pad.buttons;
    return pad.connected && !buttons && pad.lt<=30 && pad.rt<=30 &&
        std::hypot(static_cast<float>(pad.lx)/32767.0f,static_cast<float>(pad.ly)/32767.0f)<=movement_deadzone &&
        std::abs(static_cast<float>(pad.rx)/32767.0f)<=camera_deadzone &&
        std::abs(static_cast<float>(pad.ry)/32767.0f)<=camera_deadzone;
}
enum class SessionState : unsigned { awaiting_p1, solo, joined, suspended };
struct Routing {
    // P1 may be keyboard_mouse_role; P2 is always a physical controller slot.
    int p1{-1}, p2{-1};
    SessionState state{SessionState::awaiting_p1};
    bool neutralize{};
    bool controllers_swapped{}; // one update pulse; actor/camera roles stay fixed
    bool swap_input_consumed{};
    bool swap_neutral_required{}; // successful swap still waits for both releases
    bool menu_suspended{}; // proven same-binding menu pause; retain action state
    bool menu_resumed{}; // one update pulse; quarantined controls are already filtered
    std::uint64_t generation{};
    DeviceSample arisen{}, pawn{};
};
// Owns assignment only. Call under the runtime's input lock. No game pointers.
// Start assigns P1; a different controller holds Start for one second to join.
// P2 Back+Start leaves. Observed disconnect/packet reset revokes ownership.
// After P1 loss its latest intentional slot remains reserved. A different pad
// can replace a disconnected P1 with a fresh neutral-armed 3-second Start hold.
// Optional native keyboard/mouse P1 is available immediately and is never
// claimed, disconnected or swapped by a controller. Every pad may join P2.
class Session {
public:
    explicit Session(unsigned join_hold_ms=1000, float movement_deadzone=0.245f, float camera_deadzone=0.24f,
                     bool p1_keyboard_mouse=false)
        : join_hold_ms_(join_hold_ms>=500 && join_hold_ms<=3000?join_hold_ms:1000),
          movement_deadzone_(movement_deadzone),camera_deadzone_(camera_deadzone),p1_keyboard_mouse_(p1_keyboard_mouse) {}
    Routing update(const std::array<DeviceSample, 4>& pads, std::uint64_t now,
                   bool offline, bool gameplay, bool focused, std::uint64_t world,
                   bool menu_pause=false);
    // menu_pause is native menu evidence, never merely !gameplay. Only an
    // uninterrupted healthy/focused pause of an already active binding can
    // retain held actions. New menu buttons/triggers wait for their own release;
    // movement/camera axes resume immediately. Other suspension stays neutral-gated.
    // Permanently revoke P2 and its remembered join, including pending recovery.
    // Returns true if an owned or remembered binding was removed. Candidates
    // must provide neutral controls before a fresh Start edge can join again.
    bool release_pawn();
    // Retire current pawn ownership while remembering the joined controller.
    // Returns true only when current ownership was retired. Repeated calls do
    // not reset recovery. update() can reclaim the same unchanged slot only
    // when all admission gates and a complete neutral sample coincide.
    bool release_pawn_temporarily();
    bool pawn_recovery_pending() const { return p2_<0 && desired_p2_>=0; }
    bool menu_resume_pending() const { return menu_paused_; }
    bool pawn_neutral_pending() const { return pawn_neutral_required_; }
    // Value-only continuity witness for the adapter's existing native hold.
    // Never use this as a fresh gameplay command while a menu is active.
    DeviceSample menu_hold_sample(bool pawn=true) const {
        if(!menu_paused_)return {};
        const unsigned role=pawn?1u:0u;
        auto out=last_gameplay_[role];const auto& controls=menu_controls_[role];
        out.buttons=controls.held;out.lx=out.ly=out.rx=out.ry=0;
        if(!controls.held_lt)out.lt=0;
        if(!controls.held_rt)out.rt=0;
        return out;
    }
    // Keep the same pawn/controller binding, but suppress all controls until a
    // complete neutral sample (used after native distance recall).
    void neutralize_pawn() { pawn_neutral_required_=p2_>=0;forget_menu(); }
    // Actor/world lifetime changes retire pawn ownership, retain joined intent
    // for automatic recovery, and preserve controller P1.
    // Keep device history so a later disconnect/packet reset still revokes P1.
    // Repeated observations of the same epoch have no further effect.
    void world_changed(std::uint64_t world);
    // Windows broadcasts changes for unrelated devices too. Cancel incomplete
    // gestures/joins, retain bindings and packet history, and let the next
    // copied samples prove actual controller loss. Ongoing assigned gameplay
    // input and any preexisting neutral barrier are preserved.
    void devices_changed();
    void invalidate();
private:
    void forget_menu() { menu_paused_=false;menu_controls_={};last_gameplay_={}; }
    bool controls_neutral(const DeviceSample& pad,bool allow_start) const {
        return controls_released(pad,movement_deadzone_,camera_deadzone_,allow_start);
    }
    unsigned join_hold_ms_;
    float movement_deadzone_,camera_deadzone_;
    bool p1_keyboard_mouse_{};
    int p1_{-1}, p2_{-1}, desired_p2_{-1};
    int reserved_p1_{-1};
    bool active_{}, initialized_{}, suppress_start_{};
    bool release_recovery_{};
    bool pawn_neutral_required_{};
    struct MenuControls {
        std::uint16_t held{},blocked{};
        bool held_lt{},held_rt{},blocked_lt{},blocked_rt{};
        void begin(const DeviceSample& before) {
            held=before.buttons & static_cast<std::uint16_t>(~(start_button|back_button));
            held_lt=before.lt>30;held_rt=before.rt>30;
        }
        void observe(const DeviceSample& raw) {
            held &= raw.buttons;
            held_lt=held_lt && raw.lt>30;held_rt=held_rt && raw.rt>30;
            blocked=raw.buttons & static_cast<std::uint16_t>(~held);
            blocked_lt=raw.lt>30 && !held_lt;blocked_rt=raw.rt>30 && !held_rt;
        }
        void filter(DeviceSample& raw) {
            blocked &= raw.buttons;
            blocked_lt=blocked_lt && raw.lt>30;blocked_rt=blocked_rt && raw.rt>30;
            raw.buttons &= static_cast<std::uint16_t>(~blocked);
            if(blocked_lt)raw.lt=0;
            if(blocked_rt)raw.rt=0;
        }
    };
    bool menu_paused_{};
