#pragma once
#include <array>
#include <cstdint>
#include <cstring>
#include <limits>

namespace coop::shared_life_down_debug {
// Developer-only copied observations. These values never authorize gameplay.
struct Evaluation {unsigned evaluated{},truth{};};
inline bool observe(bool value,unsigned bit,Evaluation& result,bool developer) {
    if(developer){result.evaluated|=bit;if(value)result.truth|=bit;}
    return value;
}
inline constexpr unsigned capacity=8,row_words=64,header_words=8,total_words=header_words+capacity*row_words;
using Row=std::array<unsigned,row_words>;
// Header: byteSize/version/rowWords/capacity/count/next/serialLow/serialHigh.
// Physical rows follow; next is the oldest row when count==capacity.
class Ring {
public:
    void publish(Row row) {
        if(serial_!=std::numeric_limits<std::uint64_t>::max())++serial_;
        row[0]=static_cast<unsigned>(serial_);row[63]=static_cast<unsigned>(serial_>>32);
        rows_[next_]=row;next_=(next_+1)%capacity;if(count_<capacity)++count_;
    }
    unsigned copy_to(unsigned* out,unsigned count,bool developer) const {
        if(!developer || !out || count!=total_words)return 0;
        const unsigned header[header_words]{total_words*sizeof(unsigned),1,row_words,capacity,count_,next_,
            static_cast<unsigned>(serial_),static_cast<unsigned>(serial_>>32)};
        std::memcpy(out,header,sizeof(header));std::memcpy(out+header_words,rows_.data(),sizeof(rows_));return 1;
    }
private:
    std::array<Row,capacity> rows_{};
    unsigned next_{},count_{};
    std::uint64_t serial_{};
};
}

