// Read-only native selection registry, statically derived from 465DD0.
// No game calls/writes. Reject a changed table/count or unbounded registry.
(() => {
 globalThis.grabRegistry=()=>{
  const initial=runtimeStatus(),manager=ptr('0x18fa4d8').readPointer();if(manager.isNull())throw Error('No selector manager');
  const count=manager.add(0x24).readU32(),table=manager.add(0x30).readPointer();
  if(count>4096||(count&&table.isNull()))throw Error('Invalid native selection registry');
  const rows=[];
  for(let i=0;i<count;i++){
   const entry=table.add(i*4).readPointer();if(entry.isNull())throw Error('Null registry entry');
   if(entry.add(0x50).readS32()>=1||entry.add(0x4c).readU8()===0||entry.add(0x4d).readU8()===1)continue;
   const actor=entry.add(0x48).readPointer();if(actor.isNull())throw Error('Null active actor');const flags=actor.add(0x206d).readU8();
   rows.push({entry:entry.toString(),actor:actor.toString(),vtable:actor.readPointer().toString(),flags,mask:entry.add(0x44).readU32(),category:actor.add(0x1fc0).readU32(),enemyType:flags&8?actor.add(0x5858).readU32():null,pos:[0xe0,0xe4,0xe8].map(o=>actor.add(o).readFloat())});
  }
  const final=runtimeStatus();if(manager.add(0x24).readU32()!==count||!manager.add(0x30).readPointer().equals(table)||initial.stage!==final.stage||initial.generation!==final.generation)throw Error('Registry/scene changed');
  return {pid:Process.id,time:Date.now(),stage:final.stage,generation:final.generation,count,rows};
 };return grabRegistry();
})()

