     }catch(error){fail(error);}
    },
    onLeave(){if(!this.counted)return;
     try{
      if(!this.row)return;const after=lifeSample(this.life),before=this.row.before;
      if(!after||after.actor!==before.actor||after.vtable!==before.vtable||after.life!==before.life||after.list!==before.list||
         after.count!==before.count||after.index!==before.index||after.nativePartId!==before.nativePartId){this.row.lifetimeChanged=true;return;}
