     }catch(error){fail(error);}finally{--e.activeCallbacks;this.counted=false;}
    }
   });deadline=setTimeout(()=>stop('timeout'),durationMs);
  }catch(error){stop('start-error');throw error;}
  return {started:true,pid:Process.id,durationMs,maxRows:MAX_ROWS};
 };
