  attempts:u64(p,o),observations:u64(p,o+8),submissions:u64(p,o+16),completions:u64(p,o+24),
  neutral:u64(p,o+32),neutral_completions:u64(p,o+40),gated:u64(p,o+48),release_only:u64(p,o+56),
  repeated:u64(p,o+64),overwritten:u64(p,o+72),unresolved:u64(p,o+80),expired:u64(p,o+88),
  invalidated:u64(p,o+96),unobserved_overwrites:u64(p,o+104),unobserved_unresolved:u64(p,o+112),
  invalid_tokens:u64(p,o+120),invalid_context:u64(p,o+128),pending:u64(p,o+136),
