    clock_failures:u64(buffer,16),validation_failures:u64(buffer,24),
    counters:{
     frequency:u64(c,0),expiry_ticks:u64(c,8),publications:u64(c,16),changed_publications:u64(c,24),
     refreshes:u64(c,32),invalid_publications:u64(c,40),clock_rollbacks:u64(c,48),
