     enabled:u32(c,1320),sealed:u32(c,1324),counter_saturated:u32(c,1328)
    },
    coverage:{
     units:'uint64 values are exact base-10 strings; elapsed histogram values and bounds are microseconds.',
     bins:'Each bin is the inclusive upper_us edge shown; the final null edge is the unbounded overflow bin. Durations are rounded up to integer microseconds.',
     p1_delivery:'Logical XInput output delivery; this does not measure native actor consumption.',
     p2_movement:'Validated P2 movement wrapper/capture completion; completion is an upper bound on the internal consumer instant.',
     p2_buttons:'Validated P2 button wrapper/capture completion; completion is an upper bound on the internal consumer instant.',
     attempts_and_observations:'Attempts count consumer checks; observations count the first channel selection for a published sequence. A gated selection requires the next publication before that channel can select again.',
     submissions:'A validated token was submitted for a connected, owned context; disposition counters separately report neutral, gated, and release-only cases. Samples include unchanged refresh publications and final neutral or suppressed packets; they do not imply action activation.',
     completions:'A submitted token completed with a still-valid context. This covers only instrumented channels during the explicit profiler start-to-seal window.',
     timing:'Histograms measure publication-to-submission and publication-to-completion, not provider dispatch or wall-clock polling latency; durations are rounded upward to integer microseconds.',
     pending:'Outstanding token count in the returned snapshot. Expiry is evaluated lazily on tracker operations; sealing first advances time and expires pending tokens, then marks any remaining tokens unresolved.'
    }
   };
  };
