// Bounded sampler for already-defined value readers. It never installs hooks,
// reads native memory directly, or begins/seals the profiler automatically.
(() => {
 'use strict';
 if(globalThis.performanceTrialRunning)throw Error('Stop the existing performance trial before redefining it');
