  rows:3601,markers:128,errors:16});
 const freeze=value=>{
  if(value&&typeof value==='object'&&!Object.isFrozen(value)){
   Object.values(value).forEach(freeze);Object.freeze(value);
  }return value;
 };
 const copy=value=>JSON.parse(JSON.stringify(value,(_,v)=>typeof v==='number'&&!Number.isFinite(v)?{nonFinite:String(v)}:v));
