 const status=()=>{
  if(!trial)return immutable({defined:true,running:false,rows:0,bounds});
  return immutable({label:trial.label,phase:trial.phase,running:trial.running,reason:trial.reason,
   startedUtc:trial.startedUtc,stoppedUtc:trial.stoppedUtc,durationMs:trial.durationMs,
   elapsedWallMs:trial.running?Date.now()-trial.started:trial.elapsedWallMs,
   rows:trial.rows.length,markers:trial.markers.length,errors:trial.errors.length,bounds});
 };
