  const t=stamp();run.running=false;globalThis.performanceTrialRunning=false;
  run.reason=reason;run.stopped=t.wallTimeMs;run.stoppedUtc=t.wallUtc;run.elapsedWallMs=t.wallTimeMs-run.started;
  if(run.markers.length<bounds.markers)run.markers.push(immutable({...t,elapsedWallMs:run.elapsedWallMs,phase:run.phase,kind:'stop',reason}));
  freeze(run);globalThis.performanceTrial=run;return status();
 };
 globalThis.performanceTrialStatus=status;
 globalThis.stopPerformanceTrial=()=>stop('requested');
