  if(!trial?.running)throw Error('Running performance trial required for a marker');
  if(typeof label!=='string'||!label.trim()||label.length>80)throw Error('Non-empty phase label up to 80 characters required');
  if(trial.markers.length>=bounds.markers-1)throw Error('Performance trial marker bound reached');
  const t=stamp(),marker=immutable({...t,elapsedWallMs:t.wallTimeMs-trial.started,phase:label,kind:'phase'});
