   intervalMs:bounds.intervalMs,running:true,reason:null,stopped:null,stoppedUtc:null,elapsedWallMs:null,
   rows:[],markers:[],errors:[],limits:[
    'Rows combine sequential cached value snapshots; the snapshots are not atomic with each other or with native actor/render work.',
    'Elapsed profiler spans include QPC preemption time and are not CPU, frame, GPU, or presentation measurements.',
    'Only explicitly selected lock acquisitions are categorized; nested unclassified lock waits remain self. Admission and aggregate merge outside spans are not measured.',
