  const actor=address===0xb81e30?this.context.eax:this.context.edi,who=identify(actor);if(!who)return;
  if(e.rows.length>=12000)throw Error('Observation capacity');
  const row={time:Date.now(),address:ptr(address).toString(),player:who.player,
   actor:actor.toString(),thread:Process.getCurrentThreadId(),action:actor.add(0x2dd4).readU32(),
   value:this.context.esp.add(address===0xb81e30?4:12).readFloat(),
   stamina:who.info.add(0x2a8).readFloat(),pawnFlag:actor.add(0x206d).readU8(),
   regionFlags:who.gs.add(0xac720).readU32()};e.rows.push(row);
  if(e.rows.length<=4)send({staminaFirstRow:row});
