  if(before.some((v,i)=>!v||JSON.stringify(v)!==JSON.stringify(actors[i].id)))throw Error('Party actor identity changed');
  const inventory=[itemCount(manager,0,itemId),itemCount(manager,1,itemId)];
  const after=[identity(actors[0].actor,gs),identity(actors[1].actor,gs)],final=runtimeStatus();
  if(!ptr(GAME_STATE).readPointer().equals(gs)||!ptr(INVENTORY_MANAGER).readPointer().equals(manager)||
   after.some((v,i)=>!v||JSON.stringify(v)!==JSON.stringify(before[i]))||
   final.stage!==initial.stage||final.generation!==initial.generation||final.nativeOffline!==1||
   final.transport!==2||final.faults||final.nativeErrors||final.menuGated)
