   runtime:final,gameState:String(gs),inventoryManager:String(manager),
   actors:actors.map(x=>x.id),inventory,
   scope:'One read-only snapshot of item quantity in native P1 slot 0 and main-pawn slot 1; no reload action is performed.'};
 };
