// Definition-only reader for the versioned elapsed-performance export.
// It performs no polling and never begins or seals a session implicitly.
(() => {
 'use strict';
 const abi=Object.freeze({name:'CoopGetPerformanceStatus',size:2448,version:1,
  channels:['move_before','buttons_before','move_after','buttons_after','camera_before','camera_after','hud_after'],
  categories:['self','native_helper','graphics','lock_wait'],
  upperUs:[0,50,100,250,500,1000,2000,5000,10000,50000,100000,2000000,null]});
 let readStatus=null,beginSession=null,sealSession=null;
 const u32=(p,o)=>p.add(o).readU32();
 const u64=(p,o)=>{
  const value=p.add(o).readU64();
  if(typeof value==='number'){
   if(!Number.isSafeInteger(value)||value<0)throw Error('Unsafe uint64 value at offset '+o);
   return String(value);
  }
  const decimal=value.toString();
  if(!/^(0|[1-9][0-9]*)$/.test(decimal))throw Error('Invalid uint64 value at offset '+o);
  return decimal;
 };
 const histogram=(p,o)=>({bins:abi.upperUs.map((_,i)=>u64(p,o+i*8)),upper_us:abi.upperUs.slice(),count:u64(p,o+104)});
 const channelStats=(p,o)=>{
  const stats={calls:u64(p,o),wall_ticks:u64(p,o+8),child_ticks:u64(p,o+16),
   max_wall_ticks:u64(p,o+24),max_self_ticks:u64(p,o+32),category_ticks:{},category_entries:{}};
  abi.categories.forEach((name,i)=>{stats.category_ticks[name]=u64(p,o+40+i*8);});
  abi.categories.forEach((name,i)=>{stats.category_entries[name]=u64(p,o+72+i*8);});
  stats.wall_us=histogram(p,o+104);stats.self_us=histogram(p,o+216);
  return stats;
 };
 const batch=(p,o)=>{
  const result={frequency:u64(p,o),valid_roots:u64(p,o+8),invalid_roots:u64(p,o+16),
   overflows:u64(p,o+24),mismatches:u64(p,o+32),clock_failures:u64(p,o+40),
   rollbacks:u64(p,o+48),invalid_channels:u64(p,o+56),invalid_categories:u64(p,o+64),
   configuration_failures:u64(p,o+72),channels:{}};
  abi.channels.forEach((name,i)=>{result.channels[name]=channelStats(p,o+80+i*328);});
  result.saturated=u32(p,o+2376);
  return result;
 };
 const moduleForCall=()=>{
  if(typeof Process==='undefined'||typeof Process.getModuleByName!=='function'||
     typeof Memory==='undefined'||typeof Memory.alloc!=='function'||typeof NativeFunction!=='function')
   throw Error('Frida Process/Memory/NativeFunction APIs are required');
  if(Process.arch!=='ia32'||Process.pointerSize!==4)throw Error('Pinned x86 performance ABI required');
  return Process.getModuleByName('ddcoop_runtime.dll');
 };
 const createReader=()=>{
  const module=moduleForCall(),address=module.getExportByName(abi.name),buffer=Memory.alloc(abi.size);
  const get=new NativeFunction(address,'int',['pointer','uint'],'mscdecl');
  return ()=>{
   if(get(buffer,abi.size)!==1)throw Error(abi.name+' refused diagnostic ABI');
   if(u32(buffer,0)!==abi.size||u32(buffer,4)!==abi.version)
    throw Error(abi.name+' size/version mismatch: required '+abi.size+'/v'+abi.version);
   return {size:u32(buffer,0),version:u32(buffer,4),state:u32(buffer,8),coverage_mask:u32(buffer,12),
    frequency:u64(buffer,16),admitted_roots:u64(buffer,24),completed_roots:u64(buffer,32),
    active_roots:u64(buffer,40),clock_failures:u64(buffer,48),start_failures:u64(buffer,56),
    totals:batch(buffer,64),coverage:{
     units:'All uint64 values are exact base-10 strings. Tick values use the reported QPC frequency; only histogram values and edges are microseconds.',
     bins:'Each histogram bin is the inclusive integer-microsecond upper edge shown; the last null edge is unbounded. Durations are rounded up to integer microseconds.',
     channels:'Seven instrumented callback spans: movement, buttons, and camera before/after, plus HUD after. coverage_mask advertises channel availability even when idle.',
     categories:'Time is assigned to self, native helper, graphics, or selected lock acquisitions inside each span; nested lock waits not explicitly classified remain self. QPC preemption time is included, while admission and aggregate merge work outside measured spans is not.',
     elapsed:'These are elapsed spans, not CPU execution time, frame time, GPU/present time, or attribution to a game frame.',
     roots:'Only completed callback roots are published. Invalid roots contribute failure counters and no channel accounting; active roots remain unmerged until their outer callback returns.',
     lifecycle:'The reader is inert until called. Collection starts and ends only through the explicit beginPerformanceSession() and sealPerformanceSession() helpers.'
    }};
  };
 };
 const control=(name)=>{
  if(typeof NativeFunction!=='function')throw Error('Frida NativeFunction API is required');
  if(typeof Process==='undefined'||typeof Process.getModuleByName!=='function'||Process.arch!=='ia32'||Process.pointerSize!==4)
   throw Error('Pinned x86 performance ABI required');
  const address=Process.getModuleByName('ddcoop_runtime.dll').getExportByName(name);
  return new NativeFunction(address,'int',[],'mscdecl');
 };
 globalThis.readPerformanceStatus=()=>{if(!readStatus)readStatus=createReader();return readStatus();};
 globalThis.beginPerformanceSession=()=>{if(!beginSession)beginSession=control('CoopBeginPerformance');return beginSession()===1;};
 globalThis.sealPerformanceSession=()=>{if(!sealSession)sealSession=control('CoopSealPerformance');return sealSession()===1;};
})();

