// Read diagnostics and supply bounded synthetic XInput samples at the provider
// boundary. No engine hooks or actor-memory writes in this script.
(() => {
 const runtime=Process.getModuleByName('ddcoop_runtime.dll');
 const get=new NativeFunction(runtime.getExportByName('CoopGetStatus'),'int',['pointer','uint'],'mscdecl');
 const put=new NativeFunction(runtime.getExportByName('CoopSetTestPads'),'int',['pointer','uint'],'mscdecl');
 const info=Memory.alloc(132),pads=Memory.alloc(80);
 globalThis.runtimeStatus=()=>{
  if(get(info,132)!==1)throw new Error('Runtime status ABI mismatch');
  const keys=['size','version','runtime','p1','p2','session','transport','nativeOffline','nativeErrors','faults','stage','generation','physicalMask','developerInput','menuGated'];
  const out={};keys.forEach((k,i)=>out[k]=info.add(i*4).readS32());
  out.actors=[0,1].map(i=>{const p=info.add(60+i*36);return {observed:p.readU32(),action:p.add(4).readU32(),mode:p.add(8).readU32(),held:p.add(12).readU32(),frames:p.add(16).readU32(),pos:[20,24,28].map(n=>p.add(n).readFloat()),angle:p.add(32).readFloat()};});return out;
 };
 globalThis.testDevices=[{connected:true},{connected:true},{},{}];
 let packet=1;
 globalThis.setDevices=(devices)=>{
  ++packet;
  pads.writeByteArray(new Uint8Array(80));
  devices.forEach((d,i)=>{const p=pads.add(i*20);p.writeU8(d.connected?1:0);p.add(4).writeU32(d.packet??packet);p.add(8).writeU16(d.buttons??0);
   [10,12,14,16].forEach((o,n)=>p.add(o).writeS16([d.lx??0,d.ly??0,d.rx??0,d.ry??0][n]));p.add(18).writeU8(d.lt??0);p.add(19).writeU8(d.rt??0);});
  if(put(pads,4)!==1)throw new Error('Developer input unavailable');
 };
 if(globalThis.deviceTimer)clearInterval(deviceTimer);
 globalThis.deviceTimer=setInterval(()=>setDevices(testDevices),100);
 setDevices(testDevices);
 return runtimeStatus();
})()

