// Definition-only, provider-only Strider RB+A reference/comparison.
// Proven read layouts: primary_skill_trial.js, combat_observation.js and
// grabRegistry (EXP-020/025). No hooks, engine calls or actor-memory writes.
// Samples are sequential, not dispatch observations or proof of learned evasion.
(() => {
 const helpers=['primarySkillTrial','quarryContactTrial','quarryClimbTrial','climbTrial',
  'climbInterrupt','arisenMove','nativeWalk','registryApproach','shoulderTrial','grabTrial'];
 globalThis.startStriderDodgeTrial=(player,expectedPid)=>{
  if(![0,1].includes(player)||!Number.isInteger(expectedPid)||expectedPid!==Process.id)
   throw Error('Explicit current PID and player 0/1 required');
  if(globalThis.striderDodgeTrial?.running||globalThis.pulseRunning||helpers.some(k=>globalThis[k]?.running))
   throw Error('Exclusive inactive input helpers required');
  for(const name of ['runtimeStatus','splitStatus','grabRegistry','setDevices'])
   if(typeof globalThis[name]!=='function')throw Error('Missing prerequisite: '+name);
  const initial=runtimeStatus(),gs=ptr('0x18fa4bc').readPointer();
  if(initial.session!==2||initial.p1!==0||initial.p2!==1||initial.developerInput!==1||gs.isNull())
   throw Error('Joined developer-provider slots 0/1 required');
  const phases=[['neutral',{},1000],['rb',{buttons:0x200},700],
   ['rb_a_direction',{buttons:0x1200,ly:22000},350],
   ['rb_release_a',{buttons:0x200},1800],['final_neutral',{},2200]];
  const duration=phases.reduce((n,p)=>n+p[2],0),limits={sampleMs:50,maxRows:180,frameStallMs:750,deadlineMs:duration+1000};
  const registry=grabRegistry(),party=[];
  for(const row of registry.rows){
   if(!['0x15e90d0','0x15e8468'].includes(row.vtable)||party.some(p=>p.actor===row.actor))continue;
   const a=ptr(row.actor),info=a.add(0x3dec).readPointer();
   if(!a.add(0x32bc).readPointer().equals(a))throw Error('Party self identity mismatch');
   const who=info.equals(gs.add(0xa76d0))?0:info.equals(gs.add(0xa7ec0))?1:-1;
   party.push({actor:row.actor,info:String(info),actorVtable:row.vtable,player:who});
  }
  if(party.length!==4||[0,1].some(who=>party.filter(p=>p.player===who).length!==1)||party.filter(p=>p.player===-1).length!==2)
   throw Error('P1/P2 and two support identities required');
  const e={pid:Process.id,expectedPid,player,initial,party,limits,duration,running:false,
   started:Date.now(),rows:[],phases:[],errors:[],reason:null,
   evidence:'Sequential native samples and provider requests; no dispatch hook or learned-skill assertion'};
  let timer,deadline,index=0,phaseStarted=0,lastTime=e.started;
  const lastFrames=initial.actors.map(a=>a.frames),lastAdvance=[e.started,e.started];
  const neutral=()=>{globalThis.testDevices=[{connected:true},{connected:true},{},{}];setDevices(testDevices);};
  const stop=(reason='requested')=>{
   clearInterval(timer);clearTimeout(deadline);e.running=false;e.reason=reason;e.elapsedMs=Date.now()-e.started;
   try{neutral();}catch(error){e.errors.push('Neutral provider failed: '+String(error));}
  };
  const guard=r=>{
   if(Process.id!==expectedPid||r.session!==2||r.stage!==initial.stage||r.generation!==initial.generation||
    r.p1!==initial.p1||r.p2!==initial.p2||r.developerInput!==1||r.menuGated||r.faults||r.nativeErrors||
    r.nativeOffline!==1||r.transport!==2||!ptr('0x18fa4bc').readPointer().equals(gs))
    throw Error('Gameplay/scene/assignment/offline guard changed');
  };
  const sample=()=>{
   const time=Date.now();if(time<lastTime||time-e.started>limits.deadlineMs)throw Error('Clock/deadline guard');lastTime=time;
   const r=runtimeStatus();guard(r);const s=splitStatus();if(s.faults||s.active!==1)throw Error('Split view unavailable');
   const currentRegistry=grabRegistry(),currentParty=currentRegistry.rows.filter(row=>['0x15e90d0','0x15e8468'].includes(row.vtable));
   if(new Set(currentParty.map(row=>row.actor)).size!==party.length)throw Error('Party registry changed');
   const native=[];
   for(const p of party){
    const row=currentParty.find(row=>row.actor===p.actor&&row.vtable===p.actorVtable);
    if(!row)throw Error('Party actor lifetime changed');
    const a=ptr(p.actor),info=a.add(0x3dec).readPointer();
    if(!a.add(0x32bc).readPointer().equals(a)||String(info)!==p.info||
     (p.player>=0&&!info.equals(gs.add(p.player?0xa7ec0:0xa76d0))))throw Error('Party self/Info identity changed');
    if(p.player<0)continue;
    const vocation=info.add(0x10).readU8(),primary=info.add(0x14).readU32();
    if(vocation!==2||primary!==0x04000000)throw Error('Both actors must remain Strider/dagger');
    const object=a.add(0x2dc8).readPointer(),stamina=info.add(0x2a8).readFloat();
    if(!Number.isFinite(stamina)||stamina<0||row.pos.length!==3||!row.pos.every(Number.isFinite))throw Error('Nonfinite native resources/position');
    native.push({...p,vocation,primary,action:a.add(0x2dd4).readU32(),object:String(object),
     vtable:object.isNull()?null:String(object.readPointer()),held:a.add(0x32e4).readU32(),
     pending:a.add(0x32f0).readU32(),mode:a.add(0x32c0).readU32(),pos:row.pos,stamina,frames:r.actors[p.player].frames});
    if(!a.add(0x3dec).readPointer().equals(info)||!a.add(0x32bc).readPointer().equals(a))throw Error('Actor changed during native read');
   }
   for(let who=0;who<2;++who){
    if(!r.actors[who].observed)throw Error('Player callback not observed');
    if(r.actors[who].frames!==lastFrames[who]){lastFrames[who]=r.actors[who].frames;lastAdvance[who]=time;}
    else if(time-lastAdvance[who]>limits.frameStallMs)throw Error('Player '+who+' callback frames stalled');
   }
   guard(runtimeStatus());if(splitStatus().faults)throw Error('Split fault during sample');
   if(e.rows.length>=limits.maxRows)throw Error('Sample count bound');
   const row={time,elapsedMs:time-e.started,phase:e.phases.at(-1)?.name??'admission',runtime:r,split:s,native,consistent:true};
   e.rows.push(row);return row;
  };
  const enterPhase=()=>{
   const [name,pad,ms]=phases[index++];phaseStarted=Date.now();
   e.phases.push({name,time:phaseStarted,durationMs:ms,pad:{...pad}});
   globalThis.testDevices=[{connected:true},{connected:true},{},{}];testDevices[player]={connected:true,...pad};setDevices(testDevices);
  };
  // Reject wrong fixtures without publishing provider input or claiming a run.
  const before=sample();
  if(before.native.some(a=>a.action!==0||a.held!==0||a.pending!==0||a.mode!==0))throw Error('Both players must begin native idle/neutral');
  globalThis.striderDodgeTrial=e;globalThis.stopStriderDodgeTrial=stop;e.running=true;
  try{
   enterPhase();
   timer=setInterval(()=>{
    if(!e.running)return;
    try{
     sample();
     if(Date.now()-phaseStarted>=phases[index-1][2]){
      if(index===phases.length){stop('complete');return;}enterPhase();
     }
    }catch(error){e.errors.push(String(error));stop('error');}
   },limits.sampleMs);
   deadline=setTimeout(()=>{if(e.running){e.errors.push('Overall trial deadline');stop('deadline');}},limits.deadlineMs);
  }catch(error){e.errors.push(String(error));stop('startup-error');throw error;}
  return {started:e.running,pid:Process.id,player,durationMs:duration,limits,hooks:0};
 };
 return {ready:true,automaticInput:false,automaticCollection:false,hooks:0};
})();

scripts/Backup-Saves.ps1.text:
$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path -Parent $PSScriptRoot
if (Get-Process DDDA -ErrorAction SilentlyContinue) { throw 'Close DDDA before taking a consistent save backup.' }
$gameRoot = Split-Path -Parent $projectRoot
$steamRoot = Split-Path -Parent (Split-Path -Parent (Split-Path -Parent $gameRoot))
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss-fff'
$destination = Join-Path $projectRoot "private\save-backups\$stamp"
$records = @()
foreach ($account in Get-ChildItem -LiteralPath (Join-Path $steamRoot 'userdata') -Directory) {
    $remote = Join-Path $account.FullName '367500\remote'
    if (!(Test-Path -LiteralPath $remote)) { continue }
    foreach ($save in Get-ChildItem -LiteralPath $remote -File -Filter '*.sav') {
        $outDir = Join-Path $destination $account.Name
        New-Item -ItemType Directory -Path $outDir -Force | Out-Null
        $copy = Join-Path $outDir $save.Name
        $before = (Get-FileHash -LiteralPath $save.FullName -Algorithm SHA256).Hash
        Copy-Item -LiteralPath $save.FullName -Destination $copy
        $after = (Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash
        $sourceAfter = (Get-FileHash -LiteralPath $save.FullName -Algorithm SHA256).Hash
        if ($before -ne $after -or $before -ne $sourceAfter) { throw 'Save changed or backup verification failed.' }
        $records += [pscustomobject]@{ source=$save.FullName; backup=$copy; sha256=$after; bytes=$save.Length }
    }
}
if ($records.Count -eq 0) { Write-Output 'No Steam DDDA save found. Create an AI test fixture before runtime work.'; exit 0 }
$records | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $destination 'manifest.json') -Encoding utf8
Write-Output "Verified $($records.Count) save backup(s) in private/save-backups/$stamp."

scripts/Invoke-Ghidra.ps1.text:
param([switch]$Analyze, [string]$PostScript = '', [string[]]$ScriptArguments = @(), [switch]$Reimport)
$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path -Parent $PSScriptRoot
$java = Get-ChildItem -LiteralPath (Join-Path $projectRoot '.tools\jdk21') -Filter java.exe -Recurse | Select-Object -First 1 -ExpandProperty FullName
$properties = Get-ChildItem -LiteralPath (Join-Path $projectRoot '.tools\ghidra') -Filter launch.properties -Recurse | Select-Object -First 1 -ExpandProperty FullName
if (!$java -or !$properties) { throw 'Bootstrap Ghidra and Java first.' }
$ghidra = Split-Path -Parent (Split-Path -Parent $properties)
$projects = Join-Path $projectRoot 'private\ghidra'
$temp = Join-Path $projectRoot 'private\ghidra-temp'
$logDir = Join-Path $projectRoot 'artifacts\environment'
foreach ($dir in @($projects,$temp,$logDir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
# Same main classes and VM options as the shipped launch.bat. Direct invocation
# avoids cmd.exe's parentheses parsing and short-path canonicalization problems.
$vmArgs = @(Get-Content -LiteralPath $properties | Where-Object { $_ -match '^VMARGS(?:_WINDOWS)?=' } | ForEach-Object { ($_ -split '=', 2)[1] })
$arguments = $vmArgs + @('-Xmx3G', '-XX:ParallelGCThreads=2', '-XX:CICompilerCount=2', "-Djava.io.tmpdir=$temp", "-Duser.home=$env:USERPROFILE", '-cp', (Join-Path $ghidra 'Ghidra\Framework\Utility\lib\Utility.jar'), 'ghidra.Ghidra', 'ghidra.app.util.headless.AnalyzeHeadless', $projects, 'DDDA')
if ((Test-Path -LiteralPath (Join-Path $projects 'DDDA.gpr')) -and !$Reimport) { $arguments += @('-process', 'DDDA.exe') }
else { $arguments += @('-import', (Join-Path (Split-Path -Parent $projectRoot) 'DDDA.exe'), '-overwrite') }
$arguments += @('-log', (Join-Path $logDir 'ghidra-import.log'), '-max-cpu', '4', '-analysisTimeoutPerFile', '1200')
if (!$Analyze) { $arguments += '-noanalysis' }
if ($PostScript) { $arguments += @('-scriptPath', (Join-Path $projectRoot 'scripts\ghidra'), '-postScript', $PostScript) + $ScriptArguments }
& $java @arguments
if ($LASTEXITCODE -ne 0) { throw 'Ghidra headless import failed.' }

