def closed():
    result = subprocess.run(['tasklist', '/FI', 'IMAGENAME eq DDDA.exe', '/FO', 'CSV', '/NH'], capture_output=True, text=True, check=True)
    if '"DDDA.exe"' in result.stdout: raise RuntimeError('Close DDDA before changing runtime files')

def install(game, configuration, developer, settings=None):
    closed()
    if digest(game / 'DDDA.exe') != EXPECTED: raise RuntimeError('Unsupported executable')
    if any((game / name).exists() for name in (*FILES, MANIFEST)):
        raise RuntimeError('Existing runtime/proxy/config/manifest: refusing to overwrite. Roll back the owned deployment first.')
    payloads = {name: (ROOT / 'build/win32' / configuration / name).read_bytes() for name in FILES[:2]}
    template = (settings or ROOT / 'config/ddcoop.ini').read_text(encoding='utf-8')
    if developer and template.count('developer_input=0') != 1:
        raise RuntimeError('Research template must contain exactly one developer_input=0 entry')
    payloads['ddcoop.ini'] = template.replace('developer_input=0', f'developer_input={int(developer)}').encode('utf-8')
    manifest = {'version': 1, 'kind': 'internal research, not release', 'game': str(game), 'exe_sha256': EXPECTED,
                'files': {name: hashlib.sha256(data).hexdigest() for name, data in payloads.items()}}
    # Exclusive creation prevents a race from overwriting a third-party file.
    written = []
    try:
        for name, data in payloads.items():
            with (game / name).open('xb') as f: f.write(data)
            written.append(name)
            if digest(game / name) != manifest['files'][name]: raise RuntimeError('Copy verification failed')
        with (game / MANIFEST).open('x', encoding='utf-8') as f: json.dump(manifest, f, indent=2)
    except Exception:
        for name in written:
            if digest(game / name) == manifest['files'][name]: (game / name).unlink()
        raise
    print(json.dumps(manifest, indent=2))

def rollback(game):
    closed()
    path = game / MANIFEST
    m = json.loads(path.read_text(encoding='utf-8'))
    if Path(m['game']).resolve() != game or set(m['files']) != set(FILES): raise RuntimeError('Invalid deployment ownership')
    for name, sha in m['files'].items():
        if digest(game / name) != sha: raise RuntimeError(f'{name} changed; rollback refuses to remove it')
    for name in FILES: (game / name).unlink()
    path.unlink()
    print('Removed only three verified manifest-owned runtime files. Game assets and saves untouched.')

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('action', choices=['install','rollback'])
    parser.add_argument('--configuration', choices=['Debug','Release'], default='Debug')
    parser.add_argument('--developer-input', action='store_true')
    parser.add_argument('--settings', type=Path, help='Custom settings template; runtime validates all values at startup')
    args = parser.parse_args()
    game = ROOT.parent.resolve()
    if args.action == 'install': install(game,args.configuration,args.developer_input,args.settings)
    else: rollback(game)

