// Define explicitly inspected code entry points missed by automatic analysis.
// @category DDDA
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
public class DefineResearch extends GhidraScript {
    public void run() throws Exception {
        for (String argument : getScriptArgs()) {
            Address address = toAddr(argument);
            if (getFunctionContaining(address) == null) {
                disassemble(address);
                println("Defined " + createFunction(address, null));
            }
        }
    }
}

