// Private static evidence export for an owned DDDA executable.
// @category DDDA
import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.symbol.Symbol;
import ghidra.program.model.symbol.SymbolIterator;
import ghidra.program.model.symbol.Reference;
import java.io.*;
import java.util.*;

public class ExportResearch extends GhidraScript {
    public void run() throws Exception {
        String[] args = getScriptArgs();
        if (args.length == 0) throw new IllegalArgumentException("output file required");
        LinkedHashSet<Function> functions = new LinkedHashSet<>();
        try (PrintWriter out = new PrintWriter(new File(args[0]), "UTF-8")) {
            out.println("Program: " + currentProgram.getName() + " Language: " + currentProgram.getLanguageID());
            out.println("Function count: " + currentProgram.getFunctionManager().getFunctionCount());
            if (args.length > 1) {
                boolean only = args[1].equals("--only");
                for (int i = only ? 2 : 1; i < args.length; i++) {
                    Address address = toAddr(args[i]);
                    Function f = getFunctionContaining(address);
                    if (f != null) functions.add(f);
                    out.println("ADDRESS " + address + " function=" + f);
                    if (only) continue;
                    for (Reference ref : getReferencesTo(address)) {
                        out.println("  XREF " + ref.getFromAddress() + " " + ref.getReferenceType());
                        Function caller = getFunctionContaining(ref.getFromAddress());
                        if (caller != null) functions.add(caller);
                    }
                }
            } else {
                SymbolIterator symbols = currentProgram.getSymbolTable().getAllSymbols(true);
                while (symbols.hasNext()) {
                    Symbol s = symbols.next();
                    String n = s.getName().toLowerCase();
                    if (!(n.contains("xinput") || n.contains("directinput") || n.equals("connect") || n.contains("internetconnect") || n.contains("httpsendrequest"))) continue;
                    out.println("SYMBOL " + s.getName(true) + " @ " + s.getAddress());
                    for (Reference ref : getReferencesTo(s.getAddress())) {
                        out.println("  XREF " + ref.getFromAddress() + " " + ref.getReferenceType());
                        Function f = getFunctionContaining(ref.getFromAddress());
                        if (f != null) functions.add(f);
                        else for (Reference r2 : getReferencesTo(ref.getFromAddress())) {
                            out.println("    CODE " + r2.getFromAddress());
                            Function caller = getFunctionContaining(r2.getFromAddress());
                            if (caller != null) functions.add(caller);
                        }
                    }
                }
            }
            DecompInterface decomp = new DecompInterface();
            decomp.openProgram(currentProgram);
            for (Function f : functions) {
                out.println("\n===== " + f.getName() + " " + f.getEntryPoint() + " =====");
                DecompileResults result = decomp.decompileFunction(f, 45, monitor);
                if (result.decompileCompleted()) out.println(result.getDecompiledFunction().getC());
                else out.println("DECOMPILE FAILED: " + result.getErrorMessage());
                out.flush();
            }
            decomp.dispose();
        }
        println("Exported research to " + args[0]);
    }
}

