"""Read-only migration preflight and private, hash-verified rollback snapshot.

Never installs, removes, loads or executes a DLL. Never restores a save. A snapshot
is preparation evidence, not authorization to deploy or a compatibility result.
"""
import argparse
import csv
import ctypes
from datetime import datetime, timezone
import hashlib
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import zipfile

ROOT = Path(__file__).resolve().parents[1]
RELEASE = "research/PUBLIC_RELEASE_DELIVERY_1.1.0.json"
PACKAGE = "artifacts/releases/DDDA-Local-Coop-1.1.0-drop-in.zip"
GAME_SHA = "19facc2642f79a09d14ce55eace5f228161f2f8bab60ec67eb3c6196cc6277b8"
PLAYER_FILES = {"dinput8.dll", "ddcoop_runtime.dll", "ddcoop.ini", "README.txt"}
ROOT_SUFFIXES = {".dll", ".ini", ".json", ".asi"}
EXCLUDED_SOURCE_DIRS = {"private", "artifacts", "build", "external", "downloads", ".tools", ".venv", ".git", "nativepc"}
EXCLUDED_SOURCE_SUFFIXES = {".dll", ".exe", ".sav", ".pdb", ".dmp", ".arc", ".lib", ".obj"}


def digest(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def json_write(path, value):
    with Path(path).open("x", encoding="utf-8") as stream:
        json.dump(value, stream, indent=2)
        stream.write("\n")


def require_closed():
    result = subprocess.run(["tasklist", "/FI", "IMAGENAME eq DDDA.exe", "/FO", "CSV", "/NH"],
                            capture_output=True, text=True, check=True)
    if any(row and row[0].lower() == "ddda.exe" for row in csv.reader(io.StringIO(result.stdout))):
        raise RuntimeError("DDDA is running; close it before taking/verifying a migration baseline")


def contained_file(base, relative):
    path = Path(relative)
    if path.is_absolute() or path.drive or ".." in path.parts:
        raise ValueError(f"Unsafe relative path: {relative}")
    target = base / path
    if not target.resolve().is_relative_to(base.resolve()):
        raise ValueError(f"Path escapes snapshot: {relative}")
    return target


def copy_verified(source, destination):
    if source.is_symlink() or not source.is_file():
        raise ValueError(f"Expected regular source file: {source}")
    before = digest(source)
    destination.parent.mkdir(parents=True, exist_ok=True)
    with source.open("rb") as src, destination.open("xb") as dst:
        shutil.copyfileobj(src, dst)
    if digest(destination) != before or digest(source) != before:
        raise RuntimeError(f"Source changed or backup verification failed: {source}")
    return before


def root_files(game):
    return sorted(p for p in game.iterdir() if p.is_file() and p.suffix.lower() in ROOT_SUFFIXES)


def save_files(steam):
    result = []
    userdata = steam / "userdata"
    if userdata.is_dir():
        for account in sorted(userdata.iterdir()):
            remote = account / "367500" / "remote"
            if remote.is_dir():
                result.extend(sorted(p for p in remote.rglob("*") if p.is_file()))
    return result  # Includes numbered backups, not only *.sav.


def check_package(path, release):
    current = release.get("public_archive")
    if current:
        if Path(current["zip"]).name != path.name:
            raise ValueError("Accepted archive name mismatch")
        expected, pins = current["sha256"], current["members"]
    else:
        expected = release["packages"][path.name]["sha256"]
        pins = release["compact_package_revision"]["payload_sha256"]
    if digest(path) != expected:
        raise ValueError("Accepted archive hash mismatch")
    with zipfile.ZipFile(path) as archive:
        names = archive.namelist()
        if len(names) != 4 or set(names) != PLAYER_FILES:
            raise ValueError("Accepted archive must contain exactly the four pinned player files")
        for name in names:
            if hashlib.sha256(archive.read(name)).hexdigest() != pins[name]:
                raise ValueError(f"Accepted payload hash mismatch: {name}")
    return pins


def classify_loaders(hashes, pins):
    return {
        "dinput8": "accepted-coop-1.1.0" if hashes.get("dinput8.dll") == pins["dinput8.dll"]
        else "absent" if "dinput8.dll" not in hashes else "unknown-preserve",
        "xinput1_3": "occupied-preserve" if "xinput1_3.dll" in hashes else "available-at-snapshot",
        "runtime_matches_accepted": hashes.get("ddcoop_runtime.dll") == pins["ddcoop_runtime.dll"],
        "settings_match_accepted": hashes.get("ddcoop.ini") == pins["ddcoop.ini"],
        "deployment_allowed": False,
    }


def pe_inventory(path):
    import pefile  # Pinned project dependency; this parses bytes, never loads the DLL.
    with pefile.PE(str(path)) as pe:
        return {
            "path": str(path), "sha256": digest(path), "machine": hex(pe.FILE_HEADER.Machine),
            "imports": {entry.dll.decode("ascii"): [symbol.name.decode("ascii") if symbol.name else
                         f"ordinal:{symbol.ordinal}" for symbol in entry.imports]
                        for entry in getattr(pe, "DIRECTORY_ENTRY_IMPORT", [])},
            "exports": [{"ordinal": symbol.ordinal,
                         "name": symbol.name.decode("ascii") if symbol.name else None,
                         "forwarder": symbol.forwarder.decode("ascii") if symbol.forwarder else None}
                        for symbol in getattr(getattr(pe, "DIRECTORY_ENTRY_EXPORT", None), "symbols", [])],
        }


def system_xinput():
    # This is an on-disk x86 inventory, NOT the proposed runtime resolver.
    buffer = ctypes.create_unicode_buffer(32768)
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel.GetSystemDirectoryW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint]
    kernel.GetSystemDirectoryW.restype = ctypes.c_uint
    count = kernel.GetSystemDirectoryW(buffer, len(buffer))
    if not count or count >= len(buffer) or not buffer.value:
        raise RuntimeError("Cannot locate the architecture-correct system directory")
    directory = Path(buffer.value)
    # Inventory runs in 64-bit Python here; SysWOW64 holds the x86 binary.
    # On a 32-bit Windows installation use System32. Verify PE Machine below.
    wow64 = directory.parent / "SysWOW64"
    path = (wow64 if wow64.is_dir() else directory) / "xinput1_3.dll"
    if not path.is_absolute():
        raise RuntimeError("System inventory path must be absolute")
    if pe_inventory(path)["machine"] != "0x14c":
        raise RuntimeError("Inventory backend is not x86")
    return path


def git(root, *arguments):
    return subprocess.check_output(["git", "-C", str(root), *arguments])


def source_names(root):
    return sorted(set(name.decode("utf-8") for name in
                      git(root, "ls-files", "-c", "-o", "--exclude-standard", "-z").split(b"\0") if name))


def verify_sources(root, records, names):
    if source_names(root) != names:
        raise RuntimeError("Source membership changed during capture")
    expected_present = {record["path"] for record in records}
    if {name for name in names if contained_file(root, name).exists()} != expected_present:
        raise RuntimeError("Source presence changed during capture")
    for record in records:
        path = contained_file(root, record["path"])
        if not path.is_file() or digest(path) != record["sha256"]:
            raise RuntimeError(f"Source changed during capture: {record['path']}")


def snapshot_sources(root, destination):
    names = source_names(root)
    records = []
    with zipfile.ZipFile(destination, "x", compression=zipfile.ZIP_DEFLATED) as archive:
        for name in names:
            path = contained_file(root, name)
            if not path.exists():
                continue  # Git status records tracked deletions; don't resurrect them.
            resolved = path.resolve().relative_to(root.resolve())
            if any(part.lower() in EXCLUDED_SOURCE_DIRS for part in (*Path(name).parts, *resolved.parts)) or path.suffix.lower() in EXCLUDED_SOURCE_SUFFIXES or resolved.suffix.lower() in EXCLUDED_SOURCE_SUFFIXES:
                raise ValueError(f"Private/binary file in source inventory: {name}")
            if path.is_symlink() or not path.is_file():
                raise ValueError(f"Non-regular source entry: {name}")
            data = path.read_bytes()
            sha = hashlib.sha256(data).hexdigest()
            archive.writestr(name, data)
            if digest(path) != sha:
                raise RuntimeError(f"Source changed during capture: {name}")
            records.append({"path": name, "sha256": sha})
    with zipfile.ZipFile(destination) as archive:
        for record in records:
            if hashlib.sha256(archive.read(record["path"])).hexdigest() != record["sha256"]:
                raise RuntimeError("Source archive verification failed")
    verify_sources(root, records, names)
    return records


def snapshot(root, output, release_path=None, package_path=None):
    require_closed()
    root, output = root.resolve(), output.resolve()
    if not output.is_relative_to((root / "private").resolve()) or output == (root / "private").resolve():
        raise ValueError("Snapshot output must be a NEW directory inside coop-mod/private")
    game = root.parent
    steam = game.parents[2]
    graphics = Path(os.environ["LOCALAPPDATA"]) / "CAPCOM/DRAGONS DOGMA DARK ARISEN/config.ini"
    release_path = root / (release_path or RELEASE)
    release = json.loads(release_path.read_text(encoding="utf-8-sig"))
    package_path = root / (package_path or release.get("public_archive", {}).get("zip", PACKAGE))
    pins = check_package(package_path, release)
    if digest(game / "DDDA.exe") != GAME_SHA:
        raise ValueError("Unsupported executable; no migration baseline created")
    saves = save_files(steam)
    if not saves or not graphics.is_file():
        raise ValueError("Save/graphics baseline missing; resolve before migration preparation")
    original_head = git(root, "rev-parse", "HEAD")
    original_status = git(root, "status", "--short")
    original_names = source_names(root)
    output.mkdir(parents=True, exist_ok=False)
    records = []

    def capture(source, relative, kind):
        sha = copy_verified(source, contained_file(output, relative))
        records.append({"source": str(source), "backup": relative, "kind": kind,
                        "sha256": sha, "bytes": source.stat().st_size})

    installed = root_files(game)
    for path in installed:
        if path.name.lower() != "steam_api.dll":
            capture(path, "installed/" + path.name, "installed")
    for path in saves:
        capture(path, "saves/" + path.relative_to(steam / "userdata").as_posix(), "save")
    capture(graphics, "graphics/config.ini", "graphics")
    capture(package_path, "release/" + package_path.name, "accepted-package")
    capture(release_path, "release/delivery.json", "release-evidence")
    source_records = snapshot_sources(root, output / "source.zip")
    (output / "source-git-status.txt").write_bytes(original_status)
    (output / "source-working.diff").write_bytes(git(root, "diff", "--binary", "HEAD"))
    hashes = {p.name.lower(): digest(p) for p in installed}
    backend = system_xinput()
    inventory = {"game": pe_inventory(game / "DDDA.exe"), "system_xinput": pe_inventory(backend),
                 "accepted_release": release.get("version"),
                 "reference_head": git(root / "external/ddda-dinput8", "rev-parse", "HEAD").decode().strip(),
                 "reference_status": git(root / "external/ddda-dinput8", "status", "--short").decode(),
                 "reference_ini_sha256": digest(root / "external/ddda-dinput8/dinput8.ini"),
                 "installed_root_hashes": hashes, "loader_preflight": classify_loaders(hashes, pins)}
    if inventory["loader_preflight"]["dinput8"] == "accepted-coop-1.1.0":
        inventory["loader_preflight"]["dinput8"] = "accepted-coop-" + release.get("version", "unknown")
    json_write(output / "inventory.json", inventory)
    json_write(output / "source-hashes.json", source_records)
    for record in records:
        if digest(Path(record["source"])) != record["sha256"]:
            raise RuntimeError(f"Live file changed during capture: {record['source']}")
    if installed != root_files(game) or saves != save_files(steam):
        raise RuntimeError("Installed files or saves changed during capture")
    verify_sources(root, source_records, original_names)
    if git(root, "rev-parse", "HEAD") != original_head or git(root, "status", "--short") != original_status:
        raise RuntimeError("Git HEAD/status changed during capture")
    require_closed()
    manifest = {"schema": 1, "kind": "ddcoop-loader-migration-preparation", "utc": datetime.now(timezone.utc).isoformat(),
                "game": str(game), "steam": str(steam), "git_head": original_head.decode().strip(),
                "files": records, "root_members": [p.name for p in installed], "save_members": [str(p) for p in saves],
                "identity_only": [{"source": str(game / name), "sha256": digest(game / name)}
                                  for name in ("DDDA.exe", "steam_api.dll")],
                "snapshot_files": {name: digest(output / name) for name in
                                   ("source.zip", "source-hashes.json", "source-git-status.txt", "source-working.diff", "inventory.json")},
                "deployment_allowed": False, "live_compatibility_tested": False}
    json_write(output / "manifest.json", manifest)  # A partial directory never receives a success manifest.
    return verify(output, check_live=True)


def verify(snapshot_dir, check_live=False):
    manifest = json.loads((snapshot_dir / "manifest.json").read_text(encoding="utf-8"))
    if manifest.get("schema") != 1 or manifest.get("kind") != "ddcoop-loader-migration-preparation":
        raise ValueError("Unknown migration snapshot schema/kind")
    if check_live:
        require_closed()
    issues = []
    for name, sha in manifest["snapshot_files"].items():
        path = contained_file(snapshot_dir, name)
        if not path.is_file() or digest(path) != sha:
            issues.append(f"snapshot changed: {name}")
    for record in manifest["files"]:
        backup = contained_file(snapshot_dir, record["backup"])
        if not backup.is_file() or digest(backup) != record["sha256"]:
            issues.append(f"backup changed: {record['backup']}")
        if check_live:
            live = Path(record["source"])
            if not live.is_file() or digest(live) != record["sha256"]:
                issues.append(f"live changed: {live}")
    if check_live:
        for record in manifest["identity_only"]:
            path = Path(record["source"])
            if not path.is_file() or digest(path) != record["sha256"]:
                issues.append(f"identity changed: {path}")
        if [p.name for p in root_files(Path(manifest["game"]))] != manifest["root_members"]:
            issues.append("game root file membership changed")
        if [str(p) for p in save_files(Path(manifest["steam"]))] != manifest["save_members"]:
            issues.append("save membership changed")
        require_closed()
    return {"ok": not issues, "checked_live": check_live, "backed_up_files": len(manifest["files"]),
            "save_files": sum(r["kind"] == "save" for r in manifest["files"]),
            "manifest_sha256": digest(snapshot_dir / "manifest.json"), "issues": issues,
            "deployment_allowed": False, "live_compatibility_tested": False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    take = commands.add_parser("snapshot")
    take.add_argument("--out", type=Path, required=True)
    take.add_argument("--release", type=Path, help="Accepted delivery JSON; defaults to historical 1.1.0")
    take.add_argument("--package", type=Path, help="Explicit accepted ZIP, otherwise use the delivery record")
    check = commands.add_parser("verify")
    check.add_argument("snapshot", type=Path)
    check.add_argument("--check-live", action="store_true")
    args = parser.parse_args()
    result = snapshot(ROOT, args.out, args.release, args.package) if args.command == "snapshot" else verify(args.snapshot, args.check_live)
    print(json.dumps(result, indent=2))
    return 0 if result["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

scripts/research_export.py.text:
"""Export stopped research objects in bounded RPC chunks, preserving JS timers.

Do not issue other research IPC commands while this exporter runs. Objects must
have running=false. Arrays are read in small slices instead of blocking Frida's
JS thread while serializing a whole multi-megabyte trace.
"""
import argparse
import json
from pathlib import Path
import re
import time
import uuid

ROOT = Path(__file__).resolve().parents[1]
IPC = ROOT / 'private/research/session'


def request(source):
    identifier = str(uuid.uuid4())
    temp = IPC / 'command.tmp'
    temp.write_text(json.dumps(dict(id=identifier, action='evaluate', source=source)))
    # Windows can briefly deny replacement while the host reads this file.
    # Retry the same unpublished request; do not issue a second request ID.
    publish_deadline = time.monotonic() + 2
    while True:
        try:
            temp.replace(IPC / 'command.json')
            break
        except PermissionError:
            if time.monotonic() >= publish_deadline: raise
            time.sleep(.05)
    deadline = time.monotonic() + 25
    while time.monotonic() < deadline:
        try:
            response = json.loads((IPC / 'result.json').read_text())
            if response['id'] == identifier:
                if not response['ok']: raise RuntimeError(response.get('error', 'RPC failed'))
                return response['value']
        except (PermissionError, FileNotFoundError, json.JSONDecodeError):
            pass
        time.sleep(.05)
    raise TimeoutError('Export RPC timed out; inspect the existing host before retrying')


def export(objects, out, chunk):
    key = '_export_' + uuid.uuid4().hex
    refs = {}
    for spec in objects:
        alias, name = spec.split('=', 1)
        if not all(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', x) for x in (alias, name)):
            raise ValueError('Objects must be alias=globalIdentifier')
        if alias in refs: raise ValueError('Duplicate alias')
        refs[alias] = name
    if out.exists(): raise FileExistsError(out)
    started = time.monotonic()
    before = request('runtimeStatus()')
    try:
        metadata = request('''(() => {
 const refs=REFS, result={}; globalThis[KEY]={};
 for(const [alias,name] of Object.entries(refs)) {
  const object=globalThis[name];
  if(!object || object.running!==false)throw Error('Stopped object required: '+name);
  const scalars={},arrays={};
  for(const [k,v] of Object.entries(object)) {if(Array.isArray(v))arrays[k]=v.length;else scalars[k]=v;}
  globalThis[KEY][alias]=object;result[alias]={scalars,arrays};
 }return result;
})()'''.replace('KEY', json.dumps(key)).replace('REFS', json.dumps(refs)))
        result = {}
        for alias, meta in metadata.items():
            result[alias] = meta['scalars']
            for field, count in meta['arrays'].items():
                rows = []
                expression = f'globalThis[{json.dumps(key)}][{json.dumps(alias)}][{json.dumps(field)}]'
                for offset in range(0, count, chunk):
                    rows.extend(request(f'{expression}.slice({offset},{min(count, offset+chunk)})'))
                if len(rows) != count or request(f'{expression}.length') != count:
                    raise RuntimeError('Array changed during stopped export')
                result[alias][field] = rows
        after = request('runtimeStatus()')
        with out.open('x') as f:
            json.dump(dict(ok=True, value=result, export=dict(chunk=chunk, before=before, after=after,
                      seconds=time.monotonic()-started)), f, indent=2)
        print(json.dumps(dict(out=str(out), seconds=time.monotonic()-started,
                              generation_before=before['generation'], generation_after=after['generation'],
                              session_before=before['session'], session_after=after['session'])))
    finally:
        request(f'delete globalThis[{json.dumps(key)}]')


if __name__ == '__main__':
    p = argparse.ArgumentParser(); p.add_argument('--object', action='append', required=True)
    p.add_argument('--out', type=Path, required=True); p.add_argument('--chunk', type=int, default=32)
    args = p.parse_args()
    if not 1 <= args.chunk <= 64: p.error('chunk must be 1..64')
    export(args.object, args.out, args.chunk)

