"""Bounded, hash-locked DDDA research host. Pins offline guard before game resume.

Commands are local files created by research_command.py. Never opens a network port.
No gameplay write occurs unless an explicitly authored research script performs it.
"""
from pathlib import Path
import hashlib
import json
import time
import frida
import argparse

ROOT = Path(__file__).resolve().parents[1]
GAME = ROOT.parent
IPC = ROOT / "private/research/session"
IPC.mkdir(parents=True, exist_ok=True)
EXE_HASH = "19facc2642f79a09d14ce55eace5f228161f2f8bab60ec67eb3c6196cc6277b8"
if hashlib.sha256((GAME / "DDDA.exe").read_bytes()).hexdigest() != EXE_HASH:
    raise RuntimeError("Unknown executable; research launch refused")
device = frida.get_local_device()
p = argparse.ArgumentParser()
p.add_argument('--reattach', action='store_true')
p.add_argument('--runtime', action='store_true', help='Test the C++ runtime instead of S1 JavaScript hooks')
p.add_argument('--proxy-start', action='store_true', help='Let the deployed proxy initialize the runtime; do not inject it')
p.add_argument('--player-install', action='store_true', help='Observe an installed player package with explicit runtime/settings pins')
p.add_argument('--runtime-sha256')
p.add_argument('--settings-sha256')
args = p.parse_args()
if args.proxy_start and (not args.runtime or args.reattach):
    p.error('--proxy-start requires --runtime and a fresh launch')
if args.player_install and (not args.proxy_start or not args.runtime_sha256 or not args.settings_sha256):
    p.error('--player-install requires --proxy-start and exact runtime/settings SHA-256 pins')
if not args.player_install and (args.runtime_sha256 or args.settings_sha256):
    p.error('Explicit player pins require --player-install')
# Validate ownership before spawning, so a missing/wrong manifest cannot create
# even a suspended game process. Player settings are intentionally user-editable.
if args.proxy_start:
    manifest_path=GAME/('ddcoop-install.json' if args.player_install else 'ddcoop-deployment.json')
    manifest=json.loads(manifest_path.read_text(encoding='utf-8-sig'))
    loader='dinput8.dll'
    if args.player_install:
        if manifest.get('schema')==2 and manifest.get('kind')=='ddcoop-xinput-install':
            if manifest.get('loader_kind')!='xinput1_3' or manifest.get('loader_name')!='xinput1_3.dll':
                raise RuntimeError('Invalid XInput loader identity')
            loader='xinput1_3.dll'
        elif manifest.get('kind')!='ddcoop-player-install':
            raise RuntimeError('Unknown player installation kind')
        if Path(manifest['game']).resolve()!=GAME.resolve() or set(manifest['files'])!={loader,'ddcoop_runtime.dll'}:
            raise RuntimeError('Invalid player installation ownership')
        if manifest['files']['ddcoop_runtime.dll']!=args.runtime_sha256:
            raise RuntimeError('Player runtime pin mismatch')
        if hashlib.sha256((GAME/'ddcoop.ini').read_bytes()).hexdigest()!=args.settings_sha256:
            raise RuntimeError('Player settings pin mismatch')
    for name, sha in manifest['files'].items():
        if name not in {loader,'ddcoop_runtime.dll','ddcoop.ini'} or hashlib.sha256((GAME/name).read_bytes()).hexdigest()!=sha:
            raise RuntimeError('Deployment ownership check failed')
existing = [p for p in device.enumerate_processes() if p.name.lower() == 'ddda.exe']
if args.reattach:
    recorded = json.loads((IPC / 'status.json').read_text())
    if len(existing) != 1 or existing[0].pid != recorded['pid']:
        raise RuntimeError('Only the recorded guarded research process can be reattached')
    pid = recorded['pid']
elif existing:
    raise RuntimeError("A DDDA process is already running; refuse ambiguous attachment")
else:
    pid = device.spawn(str(GAME / "DDDA.exe"), cwd=str(GAME), env={"SteamAppId": "367500", "SteamGameId": "367500"})
session = device.attach(pid)
alive = True
def detached(reason, crash=None):
    global alive
    alive = False
    print(json.dumps({"detached": reason, "crash": str(crash) if crash else None}), flush=True)
session.on("detached", detached)
guard_name = 'ddcoop_runtime.dll' if args.runtime else 'ddcoop_network_guard.dll'
guard_path = str(GAME / guard_name) if args.runtime else str(ROOT / 'build/win32/Debug' / guard_name)
agent = """
if (Process.arch !== 'ia32' || Process.mainModule.base.toString() !== '0x400000') throw new Error('Unsupported image architecture/base');
const guard = REATTACH ? Process.getModuleByName(GUARD_NAME) : Module.load(GUARD_PATH);
const ensure = new NativeFunction(guard.getExportByName(ENSURE_NAME), 'int', [], 'mscdecl');
const offline = new NativeFunction(guard.getExportByName('OfflineState'), 'int', [], 'mscdecl');
const blocked = new NativeFunction(guard.getExportByName('OfflineBlockedCalls'), 'uint', [], 'mscdecl');
if (ensure() !== 1 || offline() !== 2) throw new Error('Offline guard failed');
const ws = Process.getModuleByName('ws2_32.dll');
const startup = new NativeFunction(ws.getExportByName('WSAStartup'), 'int', ['uint','pointer'], 'stdcall');
const sock = new SystemFunction(ws.getExportByName('socket'), 'uint', ['int','int','int'], 'stdcall');
const cleanup = new NativeFunction(ws.getExportByName('WSACleanup'), 'int', [], 'stdcall');
if (startup(0x202, Memory.alloc(512)) !== 0) throw new Error('WSAStartup self-test failed');
const result = sock(2, 1, 6); cleanup();
if (result.value !== 0xffffffff || result.lastError !== 10050) throw new Error('Offline enforcement self-test failed: ' + JSON.stringify(result));
globalThis.observations = [];
rpc.exports = {
  status() { return { pid: Process.id, arch: Process.arch, base: Process.mainModule.base.toString(), offline: offline(), blocked: blocked() }; },
  evaluate(source) { return (0,eval)(source); }
};
""".replace("GUARD_PATH", json.dumps(guard_path)).replace('GUARD_NAME', json.dumps(guard_name)).replace('ENSURE_NAME', json.dumps('CoopInitialize' if args.runtime else 'EnsureOffline')).replace('REATTACH', str(args.reattach).lower())
script = session.create_script(agent)
script.on("message", lambda message, data: print(json.dumps(message), flush=True))
try:
    if args.proxy_start:
        # Only use a manifest-owned, explicitly enabled deployment. This launch
        # tests bootstrap order, rather than masking it with explicit injection.
        for name, sha in manifest['files'].items():
            if hashlib.sha256((GAME/name).read_bytes()).hexdigest()!=sha:
                raise RuntimeError('Deployment ownership check failed')
        observer=session.create_script("""
rpc.exports.ready=()=>{
 const m=Process.findModuleByName('ddcoop_runtime.dll');if(!m)return false;
 const p=Memory.alloc(132),get=new NativeFunction(m.getExportByName('CoopGetStatus'),'int',['pointer','uint'],'mscdecl');
 return get(p,132)===1 && p.add(8).readS32()===2;
};
rpc.exports.loader=()=>{
 const m=Process.enumerateModules().find(x=>x.name.toLowerCase()==='xinput1_3.dll' && x.findExportByName('CoopLoaderGetStatus'));
 if(!m)return null;
 const p=Memory.alloc(212),get=new NativeFunction(m.getExportByName('CoopLoaderGetStatus'),'int',['pointer','uint'],'mscdecl');
 return get(p,212)===1?{path:m.path,words:Array.from({length:53},(_,i)=>p.add(i*4).readU32())}:null;
};
""")
        observer.load()
        device.resume(pid)
        deadline=time.monotonic()+20
        while time.monotonic()<deadline and not observer.exports_sync.ready(): time.sleep(0.1)
        print(json.dumps({'loader_startup_observation': observer.exports_sync.loader()}), flush=True)
        if not observer.exports_sync.ready(): raise RuntimeError('Proxy did not initialize the runtime')
        observer.unload()
    script.load()
    if not args.runtime:
        script.exports_sync.evaluate((ROOT / 'scripts/research_offline.js').read_text())
    status = script.exports_sync.status()
    if status["arch"] != "ia32" or status["offline"] != 2:
        raise RuntimeError("Research guard handshake failed")
    (IPC / "status.json").write_text(json.dumps(status, indent=2))
    print(json.dumps({"proxy_bootstrap_verified" if args.proxy_start else "ready_before_resume": status}), flush=True)
    if not args.reattach and not args.proxy_start: device.resume(pid)
except Exception:
    if not args.reattach: device.kill(pid)
    raise
# Never replay a previous process's request in a fresh game instance.
prior = IPC / "command.json"
seen = json.loads(prior.read_text())["id"] if prior.exists() else None
try:
    while alive:
        path = IPC / "command.json"
        if path.exists():
            try:
                request = json.loads(path.read_text())
            except (PermissionError, FileNotFoundError, json.JSONDecodeError):
                time.sleep(0.1)
                continue
            if request["id"] != seen:
                seen = request["id"]
                try:
                    if request.get("action") == "status": value = script.exports_sync.status()
                    else: value = script.exports_sync.evaluate(request["source"])
                    response = {"id": seen, "ok": True, "value": value}
                except Exception as e:
                    response = {"id": seen, "ok": False, "error": str(e)}
                tmp = IPC / "result.tmp"
                tmp.write_text(json.dumps(response, indent=2))
                for attempt in range(50):
                    try:
                        tmp.replace(IPC / "result.json")
                        break
                    except PermissionError:
                        if attempt == 49: raise
                        time.sleep(0.1)
        time.sleep(0.1)
finally:
    # The native guard stays pinned if the research transport disconnects.
    if alive:
        session.detach()

