// Research-only native option lock for the exact hash verified by research_host.py.
// Socket enforcement is pinned native code and survives loss of this transport.
(() => {
 if(globalThis.offlineHooks) return {installed:true,alreadyPresent:true};
 const points=[['0x4990e0','d94004d99960e72000'],['0x499140','d98160e72000d95804'],['0x469720','8a81450500003c02'],['0x469510','53568bf08bce']];
 for(const [va,hex] of points){const actual=Array.from(new Uint8Array(ptr(va).readByteArray(hex.length/2))).map(b=>b.toString(16).padStart(2,'0')).join('');if(actual!==hex)throw new Error('Native offline signature mismatch at '+va);}
 globalThis.nativeOffline={getterCalls:0,setterCalls:0,queryCalls:0,connectionCalls:0,cleared:0,errors:0};
 // Match the native offline-complete branch, not just its visible mode byte.
 function stateOffline(){const net=ptr('0x18d0cc4').readPointer();if(!net.isNull()){net.add(0x545).writeU8(1);net.add(0x5a2e).writeU8(1);net.add(0x534).writeU8(0xff);}}
 function clear(save){
  if(save.isNull()||save.readPointer().toString()!=='0x1561750')return false;
  const option=save.add(0x20e75c);
  if(option.readPointer().toString()!=='0x15617d4')return false;
  const f=option.add(0x18),v=f.readU32();
  if(v&0x1000){f.writeU32(v&~0x1000);nativeOffline.cleared++;}
  return true;
 }
 globalThis.offlineHooks=[
  Interceptor.attach(ptr('0x4990e0'),{onEnter(){
   nativeOffline.setterCalls++;
   try{if(!clear(this.context.ecx))throw new Error('save identity');const src=this.context.eax;if(src.readPointer().toString()!=='0x15617d4')throw new Error('option identity');src.add(0x18).writeU32(src.add(0x18).readU32()&~0x1000);}catch(e){nativeOffline.errors++;}
  },onLeave(){try{stateOffline();}catch(e){nativeOffline.errors++;}}}),
  Interceptor.attach(ptr('0x499140'),{onEnter(){nativeOffline.getterCalls++;try{if(!clear(this.context.ecx))nativeOffline.errors++;}catch(e){nativeOffline.errors++;}}}),
  Interceptor.attach(ptr('0x469720'),{onEnter(){nativeOffline.queryCalls++;try{clear(ptr('0x18fa4f8').readPointer());stateOffline();}catch(e){nativeOffline.errors++;}},onLeave(ret){ret.replace(0);}}),
  Interceptor.attach(ptr('0x469510'),{onEnter(args){nativeOffline.connectionCalls++;this.valid=this.context.eax.equals(ptr('0x18d0cc4').readPointer());if(this.valid)args[0]=ptr(0);else nativeOffline.errors++;},onLeave(){if(this.valid)try{clear(ptr('0x18fa4f8').readPointer());stateOffline();}catch(e){nativeOffline.errors++;}}})
 ];
 return {installed:true,scope:'native option get/set and online-state query; not all inlined state reads',note:'socket guard remains mandatory'};
})()

