"""Read-only PE address/string/reference helper for local DDDA research."""
from pathlib import Path
import argparse, re, struct
import pefile
from capstone import Cs, CS_ARCH_X86, CS_MODE_32
exe = Path(__file__).resolve().parents[2] / 'DDDA.exe'
pe = pefile.PE(str(exe))
raw = exe.read_bytes()
base = pe.OPTIONAL_HEADER.ImageBase
p = argparse.ArgumentParser()
p.add_argument('action', choices=['disasm','refs','strings','bytes'])
p.add_argument('value')
p.add_argument('--size',type=lambda n:int(n,0),default=256)
args = p.parse_args()
if args.action == 'strings':
    pattern = re.compile(args.value, re.I)
    count = 0
    for match in re.finditer(rb'[ -~]{4,}\x00',raw):
        name=match.group()[:-1].decode()
        if pattern.search(name):
            print(hex(base+pe.get_rva_from_offset(match.start())),name[:240])
            count += 1
            if count >= args.size: break
else:
    va=int(args.value,0)
    if args.action == 'refs':
        key=struct.pack('<I',va)
        for s in pe.sections:
            b=s.get_data()
            for m in re.finditer(re.escape(key),b): print(s.Name.rstrip(b'\0').decode(),hex(base+s.VirtualAddress+m.start()))
    else:
        b=pe.get_data(va-base,args.size)
        if args.action == 'bytes': print(b.hex(' '))
        else:
            for ins in Cs(CS_ARCH_X86,CS_MODE_32).disasm(b,va): print(f'{ins.address:08x} {ins.bytes.hex():20s} {ins.mnemonic:8s} {ins.op_str}')

scripts/verify_dual_loader_release.py.text:
"""Read-only verification for a paired XInput and DirectInput release."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import sys
import zipfile

XINPUT_FILES = ('xinput1_3.dll', 'ddcoop_runtime.dll', 'ddcoop.ini', 'README.txt')
DINPUT_FILES = ('dinput8.dll', 'ddcoop_runtime.dll', 'ddcoop.ini', 'README.txt')
SHA256_PATTERN = re.compile(r'^[0-9a-fA-F]{64}$')


def _object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f'Duplicate JSON key: {key}')
        result[key] = value
    return result


def _digest(raw):
    return hashlib.sha256(raw).hexdigest()


def _read_receipt(path):
    path = Path(path)
    if path.is_symlink() or not path.is_file():
        raise ValueError(f'Receipt must be a regular file: {path}')
    try:
        record = json.loads(path.read_text(encoding='utf-8-sig'), object_pairs_hook=_object)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError(f'Invalid JSON receipt: {path}') from error
    if not isinstance(record, dict):
        raise ValueError(f'Receipt must be a JSON object: {path}')
    return record


def _verify_one(archive_path, receipt_path, kind, package_kind, filename, expected_files):
    archive_path = Path(archive_path)
    if archive_path.is_symlink() or not archive_path.is_file():
        raise ValueError(f'{kind} ZIP must be a regular file: {archive_path}')
    record = _read_receipt(receipt_path)
    if record.get('schema') != 1 or type(record.get('schema')) is not int:
        raise ValueError(f'{kind} receipt schema mismatch')
    if record.get('package_kind') != package_kind:
        raise ValueError(f'{kind} receipt package_kind mismatch')
    if record.get('public_release') is not True:
        raise ValueError(f'{kind} receipt is not an accepted public release')
    if record.get('distribution_status') != 'public-release':
        raise ValueError(f'{kind} receipt distribution_status mismatch')
    if record.get('release_candidate') is not False:
        raise ValueError(f'{kind} receipt release_candidate mismatch')
    version = record.get('version')
    if not isinstance(version, str) or not version:
        raise ValueError(f'{kind} receipt version is missing')
    if record.get('runtime_version') != version:
        raise ValueError(f'{kind} runtime_version does not match package version')
    loader = record.get('loader')
    if (not isinstance(loader, dict) or loader.get('kind') != kind or loader.get('name') != filename or
            loader.get('version') != version):
        raise ValueError(f'{kind} loader identity mismatch')
    acceptance = record.get('acceptance')
    if not isinstance(acceptance, dict) or acceptance.get('status') != 'passed':
        raise ValueError(f'{kind} receipt lacks passed acceptance')
    if not isinstance(loader.get('sha256'), str) or not SHA256_PATTERN.fullmatch(loader['sha256']):
        raise ValueError(f'{kind} loader SHA-256 is invalid')
    runtime_build_id = record.get('runtime_build_id')
    if type(runtime_build_id) is not int or runtime_build_id <= 0:
        raise ValueError(f'{kind} runtime build ID is invalid')
    payload_hashes = record.get('payload_sha256')
    if not isinstance(payload_hashes, dict) or set(payload_hashes) != set(expected_files):
        raise ValueError(f'{kind} payload hash list does not match the four-file allowlist')
    for name, value in payload_hashes.items():
        if not isinstance(value, str) or not SHA256_PATTERN.fullmatch(value):
            raise ValueError(f'{kind} payload SHA-256 is invalid: {name}')
    runtime_sha = payload_hashes['ddcoop_runtime.dll']
    accepted_runtime_sha = acceptance.get('runtime_sha256')
    if not isinstance(accepted_runtime_sha, str) or not SHA256_PATTERN.fullmatch(accepted_runtime_sha):
        raise ValueError(f'{kind} accepted runtime SHA-256 is invalid')
    if (acceptance.get('loader') != loader or accepted_runtime_sha.lower() != runtime_sha.lower() or
            acceptance.get('runtime_version') != version or
            acceptance.get('runtime_build_id') != runtime_build_id or
            acceptance.get('public_redistribution') is not True):
        raise ValueError(f'{kind} accepted record disagrees with package identity')
    archive_hash = record.get('archive_sha256')
    archive_raw = archive_path.read_bytes()
    if not isinstance(archive_hash, str) or not SHA256_PATTERN.fullmatch(archive_hash):
        raise ValueError(f'{kind} archive SHA-256 is missing or invalid')
    if _digest(archive_raw) != archive_hash.lower():
        raise ValueError(f'{kind} archive SHA-256 mismatch')
    try:
        with zipfile.ZipFile(archive_path) as archive:
            infos = archive.infolist()
            names = [info.filename for info in infos]
            if len(names) != len(set(names)):
                raise ValueError(f'{kind} ZIP contains duplicate members')
            if len(names) != len(expected_files) or set(names) != set(expected_files):
                raise ValueError(f'{kind} ZIP members differ from the exact four-file allowlist')
            for info in infos:
                if info.is_dir() or ((info.external_attr >> 16) & 0o170000) == 0o120000:
                    raise ValueError(f'{kind} ZIP contains a non-regular member')
            bad_member = archive.testzip()
            if bad_member is not None:
                raise ValueError(f'{kind} ZIP CRC failure: {bad_member}')
            payloads = {name: archive.read(name) for name in expected_files}
    except zipfile.BadZipFile as error:
        raise ValueError(f'{kind} input is not a valid ZIP archive') from error
    for name, raw in payloads.items():
        if _digest(raw) != payload_hashes[name].lower():
            raise ValueError(f'{kind} payload SHA-256 mismatch: {name}')
    if loader['sha256'].lower() != payload_hashes[filename].lower():
        raise ValueError(f'{kind} loader hash disagrees with its payload hash')
    return dict(path=str(archive_path.resolve()), receipt=str(Path(receipt_path).resolve()),
                archive_sha256=archive_hash.lower(), version=version,
                loader_kind=kind, runtime_sha256=runtime_sha.lower(),
                runtime_build_id=runtime_build_id, ini_sha256=_digest(payloads['ddcoop.ini']),
                payload_sha256={name: payload_hashes[name].lower() for name in expected_files},
                payloads=payloads)


def verify(xinput_zip, xinput_receipt, dinput_zip, dinput_receipt):
    """Verify two independently pinned packages and their shared release identity."""
    xinput = _verify_one(xinput_zip, xinput_receipt, 'xinput1_3', 'xinput-drop-in',
                         'xinput1_3.dll', XINPUT_FILES)
    dinput = _verify_one(dinput_zip, dinput_receipt, 'dinput8', 'dinput8-drop-in',
                         'dinput8.dll', DINPUT_FILES)
    if xinput['version'] != dinput['version']:
        raise ValueError('Paired release version mismatch')
    if (xinput['runtime_sha256'] != dinput['runtime_sha256'] or
            xinput['runtime_build_id'] != dinput['runtime_build_id']):
        raise ValueError('Paired release runtime identity mismatch')
    if xinput['payloads']['ddcoop.ini'] != dinput['payloads']['ddcoop.ini']:
        raise ValueError('Paired release ddcoop.ini bytes mismatch')
    result = dict(status='passed', version=xinput['version'],
                  runtime_sha256=xinput['runtime_sha256'], runtime_build_id=xinput['runtime_build_id'],
                  ini_sha256=xinput['ini_sha256'], xinput={key: value for key, value in xinput.items() if key != 'payloads'},
                  dinput={key: value for key, value in dinput.items() if key != 'payloads'})
    print(json.dumps(result, indent=2))
    return result


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('xinput_zip', type=Path)
    parser.add_argument('xinput_receipt', type=Path)
    parser.add_argument('dinput_zip', type=Path)
    parser.add_argument('dinput_receipt', type=Path)
    try:
        verify(**vars(parser.parse_args()))
    except (OSError, ValueError) as error:
        print(json.dumps(dict(status='failed', error=str(error)), indent=2))
        sys.exit(1)

