void rect(float x,float y,float w,float h,DWORD color) {
    if(draw_clip.width()>0 && draw_clip.height()>0) {
        const float right=std::min(x+w,static_cast<float>(draw_clip.right));
        const float bottom=std::min(y+h,static_cast<float>(draw_clip.bottom));
        x=std::max(x,static_cast<float>(draw_clip.left));y=std::max(y,static_cast<float>(draw_clip.top));
        w=right-x;h=bottom-y;
    }
    if(w<=0 || h<=0 || count+6>vertices.size())return;
    const Vertex a{x-.5f,y-.5f,0,1,color},b{x+w-.5f,y-.5f,0,1,color};
    const Vertex c{x+w-.5f,y+h-.5f,0,1,color},d{x-.5f,y+h-.5f,0,1,color};
    for(const auto& v:{a,b,c,a,c,d})vertices[count++]=v;
}
// Text is queued into a cached antialiased serif layer; geometry stays batched.
void text(float x,float y,float scale,const char* value,DWORD color) {
    queue_hint_text(x,y,scale,value,color);
}
void marker_arrow(const PartnerMarker& marker,float scale,DWORD tint) {
    if(!marker.edge)return;
    const auto triangle=[&](float length,float width,DWORD color) {
        if(count+3>vertices.size())return;
        // Leave the serif role label clear when the partner is behind/below.
        const float offset=23+16*std::max(0.0f,marker.dy);
        const float x=marker.x+marker.dx*offset*scale,y=marker.y+marker.dy*offset*scale;
        vertices[count++]={x+marker.dx*length*scale,y+marker.dy*length*scale,0,1,color};
        vertices[count++]={x-marker.dx*2*scale-marker.dy*width*scale,y-marker.dy*2*scale+marker.dx*width*scale,0,1,color};
        vertices[count++]={x-marker.dx*2*scale+marker.dy*width*scale,y-marker.dy*2*scale-marker.dx*width*scale,0,1,color};
    };
    triangle(7,5,0xec171310);triangle(4.5f,2.8f,tint);
}
const char* channel_name(int spell) {
    switch(spell) {
    case 211:return "Frazil";
    case 217:return "Silentium";
    case 218:return "Blearing";
    case 238:return "Spellscreen";
    case 215:return "Brontide";
    default:return "Spell";
    }
}
const char* projectile_name(int spell) {
    switch(spell) {
    case 210:return "Ingle";
    case 216:return "Grapnel";
    default:return "Spell";
    }
}
const char* boon_name(int spell) {
    switch(spell) {
    case 222:return "Fire Boon";
    case 223:return "Ice Boon";
    case 224:return "Thunder Boon";
    case 225:return "Holy Boon";
    case 226:return "Dark Boon";
    default:return "Boon";
    }
}
player_feedback::Copy notice_copy(const Snapshot& s) {
    const auto unified=player_feedback::copy(static_cast<player_feedback::Notice>(s.player_notice));
    if(*unified.title)return unified;
    if(s.player_notice_managed)return {"Local co-op is running","Player 2: hold START to join"};
    using N=player_feedback::Notice;
    if(s.vocation_notice==1)return player_feedback::copy(N::unsupported_vocation);
    if(s.vocation_notice==2)return {"P2 returned to AI","Waiting for the main pawn or a stable distance"};
    if(s.vocation_notice==3)return player_feedback::copy(N::rejoin);
    switch(s.separation.state) {
    case 1:return player_feedback::copy(settings().distance_action==DistanceAction::teleport?N::stay_close_teleport:N::stay_close);
    case 2:return player_feedback::copy(N::recovering_distance);
    case 3:return {"P2 ready to resume","Release controls to resume"};
    case 4:return player_feedback::copy(N::checking_distance);
    default:return {"Local co-op is running","Player 2: hold START to join"};
    }
}
bool valid_resources(const Resources& r) {
    return r.valid && std::isfinite(r.hp) && std::isfinite(r.hp_max) && std::isfinite(r.hp_white) &&
        std::isfinite(r.stamina) && std::isfinite(r.stamina_max) && r.hp_max>0 && r.stamina_max>0;
}
bool collect_visible(const Snapshot& s) {
    return s.active && s.collect.visible &&
        ((s.collect.kind==1 && settings().p2_npc_interaction) || s.collect.kind==6 || s.collect.kind==10) &&
        !s.palette.mode && !s.aim.visible && !s.boon.visible && !s.ingle.visible &&
        !s.frazil.visible && !s.player_notice && !s.vocation_notice && !s.separation.state;
}
void build_resources(const Snapshot& s,unsigned w,unsigned h,GroundHudStatus& ground,BoonHudStatus& boon,IngleHudStatus& ingle) {
