        native.generation==s.generation && now>=native.last_draw && now-native.last_draw<250;
    // Keep an error fallback, but never overlay the custom box on native bars.
    if(!native_bars) {
    rect(x-12*scale,y-12*scale,292*scale,114*scale,0xcf101519);
    rect(x-12*scale,y-12*scale,3*scale,114*scale,0xffb1c4a0);
    text(x,y,2*scale,"P2  Main pawn",0xffe8e9dc);
    std::snprintf(label,sizeof(label),"HP %.0f / %.0f",std::ceil(r.hp),std::ceil(r.hp_max));
    text(x,y+27*scale,2*scale,label,0xffd9e4d2);
    rect(x,y+46*scale,268*scale,6*scale,0xff343a3a);
    rect(x,y+46*scale,268*scale*std::clamp(r.hp_white/r.hp_max,0.0f,1.0f),6*scale,0xff919a91);
    rect(x,y+46*scale,268*scale*std::clamp(r.hp/r.hp_max,0.0f,1.0f),6*scale,0xff96c679);
    std::snprintf(label,sizeof(label),"ST %.0f / %.0f",std::ceil(r.stamina),std::ceil(r.stamina_max));
    text(x,y+65*scale,2*scale,label,0xffe6dabb);
    rect(x,y+84*scale,268*scale,6*scale,0xff343a3a);
    rect(x,y+84*scale,268*scale*std::clamp(r.stamina/r.stamina_max,0.0f,1.0f),6*scale,0xffdcc274);
    }
    if(collect_visible(s)) {
        // Share the right HUD inset, above the skill area, in either split layout.
        const float cx=right-100*scale,cy=bottom-178*scale;
        rect(cx-76*scale,cy-5*scale,152*scale,34*scale,0xdf171310);
        rect(cx-76*scale,cy-5*scale,2*scale,34*scale,0xffb6a987);
        const bool talk=s.collect.kind==1;
        text(cx-(talk?37:53)*scale,cy,1.75f*scale,talk?"B  Talk":"B  Collect",0xfff0e7d5);
    }
    if(s.aim.visible) {
        // The verified bow ray follows eye -> look, the center of P2's native
        // viewport. This marks requested aim, not projectile-drop prediction.
        const float cx=(left+right)*.5f,cy=(top+bottom)*.5f;
        const DWORD color=s.aim.ready && !s.aim.release_shot?0xfff3f0dc:0xffdcc274;
        for(const auto& box:std::array<std::array<float,4>,4>{{
            {{-11,-1,6,2}},{{5,-1,6,2}},{{-1,-11,2,6}},{{-1,5,2,6}}
        }}) {
            rect(cx+(box[0]-1)*scale,cy+(box[1]-1)*scale,(box[2]+2)*scale,(box[3]+2)*scale,0xdf101519);
            rect(cx+box[0]*scale,cy+box[1]*scale,box[2]*scale,box[3]*scale,color);
        }
        rect(cx-2*scale,cy-2*scale,4*scale,4*scale,0xdf101519);
        rect(cx-scale,cy-scale,2*scale,2*scale,color);
        const auto& g=s.aim.ground;
        ground.active=g.active;ground.ready=g.active && g.ready;ground.hit=ground.ready && g.hit;
        if(ground.ready)std::memcpy(ground.target,g.target,12);
        if(ground.hit)ground.projected=split::project(g.target,g.epoch,g.generation,w,h,ground.x,ground.y);
        if(ground.projected) {
            // Clip every marker rectangle to P2's letterboxed pane.
            const auto box=[&](float ox,float oy,float bw,float bh,DWORD tint) {
                rect(ground.x+ox*scale,ground.y+oy*scale,bw*scale,bh*scale,tint);
            };
            for(const auto& b:std::array<std::array<float,4>,4>{{{{-13,-13,26,3}},{{-13,10,26,3}},{{-13,-10,3,20}},{{10,-10,3,20}}}}) {
                box(b[0]-1,b[1]-1,b[2]+2,b[3]+2,0xdf101519);
                box(b[0],b[1],b[2],b[3],0xff7bdfdc);
            }
        }
        rect(x-12*scale,y-(g.active?98:76)*scale,292*scale,(g.active?80:58)*scale,0xcf101519);
        if(g.active)text(x,y-88*scale,1.5f*scale,!g.ready?"Preparing target":!g.hit?"Ground unconfirmed":
