        if(s.aim.slot>=0)std::snprintf(label,sizeof(label),"Bow  Skill %d",s.aim.slot+1);
        else std::snprintf(label,sizeof(label),"Bow");
        text(x,y-66*scale,2*scale,label,color);
        const char* hint=s.aim.release_shot?"Release X/Y/B/RT":!s.aim.ready?"Aim not ready":"RT fire  X1 Y2 B3";
        text(x,y-40*scale,1.5f*scale,hint,0xffe8e9dc);
    }
    if(s.frazil.visible) {
        rect(x-12*scale,y-100*scale,292*scale,80*scale,0xe8101519);
        char caption[48]{};
        std::snprintf(caption,sizeof(caption),"%s - %s",channel_name(s.frazil.spell),
            s.frazil.state==6?"Channeling":s.frazil.state==2?"Ready":"Charging");
        text(x,y-88*scale,1.5f*scale,caption,0xffe8e9dc);
        constexpr const char* hints[]{"Release X: cast","Release Y: cast","Release B: cast"};
        const char* cast=s.frazil.slot>=0 && s.frazil.slot<6?hints[s.frazil.slot%3]:"Release skill: cast";
        const char* channel_hint=s.frazil.spell==215?"X/Y: whip  A: stop":"A: jump to stop";
        text(x,y-65*scale,1.5f*scale,s.frazil.state==6?channel_hint:s.frazil.state==2?cast:"Hold skill to charge",0xffdcc274);
        text(x,y-43*scale,1.25f*scale,s.frazil.state==6?"Drains stamina":"A: cancel",0xffc7d0c7);
    }
    if(s.ingle.visible) {
        ingle.visible=1;ingle.ready=s.ingle.ready;ingle.target_valid=s.ingle.target_valid;
        if(ingle.target_valid) {
            std::memcpy(ingle.position,s.ingle.position,12);
            ingle.projected=split::project(s.ingle.position,s.ingle.epoch,s.ingle.generation,w,h,ingle.x,ingle.y);
        }
        const DWORD tint=ingle.ready && ingle.target_valid?0xfff3f0dc:0xffdcc274;
        if(ingle.projected) {
            // This is the requested native aim point, not a predicted hit.
            // Bone-origin parallax makes a fixed viewport-center mark inaccurate.
            const auto box=[&](float ox,float oy,float bw,float bh,DWORD color) {
                rect(ingle.x+ox*scale,ingle.y+oy*scale,bw*scale,bh*scale,color);
            };
            for(const auto& b:std::array<std::array<float,4>,4>{{{{-11,-1,6,2}},{{5,-1,6,2}},{{-1,-11,2,6}},{{-1,5,2,6}}}}) {
                box(b[0]-1,b[1]-1,b[2]+2,b[3]+2,0xdf101519);box(b[0],b[1],b[2],b[3],tint);
            }
            box(-2,-2,4,4,0xdf101519);box(-1,-1,2,2,tint);
        }
        rect(x-12*scale,y-98*scale,292*scale,84*scale,0xcf101519);
        char caption[48]{};
        std::snprintf(caption,sizeof(caption),"%s - %s",projectile_name(s.ingle.spell),
            !ingle.ready?"Charging":s.ingle.mode==1?"Locked":s.ingle.has_enemy?"Target":"Ready");
        text(x,y-88*scale,1.5f*scale,caption,0xffe8e9dc);
        const char* cast_hints[]{"Release X: cast","Release Y: cast","Release B: cast"};
        const char* cast_hint=s.ingle.slot>=0 && s.ingle.slot<6?cast_hints[s.ingle.slot%3]:"Release skill: cast";
        const char* hint=!ingle.target_valid?"Aim lost - cast cancels":!ingle.projected?"Aim offscreen":
            ingle.ready?cast_hint:s.ingle.mode==2?"Free aim":s.ingle.has_enemy?"Target selected":"Auto aim";
        text(x,y-66*scale,1.5f*scale,hint,tint);
        text(x,y-40*scale,1.5f*scale,"RS click: lock  A: cancel",0xffe8e9dc);
        text(x,y-25*scale,1.5f*scale,"LS click: free / auto",0xffe8e9dc);
    }
    if(s.boon.visible) {
        boon.visible=1;boon.ready=s.boon.ready;boon.target_valid=s.boon.target_valid;boon.target_kind=s.boon.target_kind;
        if(boon.target_valid) {
            std::memcpy(boon.position,s.boon.position,12);
            boon.projected=split::project(s.boon.position,s.boon.epoch,s.boon.generation,w,h,boon.x,boon.y);
        }
        const DWORD tint=boon.target_valid?0xff96c679:0xffdcc274;
        if(boon.projected) {
            const auto box=[&](float ox,float oy,float bw,float bh,DWORD color) {
                rect(boon.x+ox*scale,boon.y+oy*scale,bw*scale,bh*scale,color);
            };
            for(const auto& b:std::array<std::array<float,4>,4>{{{{-13,-13,26,3}},{{-13,10,26,3}},{{-13,-10,3,20}},{{10,-10,3,20}}}}) {
                box(b[0]-1,b[1]-1,b[2]+2,b[3]+2,0xdf101519);box(b[0],b[1],b[2],b[3],tint);
            }
        }
        rect(x-12*scale,y-98*scale,292*scale,80*scale,0xcf101519);
        char caption[40]{};std::snprintf(caption,sizeof(caption),"%s - %s",boon_name(s.boon.spell),boon.ready?"Ready":"Charging");
        text(x,y-88*scale,1.5f*scale,caption,0xffe8e9dc);
        const char* target=!boon.target_valid?"No target - cast cancels":boon.target_kind==1?"Target: self":
            boon.target_kind==2?"Target: Arisen":"Target: ally";
        text(x,y-66*scale,1.5f*scale,target,tint);
        text(x,y-40*scale,1.5f*scale,"LS: self/ally  A: cancel",0xffe8e9dc);
    }
