bool overhead_enabled(const Snapshot& s) {
    if(!s.active || !s.overhead.count)return false;
    return settings().p2_enemy_health_bars || settings().p2_ally_health_bars;
}
DWORD faded_color(DWORD rgb,float alpha) {
    const auto a=static_cast<DWORD>(std::lround(220.0f*std::clamp(alpha,0.0f,1.0f)));
    return (a<<24)|(rgb&0x00ffffffu);
}
void build_overhead(const Snapshot& s,unsigned w,unsigned h,OverheadStatus& drawn) {
    drawn=OverheadStatus{};drawn.width=w;drawn.height=h;
    const auto pane=split::pane_rect(w,h,settings().split_layout,1);
    draw_clip=pane;
    camera::Projection view;
    if(!split::marker_view(1,s.epoch,s.generation,w,h,view))return;
    // This after-scene overlay has no terrain depth test. Projection proves
    // only frustum visibility; native occlusion remains a separate requirement.
    std::array<overhead::ProjectedBar,64> projected{};
    const unsigned bar_count=overhead::project(s.overhead,view,settings().p2_enemy_health_bars,
        settings().p2_ally_health_bars,projected);
    const float scale=split::pane_hud_scale(w,h,settings().split_layout);
    const float width=60.0f*scale,height=6.0f*scale;
    bool has_ratio{};
    for(unsigned i=0;i<bar_count;++i) {
        const auto& bar=projected[i];
        const float x=bar.x-width*.5f,y=bar.y-8.0f*scale;
        const float edge=1.0f*scale;
        // Keep the complete life bar inside P2's pane. A partially clipped
        // edge bar is omitted so diagnostics count only whole drawn bars.
        if(x-edge<pane.left || y-edge<pane.top || x+width+edge>pane.right ||
           y+height+edge>pane.bottom || width<=0 || height<=0)continue;
        const DWORD border=faded_color(0x171613,bar.alpha);
        const DWORD background=faded_color(0x343a35,bar.alpha);
        const DWORD damage=faded_color(0x887653,bar.alpha);
        const DWORD health=faded_color(bar.ally?0xb4ca87:0xd86a98,bar.alpha);
        const DWORD corner=faded_color(0x9b8c68,bar.alpha*.8f);
        // A narrow native-like life bar: charcoal rim, muted ochre lost HP,
        // pink enemy / green ally current HP, and small antique-gold corner marks.
        rect(x-1.0f*scale,y-1.0f*scale,width+2.0f*scale,height+2.0f*scale,border);
        rect(x,y,width,height,background);
        const float fraction=std::clamp(bar.ratio,0.0f,1.0f);
        const float inner_width=width-2.0f*scale,filled_width=inner_width*fraction;
        rect(x+1.0f*scale+filled_width,y+1.0f*scale,inner_width-filled_width,height-2.0f*scale,damage);
        rect(x+1.0f*scale,y+1.0f*scale,filled_width,height-2.0f*scale,health);
        const float tick=3.0f*scale;
        rect(x-edge,y-edge,tick,edge,corner);rect(x-edge,y-edge,edge,tick,corner);
        rect(x+width+edge-tick,y-edge,tick,edge,corner);rect(x+width,y-edge,edge,tick,corner);
        rect(x-edge,y+height,tick,edge,corner);rect(x-edge,y+height+edge-tick,edge,tick,corner);
        rect(x+width+edge-tick,y+height,tick,edge,corner);rect(x+width,y+height+edge-tick,edge,tick,corner);
        if(bar.ally)++drawn.allies;else ++drawn.enemies;
        if(!has_ratio || bar.ratio<drawn.minimum_ratio)drawn.minimum_ratio=bar.ratio;
        has_ratio=true;
    }
}
HRESULT draw(IDirect3DDevice9* d,const Snapshot& s,bool resources,bool notice,unsigned& w,unsigned& h,GroundHudStatus& ground,BoonHudStatus& boon,IngleHudStatus& ingle,OverheadStatus& overhead_drawn) {
    IDirect3DSurface9 *target{},*back{};
    HRESULT result=d->GetRenderTarget(0,&target);
    if(FAILED(result))return result;
    result=d->GetBackBuffer(0,0,D3DBACKBUFFER_TYPE_MONO,&back);
    const bool main=SUCCEEDED(result) && target==back;
    D3DSURFACE_DESC desc{};if(main)result=back->GetDesc(&desc);
    target->Release();if(back)back->Release();
    if(!main || FAILED(result))return S_FALSE;
    if(desc.Width<640 || desc.Height<360)return S_FALSE;
    w=desc.Width;h=desc.Height;
    IDirect3DStateBlock9* state{};
    result=d->CreateStateBlock(D3DSBT_ALL,&state);
    if(FAILED(result))return result;
    result=state->Capture();
    if(SUCCEEDED(result))result=d->BeginScene();
    if(SUCCEEDED(result)) {
        try {
        count=0;draw_clip={};begin_hint_text();
        if(resources)build_resources(s,w,h,ground,boon,ingle);
        if(overhead_enabled(s))build_overhead(s,w,h,overhead_drawn);
        std::array<PartnerMarker,2> markers{};
        const float marker_scale=split::pane_hud_scale(w,h,settings().split_layout);
        if(s.active && s.partners.visible && settings().partner_sigils)for(unsigned pane=0;pane<2;++pane) {
            camera::Projection camera;
            if(split::marker_view(pane,s.epoch,s.generation,w,h,camera)) {
                markers[pane]=partner_marker(camera,s.partners.position[1-pane],46*marker_scale);
                if(markers[pane].visible)marker_arrow(markers[pane],marker_scale,pane==0?0xffb3cbd0:0xffd6bc86);
            }
        }
        D3DVIEWPORT9 view{0,0,w,h,0,1};
        // Restore the entire captured device state before handing back control.
        // Every setter failure prevents drawing with a partially configured state.
        const auto apply=[&](HRESULT hr){if(FAILED(hr) && SUCCEEDED(result))result=hr;};
        apply(d->SetViewport(&view));apply(d->SetVertexShader(nullptr));apply(d->SetPixelShader(nullptr));
        apply(d->SetFVF(D3DFVF_XYZRHW|D3DFVF_DIFFUSE));apply(d->SetTexture(0,nullptr));
        for(const auto& v:std::array<std::pair<D3DRENDERSTATETYPE,DWORD>,20>{{
            {D3DRS_ZENABLE,FALSE},{D3DRS_ZWRITEENABLE,FALSE},{D3DRS_ALPHATESTENABLE,FALSE},
            {D3DRS_ALPHABLENDENABLE,TRUE},{D3DRS_SRCBLEND,D3DBLEND_SRCALPHA},
            {D3DRS_DESTBLEND,D3DBLEND_INVSRCALPHA},{D3DRS_BLENDOP,D3DBLENDOP_ADD},
            {D3DRS_SEPARATEALPHABLENDENABLE,FALSE},{D3DRS_CULLMODE,D3DCULL_NONE},
            {D3DRS_LIGHTING,FALSE},{D3DRS_FOGENABLE,FALSE},{D3DRS_STENCILENABLE,FALSE},
            {D3DRS_SCISSORTESTENABLE,FALSE},{D3DRS_SRGBWRITEENABLE,FALSE},
            {D3DRS_COLORWRITEENABLE,15},{D3DRS_FILLMODE,D3DFILL_SOLID},
            {D3DRS_CLIPPLANEENABLE,0},{D3DRS_SHADEMODE,D3DSHADE_GOURAUD},
            // Render-state wrapping alters UV interpolation independently of
            // sampler CLAMP; 0/1 ribbon UVs must not collapse onto alpha edges.
            // Cover every MSAA sample, then restore the caller's native mask.
            {D3DRS_WRAP0,0},{D3DRS_MULTISAMPLEMASK,0xffffffffu}}})apply(d->SetRenderState(v.first,v.second));
        apply(d->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_SELECTARG1));
        apply(d->SetTextureStageState(0,D3DTSS_COLORARG1,D3DTA_DIFFUSE));
        apply(d->SetTextureStageState(0,D3DTSS_ALPHAOP,D3DTOP_SELECTARG1));
        apply(d->SetTextureStageState(0,D3DTSS_ALPHAARG1,D3DTA_DIFFUSE));
        apply(d->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_DISABLE));
        if(SUCCEEDED(result) && count)result=d->DrawPrimitiveUP(D3DPT_TRIANGLELIST,count/3,vertices.data(),sizeof(Vertex));
        if(SUCCEEDED(result))result=draw_hint_text(d,w,h);
        const bool life_visible=player_feedback::shared_life_visible(s.life);
        if(SUCCEEDED(result) && life_visible)
            result=draw_shared_life(d,s.life.remaining,settings().shared_life_hud,s.life.persistence_error,w,h,s.life.endless);
        else release_shared_life_textures();
        if(SUCCEEDED(result) && resources)result=draw_palette_text(d,s.palette,w,h);
        bool any_marker{};
        for(unsigned pane=0;pane<2 && SUCCEEDED(result);++pane)if(markers[pane].visible) {
            const auto clip=split::pane_rect(w,h,settings().split_layout,pane);
            any_marker=true;
            result=draw_partner_sigil(d,1-pane,markers[pane].x,markers[pane].y,marker_scale,
                {clip.left,clip.top,clip.right,clip.bottom});
        }
        if(!any_marker)release_partner_textures();
        if(SUCCEEDED(result) && notice) {
            const auto message=notice_copy(s);result=draw_notice_text(d,message.title,message.help,w,h);
        }
        if(!notice)release_notice_textures();
        if(!resources)release_palette_texture();
        } catch(const std::bad_alloc&) {result=E_OUTOFMEMORY;}
          catch(...) {result=E_FAIL;}
        // Cleanup also runs when CPU raster allocation failed after BeginScene.
        const auto cleanup=[&](HRESULT hr){if(FAILED(hr) && SUCCEEDED(result))result=hr;};
        cleanup(state->Apply());cleanup(d->EndScene());
    }
    state->Release();return result;
}
}
// Keep guarded static initialization outside the POD-only SEH wrapper.
static double hud_time_factor() {
    static const double factor=[](){LARGE_INTEGER f;QueryPerformanceFrequency(&f);return 1e6/static_cast<double>(f.QuadPart);}();
    return factor;
}
void __fastcall submit_hook(void* renderer,void*) {
    // EXP-012: native D3D command consumer, ECX=sRenderExt, RET 0. The native
    // scene has ended when it returns; no native render jobs remain in flight.
    AcquireSRWLockExclusive(&status_lock);overhead_status=OverheadStatus{};ReleaseSRWLockExclusive(&status_lock);
    submit_original(renderer);
    const auto span=performance::begin(performance::Channel::hud_after);
    __try {
    LARGE_INTEGER begin{},end{};QueryPerformanceCounter(&begin);
    const auto s=snapshot();float dx{},dz{};
    const bool resources=s.active && valid_resources(s.resources) && split::basis(dx,dz);
    const bool overhead_bars=overhead_enabled(s) && split::basis(dx,dz);
    const bool shared_life=player_feedback::shared_life_visible(s.life) &&
        (settings().shared_life_hud || s.life.persistence_error);
    const bool markers=s.active && s.partners.visible && settings().partner_sigils && split::basis(dx,dz);
    const bool player_notice=*player_feedback::copy(static_cast<player_feedback::Notice>(s.player_notice)).title!=0;
    const bool vocation_notice=!player_notice && !s.player_notice_managed && s.vocation_notice>=1 && s.vocation_notice<=3;
    const bool notice=!player_notice && !s.player_notice_managed && !vocation_notice && s.separation.state>=1 && s.separation.state<=4;
    const bool startup=s.startup_notice && !player_notice && !vocation_notice && !notice;
    // Native command buffers have finished consuming our owned GUI nodes here.
    if(!resources)native_hud::release_at_safe_boundary();
    unsigned w{},h{};HRESULT result=S_FALSE;
    GroundHudStatus ground;
    BoonHudStatus boon;
    IngleHudStatus ingle;
    OverheadStatus overhead_drawn;
    if(resources || overhead_bars || shared_life || markers || notice || vocation_notice || startup || player_notice) {
        const auto device=*reinterpret_cast<IDirect3DDevice9**>(static_cast<unsigned char*>(renderer)+0x98);
        if(device) {
            const auto graphics=performance::enter(performance::Category::graphics);
            __try {result=draw(device,s,resources,notice || vocation_notice || startup || player_notice,w,h,ground,boon,ingle,overhead_drawn);}
            __finally {performance::leave(graphics);}
        }
    }
    if(result!=S_OK || (!resources && !overhead_bars && !shared_life && !markers && !notice && !vocation_notice && !startup && !player_notice)) {
        const auto graphics=performance::enter(performance::Category::graphics);
        __try {release_hud_textures();} __finally {performance::leave(graphics);}
    }
    QueryPerformanceCounter(&end);
    const auto wait=performance::enter(performance::Category::lock_wait);
    __try {AcquireSRWLockExclusive(&status_lock);} __finally {performance::leave(wait);}
    const bool resource_drawn=result==S_OK && resources;
    collect_status=NoticeStatus{};
    if(resource_drawn && collect_visible(s)) {
        collect_status.visible=1;collect_status.state=s.collect.kind;
        collect_status.width=w;collect_status.height=h;
    }
    status.visible=resource_drawn?1u:0u;
    if(resource_drawn){
        ++status.draws;status.width=w;status.height=h;
        const auto us=static_cast<float>(static_cast<double>(end.QuadPart-begin.QuadPart)*hud_time_factor());
        draw_times[time_index]=us;time_index=(time_index+1)%2048;time_count=std::min(time_count+1,2048u);
        ++status.samples;status.draw_last_us=us;status.draw_max_us=std::max(status.draw_max_us,us);
    }
    // Device loss is expected during native reset, not a permanent HUD failure.
    if(FAILED(result) && result!=D3DERR_DEVICELOST && result!=D3DERR_DEVICENOTRESET)++status.failures;
    overhead_status=OverheadStatus{};
    if(result==S_OK && overhead_bars)overhead_status=overhead_drawn;
    status.hp=s.resources.hp;status.hp_max=s.resources.hp_max;status.hp_white=s.resources.hp_white;
    status.stamina=s.resources.stamina;status.stamina_max=s.resources.stamina_max;
    notice_status=NoticeStatus{};
    if(result==S_OK && notice) {
        notice_status.visible=1;notice_status.state=s.separation.state;notice_status.width=w;notice_status.height=h;
    }
    vocation_notice_status=NoticeStatus{};
    startup_notice_status=NoticeStatus{};
    player_notice_status=NoticeStatus{};
    if(result==S_OK && player_notice) {
        player_notice_status.visible=1;player_notice_status.state=s.player_notice;
        player_notice_status.width=w;player_notice_status.height=h;
    }
    if(result==S_OK && startup) {
        startup_notice_status.visible=1;startup_notice_status.state=1;startup_notice_status.width=w;startup_notice_status.height=h;
    }
    if(result==S_OK && vocation_notice) {
        vocation_notice_status.visible=1;vocation_notice_status.state=s.vocation_notice;vocation_notice_status.width=w;vocation_notice_status.height=h;
    }
    aim_status.visible=resource_drawn && s.aim.visible?1u:0u;
    aim_status.ready=aim_status.visible && s.aim.ready?1u:0u;
    aim_status.release_shot=aim_status.visible && s.aim.release_shot?1u:0u;
    aim_status.slot=aim_status.visible?s.aim.slot:-1;
    const auto pane=split::pane_rect(w,h,settings().split_layout,1);
    aim_status.x=aim_status.visible?(static_cast<float>(pane.left)+static_cast<float>(pane.right))*.5f:0;
    aim_status.y=aim_status.visible?(static_cast<float>(pane.top)+static_cast<float>(pane.bottom))*.5f:0;
    ground_status=resource_drawn?ground:GroundHudStatus{};
    boon_status=resource_drawn?boon:BoonHudStatus{};
    ingle_status=resource_drawn?ingle:IngleHudStatus{};
    skill_status=SkillHudStatus{};
    if(resource_drawn && s.palette.mode && settings().skill_hud) {
        skill_status.visible=1;skill_status.mode=s.palette.mode;skill_status.blocked=s.palette.blocked;
        for(unsigned i=0;i<3;++i){skill_status.ids[i]=s.palette.ids[i];std::memcpy(skill_status.names[i],s.palette.names[i].data(),256);}
    }
    ReleaseSRWLockExclusive(&status_lock);
    } __finally {performance::end(span);}
}
}
