#include "coop/native_offline.hpp"
#include <windows.h>
#include <atomic>
#include <cstdint>
namespace coop::native {
void* set_original{};
void* get_original{};
void* connect_original{};
namespace {
std::atomic<unsigned> failures{};
template<class T> T& at(std::uintptr_t base, unsigned offset=0) { return *reinterpret_cast<T*>(base+offset); }
bool clear_save(std::uintptr_t save) {
    if (!save || at<unsigned>(save)!=0x1561750 || at<unsigned>(save,0x20e75c)!=0x15617d4) return false;
    at<unsigned>(save,0x20e774) &= ~0x1000u;
    return true;
}
void complete() {
    const auto net=at<std::uintptr_t>(0x18d0cc4);
    if(net) {
        // All three fields match the engine's offline-complete branch.
        at<unsigned char>(net,0x545)=1;
        at<unsigned char>(net,0x5a2e)=1;
        at<unsigned char>(net,0x534)=0xff;
    }
}
void __cdecl before_option(std::uintptr_t save, std::uintptr_t source) {
    __try {
        if(!clear_save(save)) ++failures;
        if(source) {
            if(at<unsigned>(source)==0x15617d4) at<unsigned>(source,0x18)&=~0x1000u;
            else ++failures;
        }
    } __except(EXCEPTION_EXECUTE_HANDLER) { ++failures; }
}
void __cdecl after_connect() {
    __try { clear_save(at<std::uintptr_t>(0x18fa4f8)); complete(); }
    __except(EXCEPTION_EXECUTE_HANDLER) { ++failures; }
}
}
// Original get/set use EAX for the option, ECX for the save. Preserve machine
// state across the C++ pre-hook and tail-call the verified original ABI.
__declspec(naked) void set_hook() {
    __asm {
        push ebp
        mov ebp, esp
        pushfd
        pushad
        push eax
        push ecx
        call before_option
        add esp, 8
        popad
        popfd
        call dword ptr [set_original]
        pushfd
        pushad
        call after_connect
        popad
        popfd
        mov esp, ebp
        pop ebp
        ret
    }
}
__declspec(naked) void get_hook() {
    __asm {
        pushfd
        pushad
        push 0
        push ecx
        call before_option
        add esp, 8
        popad
        popfd
        jmp dword ptr [get_original]
    }
}
// EAX=network object, one callee-cleaned stack argument. Use the original's
// offline path first; completing only the visible mode at startup can hang DDDA.
__declspec(naked) void connect_hook() {
    __asm {
        push ebp
        mov ebp, esp
        push 0
        call dword ptr [connect_original]
        pushfd
        pushad
        call after_connect
        popad
        popfd
        mov esp, ebp
        pop ebp
        ret 4
    }
}
unsigned char __fastcall query_hook(void*, void*) { after_connect(); return 0; }
bool healthy() {
    if(failures.load()) return false;
    __try {
        const auto save=at<std::uintptr_t>(0x18fa4f8), net=at<std::uintptr_t>(0x18d0cc4);
        return save && net && at<unsigned>(save)==0x1561750 && at<unsigned>(save,0x20e75c)==0x15617d4 &&
            !(at<unsigned>(save,0x20e774)&0x1000) && at<unsigned char>(net,0x545)==1 && at<unsigned char>(net,0x5a2e)==1;
    } __except(EXCEPTION_EXECUTE_HANDLER) { return false; }
}
unsigned errors() { return failures.load(); }
}

