// Process-local offline research guard. Installed explicitly outside DllMain.
// Hooks stay installed until process exit; no hot unhook/reconnect path.
#include <winsock2.h>
#include <windows.h>
#include <MinHook.h>
#include <atomic>

namespace {
std::atomic<unsigned> blocks{0};
std::atomic<int> state{0}; // 0 inactive, 1 initializing, 2 locked, -1 failed
SOCKET WSAAPI deny_socket(int, int, int) { ++blocks; WSASetLastError(WSAENETDOWN); return INVALID_SOCKET; }
SOCKET WSAAPI deny_wsa_a(int, int, int, LPWSAPROTOCOL_INFOA, GROUP, DWORD) { ++blocks; WSASetLastError(WSAENETDOWN); return INVALID_SOCKET; }
SOCKET WSAAPI deny_wsa_w(int, int, int, LPWSAPROTOCOL_INFOW, GROUP, DWORD) { ++blocks; WSASetLastError(WSAENETDOWN); return INVALID_SOCKET; }
int WSAAPI deny_connect(SOCKET, const sockaddr*, int) { ++blocks; WSASetLastError(WSAENETDOWN); return SOCKET_ERROR; }
int WSAAPI deny_wsa_connect(SOCKET, const sockaddr*, int, LPWSABUF, LPWSABUF, LPQOS, LPQOS) { ++blocks; WSASetLastError(WSAENETDOWN); return SOCKET_ERROR; }
int WSAAPI deny_send(SOCKET, const char*, int, int) { ++blocks; WSASetLastError(WSAENETDOWN); return SOCKET_ERROR; }
int WSAAPI deny_sendto(SOCKET, const char*, int, int, const sockaddr*, int) { ++blocks; WSASetLastError(WSAENETDOWN); return SOCKET_ERROR; }
int WSAAPI deny_wsasend(SOCKET, LPWSABUF, DWORD, LPDWORD count, DWORD, LPWSAOVERLAPPED, LPWSAOVERLAPPED_COMPLETION_ROUTINE) {
    ++blocks; if (count) *count = 0; WSASetLastError(WSAENETDOWN); return SOCKET_ERROR;
}
int WSAAPI deny_wsasendto(SOCKET, LPWSABUF, DWORD, LPDWORD count, DWORD, const sockaddr*, int, LPWSAOVERLAPPED, LPWSAOVERLAPPED_COMPLETION_ROUTINE) {
    ++blocks; if (count) *count = 0; WSASetLastError(WSAENETDOWN); return SOCKET_ERROR;
}
struct Hook { const char* name; void* replacement; void* address; };
Hook hooks[] = {
    {"socket", reinterpret_cast<void*>(deny_socket), nullptr},
    {"WSASocketA", reinterpret_cast<void*>(deny_wsa_a), nullptr},
    {"WSASocketW", reinterpret_cast<void*>(deny_wsa_w), nullptr},
    {"connect", reinterpret_cast<void*>(deny_connect), nullptr},
    {"WSAConnect", reinterpret_cast<void*>(deny_wsa_connect), nullptr},
    {"send", reinterpret_cast<void*>(deny_send), nullptr},
    {"sendto", reinterpret_cast<void*>(deny_sendto), nullptr},
    {"WSASend", reinterpret_cast<void*>(deny_wsasend), nullptr},
    {"WSASendTo", reinterpret_cast<void*>(deny_wsasendto), nullptr}
};
}
extern "C" __declspec(dllexport) int __cdecl EnsureOffline() {
    int expected = 0;
    if (!state.compare_exchange_strong(expected, 1)) return state.load() == 2 ? 1 : 0;
    HMODULE pinned{};
    // Once installed the guard cannot be unloaded, even if the research controller exits.
    if (!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_PIN,
        reinterpret_cast<LPCWSTR>(&EnsureOffline), &pinned)) { state = -1; return 0; }
    HMODULE ws = LoadLibraryExW(L"ws2_32.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!ws || MH_Initialize() != MH_OK) { state = -1; return 0; }
    for (auto& h : hooks) {
        h.address = reinterpret_cast<void*>(GetProcAddress(ws, h.name));
        if (!h.address || MH_CreateHook(h.address, h.replacement, nullptr) != MH_OK) { state = -1; return 0; }
    }
    for (auto& h : hooks) {
        if (MH_EnableHook(h.address) != MH_OK) { state = -1; return 0; }
    }
    // Production startup must verify enforcement itself; a developer host is
    // optional. This creates no connection and sends no bytes even on failure.
    WSADATA data{};
    if (WSAStartup(MAKEWORD(2, 2), &data)) { state = -1; return 0; }
    const auto prior = blocks.load();
    const SOCKET probe = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    const int error = WSAGetLastError();
    if (probe != INVALID_SOCKET) closesocket(probe);
    WSACleanup();
    if (probe != INVALID_SOCKET || error != WSAENETDOWN || blocks.load() <= prior) {
        state = -1; return 0;
    }
    state = 2;
    return 1;
}
extern "C" __declspec(dllexport) int __cdecl OfflineState() { return state.load(); }
extern "C" __declspec(dllexport) unsigned __cdecl OfflineBlockedCalls() { return blocks.load(); }

