// System dinput8 forwarding. No loading, hooks or worker threads in DllMain.
#include <windows.h>
#include <dinput.h>
#include <string>
namespace {
INIT_ONCE once = INIT_ONCE_STATIC_INIT;
HMODULE real_module{};
BOOL CALLBACK initialize(PINIT_ONCE, PVOID, PVOID*) {
    wchar_t system[MAX_PATH]{};
    if (!GetSystemDirectoryW(system, MAX_PATH)) return TRUE;
    const std::wstring real_path = std::wstring(system) + L"\\dinput8.dll";
    real_module = LoadLibraryExW(real_path.c_str(), nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!real_module) return TRUE;
    wchar_t file[MAX_PATH]{};
    HMODULE self{};
    if (!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(&initialize), &self) || !GetModuleFileNameW(self, file, MAX_PATH)) return TRUE;
    std::wstring path(file);
    path.resize(path.find_last_of(L"\\/") + 1);
    // The runtime uses one strict parser and logs configuration errors before
    // installing anything. Missing/disabled settings leave native input intact.
    HMODULE runtime = LoadLibraryExW((path + L"ddcoop_runtime.dll").c_str(), nullptr,
        LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR | LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (runtime) {
        auto start = reinterpret_cast<int(__cdecl*)()>(GetProcAddress(runtime, "CoopInitialize"));
        if (start) start();
        // Initialized runtimes pin themselves; inert runtimes can unload normally.
        FreeLibrary(runtime);
    }
    return TRUE;
}
template<class T> T proc(const char* name) {
    InitOnceExecuteOnce(&once, initialize, nullptr, nullptr);
    return real_module ? reinterpret_cast<T>(GetProcAddress(real_module, name)) : nullptr;
}
}
extern "C" HRESULT WINAPI ProxyDirectInput8Create(HINSTANCE h, DWORD version, REFIID iid, LPVOID* out, LPUNKNOWN outer) {
    auto fn = proc<decltype(&DirectInput8Create)>("DirectInput8Create");
    return fn ? fn(h,version,iid,out,outer) : E_FAIL;
}
extern "C" HRESULT WINAPI ProxyDllCanUnloadNow() {
    auto fn = proc<HRESULT(WINAPI*)()>("DllCanUnloadNow"); return fn ? fn() : S_FALSE;
}
extern "C" HRESULT WINAPI ProxyDllGetClassObject(REFCLSID cls, REFIID iid, LPVOID* out) {
    auto fn = proc<HRESULT(WINAPI*)(REFCLSID,REFIID,LPVOID*)>("DllGetClassObject"); return fn ? fn(cls,iid,out) : E_FAIL;
}
extern "C" HRESULT WINAPI ProxyDllRegisterServer() {
    auto fn = proc<HRESULT(WINAPI*)()>("DllRegisterServer"); return fn ? fn() : E_FAIL;
}
extern "C" HRESULT WINAPI ProxyDllUnregisterServer() {
    auto fn = proc<HRESULT(WINAPI*)()>("DllUnregisterServer"); return fn ? fn() : E_FAIL;
}
extern "C" LPCDIDATAFORMAT WINAPI ProxyGetdfDIJoystick() {
    auto fn = proc<LPCDIDATAFORMAT(WINAPI*)()>("GetdfDIJoystick"); return fn ? fn() : nullptr;
}

