DWORD neutral_input_state(DWORD index,XINPUT_STATE* out) {
    if(!out)return ERROR_BAD_ARGUMENTS;
    *out={};
    if(index || native_keyboard_input.load(std::memory_order_acquire))return ERROR_DEVICE_NOT_CONNECTED;
    out->dwPacketNumber=static_cast<DWORD>(GetTickCount64());return ERROR_SUCCESS;
}
DWORD neutral_input_caps(DWORD index,XINPUT_CAPABILITIES* out) {
    if(!out)return ERROR_BAD_ARGUMENTS;
    *out={};
    if(index || native_keyboard_input.load(std::memory_order_acquire))return ERROR_DEVICE_NOT_CONNECTED;
    out->Type=XINPUT_DEVTYPE_GAMEPAD;out->SubType=XINPUT_DEVSUBTYPE_GAMEPAD;
    out->Gamepad={0xf3ff,255,255,32767,32767,32767,32767};
    out->Vibration={65535,65535};return ERROR_SUCCESS;
}
DWORD raw_get_state(DWORD index,XINPUT_STATE* out) {
    DWORD result=ERROR_DEVICE_NOT_CONNECTED;
    ++raw_input_depth;raw_input_calls.fetch_add(1,std::memory_order_acq_rel);
    __try {if(get_original)result=get_original(index,out);}
    __finally {raw_input_calls.fetch_sub(1,std::memory_order_release);--raw_input_depth;}
    return result;
}
DWORD raw_get_caps(DWORD index,DWORD flags,XINPUT_CAPABILITIES* out) {
    DWORD result=ERROR_DEVICE_NOT_CONNECTED;
    ++raw_input_depth;raw_input_calls.fetch_add(1,std::memory_order_acq_rel);
    __try {if(caps_original)result=caps_original(index,flags,out);}
    __finally {raw_input_calls.fetch_sub(1,std::memory_order_release);--raw_input_depth;}
    return result;
}
void raw_set_state(DWORD index,XINPUT_VIBRATION* vibration) {
    ++raw_input_depth;raw_input_calls.fetch_add(1,std::memory_order_acq_rel);
