// Existing adapter lock must be held. Clock failure stops only research timing.
bool latency_tick(std::uint64_t& tick) {
    if(!latency_running)return false;
    LARGE_INTEGER now{};
    if(!QueryPerformanceCounter(&now) || now.QuadPart<0 ||
       static_cast<std::uint64_t>(now.QuadPart)<latency_clock) {
        ++latency_clock_failures;latency_tracker.seal(latency_clock);latency_running=false;return false;
    }
    tick=static_cast<std::uint64_t>(now.QuadPart);latency_clock=tick;return true;
}
latency::Context latency_context(bool pawn) {
    const int slot=pawn?routing.p2:routing.p1;
    const bool connected=pawn?routing.pawn.connected:routing.arisen.connected;
    return {slot>=0?static_cast<unsigned>(slot):latency::unassigned_slot,
        pawn?actor_identity[1]:0,world_epoch,routing.generation,
        connected && (!pawn || routing.state==coop::SessionState::joined)};
}
