unsigned separation_notice(std::uint64_t now) {
    const auto v=separation_gate.view(now);
    if(separation_released && session.pawn_recovery_pending())return v.fresh?(v.join_allowed?3u:2u):4u;
    if(routing.p2<0)return 0;
    return !v.fresh?4u:v.warning?1u:0u;
}
unsigned vocation_notice(std::uint64_t now) {
    const auto v=vocation_view(now);
    if(v.fresh && !v.allowed)return 1;
    if(!vocation_released)return 0;
    const auto d=separation_gate.view(now);
    const bool within_range=d.fresh && (separation_released || session.pawn_recovery_pending()?d.join_allowed:d.initial_join_allowed);
    return v.fresh && v.allowed && within_range?3u:2u;
}
