// Copied provenance only: polling never reads a native action or renews a
// native timestamp. The consumer below revalidates action/resource ownership.
void capture_menu_charge(std::uint64_t now) {
    menu_charge={};
    const auto held=session.menu_hold_sample();
    if(!held.connected || mage_frame.actor!=actor_identity[1] || mage_frame.epoch!=world_epoch ||
       mage_frame.generation!=routing.generation || now<mage_frame.when || now-mage_frame.when>150)return;
    const auto keep=[&](const coop::mage::Identity& id,const coop::mage::RankBinding& rank,
                        const coop::mage::RankView& released,unsigned command) {
        if(!id.healthy || !id.action || !id.lifetime || id.actor!=actor_identity[1] || id.epoch!=world_epoch ||
           id.generation!=routing.generation || now<id.when || now-id.when>150 || released.parameters ||
           !rank.parameters || !rank.element || !coop::mage::skill_held(command) ||
           (status.actors[1].held&command)!=command)return;
        for(int slot=0;slot<6;++slot) {
            const bool selected=slot<3?(held.buttons&0x200) && !(held.buttons&0x100):(held.buttons&0x100)!=0;
            constexpr unsigned faces[]{0x4000,0x8000,0x2000};
            if(command==(coop::mage::slot_modifier(slot)|coop::mage::slot_button(slot)) && selected &&
               (held.buttons&faces[slot%3]))menu_charge={id,rank,rank.spell,slot,command,0,0,0};
        }
    };
    keep(mage_bound,mage_rank_bound,mage_released_rank,mage_frame.marker_command);
    keep(boon_frame.bound,boon_frame.rank_bound,boon_frame.released_rank,mage_frame.boon_command);
    keep(ingle_frame.bound,ingle_frame.rank_bound,ingle_frame.released_rank,mage_frame.ingle_command);
    keep(frazil_frame.bound,frazil_frame.rank_bound,frazil_frame.released_rank,mage_frame.frazil_command);
    // Ground spells freeze their release in LevinCast, not the targeting
    // frame. A frozen cast of this exact lifetime is already relinquished.
    if(!coop::mage::same_owner(levin_frame.bound,levin_cast.bound))
        keep(levin_frame.bound,levin_frame.rank_bound,{},mage_frame.levin_command);
    keep(whip_frame.bound,whip_frame.rank_bound,whip_frame.released_rank,mage_frame.whip_command);
    keep(fulmination_frame.bound,fulmination_frame.rank_bound,fulmination_frame.released_rank,mage_frame.fulmination_command);
}
