// Under the existing input lock. No game reads/addresses or diagnostic ABI.
// Exact explicit causes are supplied at the old invalidation boundary. For an
// update loss, report the actual selected batch/history rather than infer why
// Windows/the provider delivered it. pN=oldConnected:packet/newConnected:packet;
// newConnected=-1 means no pad batch was sampled at this explicit boundary.
void log_assignment_loss(const char* cause,const AssignmentHistory& old,
                         int p1,int p2,std::uint64_t generation,
                         const std::array<coop::DeviceSample,4>* pads=nullptr,
                         std::uint64_t sampled_at=0) {
    if(old.p1<0 && old.p2<0)return;
    constexpr unsigned limit=256;
    if(assignment_log_entries>=limit) {
        if(assignment_log_entries==limit){++assignment_log_entries;log("assignment-revoke log limit reached; further entries omitted");}
        return;
    }
    ++assignment_log_entries;
    const auto previous=[&](int slot){return slot>=0 && slot<4?old.pads[static_cast<unsigned>(slot)]:coop::DeviceSample{};};
    const auto current=[&](int slot){return pads && slot>=0 && slot<4?(*pads)[static_cast<unsigned>(slot)]:coop::DeviceSample{};};
    const auto a=previous(old.p1),b=previous(old.p2),c=current(old.p1),d=current(old.p2);
    // Update logs use the clock that actually selected the lease/batch, not a
    // later logging clock that might cross its deadline.
    const auto now=pads?sampled_at:GetTickCount64();
    char message[448]{};
    std::snprintf(message,sizeof(message),
        "assignment-revoke cause=%s from=%d,%d,g%llu to=%d,%d,g%llu dev=%u expired=%u now=%llu deadline=%llu device=%u applied=%u world=%llu prev_world=%llu sampled=%u p1=%u:%u/%d:%u p2=%u:%u/%d:%u buttons=%u,%u",
        cause,old.p1,old.p2,old.generation,p1,p2,generation,dev_enabled?1u:0u,
        dev_enabled && now>test_deadline?1u:0u,now,test_deadline,device_epoch.load(),applied_device_epoch,
        world_epoch,old.world,pads?1u:0u,a.connected?1u:0u,a.packet,pads?(c.connected?1:0):-1,c.packet,
        b.connected?1u:0u,b.packet,pads?(d.connected?1:0):-1,d.packet,
        static_cast<unsigned>(c.buttons),static_cast<unsigned>(d.buttons));
    log(message);
}
