// Only copied accounting crosses to this control thread; no engine objects or
// native calls. Disk IO never runs under the gameplay lock or inside a hook.
void flush_life_state() {
    if(!life_enabled || initialized.load()!=2)return;
    std::optional<life_disk::Record> pending;
    std::uint64_t recovery{};
    AcquireSRWLockShared(&lock);
    pending=life_journal.pending();recovery=life_recovery_revision;
    ReleaseSRWLockShared(&lock);
    if(!pending)return;
    life_disk::WriteResult result;
    try {result=recovery?life_store.recover_after_verified_rest(*pending):life_store.commit(*pending);}
    catch(...) {result={life_disk::Status::io_error,ERROR_WRITE_FAULT};}
    bool report_failure{},report_recovery{};
    AcquireSRWLockExclusive(&lock);
    if(result) {
        ++life_disk_commits;life_journal.acknowledge(*pending);
        if(life_recovery_revision && life_recovery_revision<=pending->revision)life_recovery_revision=0;
        report_recovery=life_disk_error;life_disk_error=false;
    } else {++life_disk_failures;report_failure=!life_disk_error;life_disk_error=true;}
    ReleaseSRWLockExclusive(&lock);
    if(report_failure)log("shared lives: state could not be saved; pending count retained for retry (check folder access)");
    if(report_recovery)log("shared lives: persistent state saved successfully again");
}
