DWORD WINAPI device_watch(void*) {
    HMODULE module{};
    if(!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(&device_watch),&module)) return 1;
    WNDCLASSW cls{};cls.lpfnWndProc=device_window;cls.hInstance=module;cls.lpszClassName=L"DDDACoopDeviceWatch02";
    if(!RegisterClassW(&cls)) return 1;
    // A hidden top-level window receives device-node broadcasts; message-only
    // windows do not. This thread never reads or writes an engine object.
    HWND window=CreateWindowExW(WS_EX_TOOLWINDOW,cls.lpszClassName,L"",WS_POPUP,0,0,0,0,nullptr,nullptr,module,nullptr);
    if(!window) return 1;
    if(life_enabled && !SetTimer(window,1,100,nullptr)){DestroyWindow(window);return 1;}
    device_watch_ready=true;
    MSG message{};
    while(GetMessageW(&message,nullptr,0,0)>0) {TranslateMessage(&message);DispatchMessageW(&message);}
    device_watch_ready=false;return 0;
}
bool watch_devices() {
    HANDLE thread=CreateThread(nullptr,0,device_watch,nullptr,0,nullptr);
    if(!thread) return false;
    const auto deadline=GetTickCount64()+1000;
    while(!device_watch_ready.load() && GetTickCount64()<deadline && WaitForSingleObject(thread,10)==WAIT_TIMEOUT) {}
    CloseHandle(thread);return device_watch_ready.load();
}
bool copy_input_boundary(const CoopInputBoundary* source,unsigned size,CoopInputBoundary& out) {
    if(!source || size!=sizeof(out))return false;
    __try {out=*source;}
    __except(EXCEPTION_EXECUTE_HANDLER) {return false;}
    return out.size==sizeof(out) && out.version==1 && out.get && out.caps && out.rumble;
}
bool input_entry_in_module(FARPROC entry,HMODULE module) {
    HMODULE owner{};MEMORY_BASIC_INFORMATION memory{};
    if(!entry || !GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
       reinterpret_cast<LPCWSTR>(entry),&owner) || owner!=module ||
       !VirtualQuery(reinterpret_cast<const void*>(entry),&memory,sizeof(memory)) || memory.State!=MEM_COMMIT ||
       (memory.Protect&(PAGE_GUARD|PAGE_NOACCESS)))return false;
    const auto access=memory.Protect&0xffu;
    return access==PAGE_EXECUTE || access==PAGE_EXECUTE_READ || access==PAGE_EXECUTE_READWRITE || access==PAGE_EXECUTE_WRITECOPY;
}
bool canonical_input_boundary(const CoopInputBoundary& candidate,const void* caller,HMODULE& loader) {
    if(!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
       reinterpret_cast<LPCWSTR>(caller),&loader))return false;
    wchar_t canonical[MAX_PATH]{},loaded[MAX_PATH]{};
    const DWORD exe_length=GetModuleFileNameW(nullptr,canonical,MAX_PATH);
    const DWORD loader_length=GetModuleFileNameW(loader,loaded,MAX_PATH);
    if(!exe_length || exe_length>=MAX_PATH || !loader_length || loader_length>=MAX_PATH)return false;
    auto separator=std::wcsrchr(canonical,L'\\');
    if(!separator || wcscpy_s(separator+1,MAX_PATH-static_cast<std::size_t>(separator+1-canonical),L"xinput1_3.dll") ||
       _wcsicmp(canonical,loaded))return false;
    const FARPROC entries[]{reinterpret_cast<FARPROC>(candidate.get),reinterpret_cast<FARPROC>(candidate.caps),
        reinterpret_cast<FARPROC>(candidate.rumble)};
    const char* names[]{"XInputGetState","XInputGetCapabilities","XInputSetState"};
    for(unsigned i=0;i<std::size(entries);++i)
        if(!input_entry_in_module(entries[i],loader) || entries[i]!=GetProcAddress(loader,names[i]))return false;
    // Reject a foreign XInput forwarding DLL with no co-op loader identity.
    return input_entry_in_module(GetProcAddress(loader,"CoopLoaderGetStatus"),loader);
