bool fingerprint() {
    if(reinterpret_cast<std::uintptr_t>(GetModuleHandleW(nullptr))!=0x400000) return false;
    wchar_t file[MAX_PATH]{};
    if(!GetModuleFileNameW(nullptr,file,MAX_PATH)) return false;
    HANDLE input=CreateFileW(file,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
    if(input==INVALID_HANDLE_VALUE) return false;
    BCRYPT_ALG_HANDLE alg{}; BCRYPT_HASH_HANDLE hash{};
    bool ok=BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,0)>=0;
    if(ok) ok=BCryptCreateHash(alg,&hash,nullptr,0,nullptr,0,0)>=0;
    std::array<unsigned char,65536> buffer{};
    DWORD read{};
    while(ok) {
        if(!ReadFile(input,buffer.data(),static_cast<DWORD>(buffer.size()),&read,nullptr)) {ok=false;break;}
        if(!read) break;
        ok=BCryptHashData(hash,buffer.data(),read,0)>=0;
    }
    std::array<unsigned char,32> digest{};
    if(ok) ok=BCryptFinishHash(hash,digest.data(),static_cast<ULONG>(digest.size()),0)>=0;
    if(hash) BCryptDestroyHash(hash);
    if(alg) BCryptCloseAlgorithmProvider(alg,0);
    CloseHandle(input);
    char hex[65]{};
    for(unsigned i=0;i<digest.size();++i) std::snprintf(hex+i*2,3,"%02x",digest[i]);
    return ok && std::strcmp(hex,coop::build::sha256)==0;
}
bool signatures() {
    auto base=reinterpret_cast<unsigned char*>(GetModuleHandleW(nullptr));
    auto dos=reinterpret_cast<IMAGE_DOS_HEADER*>(base);
    if(dos->e_magic!=IMAGE_DOS_SIGNATURE) return false;
    auto pe=reinterpret_cast<IMAGE_NT_HEADERS*>(base+dos->e_lfanew);
    if(pe->Signature!=IMAGE_NT_SIGNATURE || pe->FileHeader.Machine!=IMAGE_FILE_MACHINE_I386) return false;
    auto section=IMAGE_FIRST_SECTION(pe);
    for(const auto& thunk:coop::build::input_thunks) {
        unsigned count{};
        for(unsigned j=0;j<pe->FileHeader.NumberOfSections;++j)
            if(section[j].Characteristics&IMAGE_SCN_MEM_EXECUTE)
                count+=static_cast<unsigned>(coop::signature_count({base+section[j].VirtualAddress,section[j].Misc.VirtualSize},thunk.bytes));
        if(count!=1 || std::memcmp(base+thunk.rva,thunk.bytes.data(),thunk.bytes.size())) {log(thunk.name);return false;}
    }
    for(const auto& sym:coop::build::symbols) {
        unsigned count{};
        for(unsigned j=0;j<pe->FileHeader.NumberOfSections;++j) {
            if(section[j].Characteristics & IMAGE_SCN_MEM_EXECUTE)
                count+=static_cast<unsigned>(coop::signature_count({base+section[j].VirtualAddress,section[j].Misc.VirtualSize},sym.bytes));
        }
        // EXP071: this one shared prefix is fixed-RVA checked together with
        // its adjacent unique body; never discover the hook by prefix alone.
        const unsigned expected_count=std::strcmp(sym.name,"dialogue_close_entry")==0?2u:1u;
        if(count!=expected_count || std::memcmp(base+sym.rva,sym.bytes.data(),sym.bytes.size())) {log(sym.name);return false;}
    }
    return true;
}
