    menu_current_known=known;menu_current_gameplay=current;
    const bool canonical=menu_native_known && menu_native_gameplay && now>=menu_native_observed && now-menu_native_observed<150;
    const auto phase=menu_lease.phase();
    const auto inventory=inventory_lifetime.observation(world_epoch);
    const bool typed_modal=inventory.state==coop::shared_menu::InventoryState::active || inventory.state==coop::shared_menu::InventoryState::closing;
    menu_input={pads,routing.p1,routing.p2,routing.generation,world_epoch,device_epoch.load(),now,
        healthy && known,has_focus,!typed_modal && current && canonical &&
            dialogue_root.state!=coop::dialogue_menu::RootState::active && dialogue_root.state!=coop::dialogue_menu::RootState::unowned,
        routing.state==coop::SessionState::joined && native_gameplay && !configuration.p1_keyboard_mouse,
        routing.swap_input_consumed || routing.swap_neutral_required || routing.controllers_swapped,
        inventory};
