    row[17]=static_cast<unsigned>(s.info);row[18]=static_cast<unsigned>(s.list);row[19]=static_cast<unsigned>(s.node);
    row[20]=static_cast<unsigned>(s.action);row[21]=s.action_id;row[22]=s.pending;row[23]=s.downed;
    row[24]=s.downed_ed;row[25]=s.terminal;row[26]=s.blocked;row[27]=s.terminal_state;
    std::memcpy(&row[28],&s.hp,sizeof(s.hp));
