// Read immutable native skill tables and this pawn's learning bits only at its
// established actor callback. Empty/unknown metadata never indexes native arrays.
void capture_skills(std::uintptr_t actor,std::uintptr_t info) {
    SkillFrame next{actor,world_epoch,routing.generation,GetTickCount64()};
    if(routing.state!=coop::SessionState::joined || !gameplay){skill_frame={};return;}
    next.valid=true;
    next.warrior_supported=coop::warrior::supported(at<unsigned char>(info,0x10),at<unsigned>(info,0x14));
    next.fighter_supported=coop::fighter::supported(at<unsigned char>(info,0x10),at<unsigned>(info,0x14),at<unsigned>(info,0x18));
    next.shield_supported=next.fighter_supported && coop::fighter::secondary_supported(at<unsigned char>(info,0x10),at<unsigned>(info,0x18));
    next.primary_supported=next.warrior_supported || (next.fighter_supported && coop::fighter::primary_supported(at<unsigned char>(info,0x10),at<unsigned>(info,0x14))) ||
        coop::bow::dagger(at<unsigned char>(info,0x10),at<unsigned>(info,0x14));
    next.mage_supported=coop::mage::caster_equipment(at<unsigned char>(info,0x10),at<unsigned>(info,0x14));
    for(unsigned i=0;i<6;++i) {
        auto& slot=next.slots[i];slot.id=at<int>(info,0x270+i*4);
        if(slot.id==-1)continue;
