        const auto metadata=at<int>(0x14f3670,static_cast<unsigned>(slot.id)*32+4);
        if(metadata<0 || metadata>=149){next.valid=false;break;}
        const auto record=0x1520278u+static_cast<unsigned>(metadata)*12;
        const auto flags=at<unsigned short>(record,10);
        const auto word=static_cast<unsigned>(slot.id)/32*4,bit=1u<<(slot.id%32);
        const auto learned=info+0x72c;
