            (at<unsigned>(learned,0x3c+word)&bit)!=0,(at<unsigned>(learned,0x74+word)&bit)!=0);
        if(next.mage_supported && coop::mage::learned_rank_eligible(slot.id,level) &&
           mage_slot(info,slot.id)==static_cast<int>(i))next.mage_available|=1u<<i;
        slot.index=coop::skills::message(at<short>(record),flags,level);
        if(slot.index<0 || slot.index>=4096){next.valid=false;break;}
    }
