bool coop::split::pawn_visual(void* unit) {
    const auto p=reinterpret_cast<std::uintptr_t>(unit);
    AcquireSRWLockShared(&lock);
    bool selected{};
    __try {
        const auto pawn=actor_identity[1];
        selected=pawn && p==pawn;
        // EXP-010: weapon/lantern parent and custom cloth source model. Read only;
        // never retain these scene-owned attachment pointers between draws.
        if(pawn && !selected) {
            const auto type=at<unsigned>(p);
            if(type==0x1602730)selected=at<std::uintptr_t>(p,0x30)==pawn;
            else if(type==0x159f198)selected=at<std::uintptr_t>(p,0x1e0)==pawn;
            else if(type==0x1603dd8)selected=at<std::uintptr_t>(p,0x30)==pawn &&
                at<std::uintptr_t>(pawn,0x3d6c)==p;
        }
    } __finally {ReleaseSRWLockShared(&lock);}
    return selected;
}
