// Research provider boundary: no actor pointers or game writes. Expires after
// two seconds unless refreshed. Unavailable unless explicitly configured.
extern "C" __declspec(dllexport) int __cdecl CoopSetTestPads(const coop::DeviceSample* pads,unsigned count) {
    if(!dev_enabled || !pads || count!=4 || initialized.load()!=2) return 0;
    AcquireSRWLockExclusive(&lock);
    for(unsigned i=0;i<4;++i) test_pads[i]=pads[i];
    std::uint64_t tick{};
    if(latency_tick(tick)) {
        std::array<latency::Values,4> values{};
        for(unsigned i=0;i<4;++i) {
            const auto& p=test_pads[i];values[i]={p.connected,p.buttons,p.lx,p.ly,p.rx,p.ry,p.lt,p.rt};
        }
        if(latency_sequence==std::numeric_limits<std::uint64_t>::max()) {
            latency_tracker.seal(tick);latency_running=false;
        } else {
            const auto next=latency_sequence+1;
            if(latency_tracker.publish(next,tick,values).accepted)latency_sequence=next;
        }
    }
    test_deadline=GetTickCount64()+2000;poll_at=0;
    ReleaseSRWLockExclusive(&lock);return 1;
}
// Cached-value request only, like the controller provider. No engine reads,
// writes or calls from RPC. At most half a second; cannot outlive ownership.
extern "C" __declspec(dllexport) int __cdecl CoopTestMageViewGap(unsigned duration_ms) {
    if(!dev_enabled || initialized.load()!=2 || duration_ms<100 || duration_ms>500)return 0;
    int result{};
    AcquireSRWLockExclusive(&lock);
    const auto now=GetTickCount64();
    if(!mage_view_gap.until && routing.state==coop::SessionState::joined && mage_bound.healthy &&
       mage_frame.ready && mage_frame.view.active && now>=mage_bound.when && now-mage_bound.when<=100 &&
       now>=mage_frame.view.when && now-mage_frame.view.when<=100 &&
       (mage_status.state==2 || mage_status.state==5)) {
        mage_view_gap={mage_frame.view,now+duration_ms,mage_bound.lifetime,routing.generation};result=1;
    }
    ReleaseSRWLockExclusive(&lock);return result;
}
// Additive copied-state diagnostics; never dereference game objects from RPC.
extern "C" __declspec(dllexport) int __cdecl CoopGetCollectEligibilityStatus(coop::pickup::Status* out,unsigned size) {
    if(!out || size!=sizeof(*out))return 0;
    AcquireSRWLockShared(&lock);*out=pickup_status;
    const auto now=GetTickCount64();
    out->age=pickup_frame.when && now>=pickup_frame.when?
        static_cast<unsigned>(std::min<std::uint64_t>(now-pickup_frame.when,0xffffffffu)):0xffffffffu;
    out->ready=out->ready && coop::pickup::fresh(pickup_frame,now,world_epoch,routing.generation,pickup_input_serial) &&
        routing.state==coop::SessionState::joined && !status.menu_gated && !faults.load();
    ReleaseSRWLockShared(&lock);return 1;
}

