#include "coop/session.hpp"
namespace coop {

bool Session::release_pawn() {
    forget_menu();
    swap_shortcut_.cancel();
    pawn_neutral_required_=false;
    join_since_.fill(0);
    if (p2_ < 0 && desired_p2_ < 0) return false;
    release_recovery_ = true;
    recovery_neutral_.fill(false);
    p2_ = desired_p2_ = -1;
    ++generation_;
    return true;
}

bool Session::release_pawn_temporarily() {
    if (p2_ < 0) return false;
    forget_menu();
    swap_shortcut_.cancel();
    desired_p2_ = p2_;
    p2_ = -1;
    pawn_neutral_required_=false;
    release_recovery_ = true;
    recovery_neutral_.fill(false);
    join_since_.fill(0);
    blocked_buttons_ = 0;
    ++generation_;
    return true;
}

void Session::world_changed(std::uint64_t world) {
    if (initialized_ && world_ == world) return;
    world_ = world;
    initialized_ = true;
    swap_shortcut_.cancel();
    // Even a solo epoch change invalidates outstanding actor/action frames.
    if (!release_pawn_temporarily()) ++generation_;
    pawn_neutral_required_=false;
    release_recovery_ = true;
    recovery_neutral_.fill(false);
    join_since_.fill(0);
    blocked_buttons_ = 0;
}

void Session::invalidate() {
    forget_menu();
    swap_shortcut_.reset();
    pawn_neutral_required_=false;
    p1_ = p2_ = desired_p2_ = -1;
    reserved_p1_ = -1;
    release_recovery_ = false;
    recovery_neutral_.fill(false);
    join_since_.fill(0);
    // After a device topology change the old slot's button history cannot
    // establish an edge for its replacement. Observe release before assignment.
    previous_.fill({});
    blocked_buttons_ = 0;
    suppress_start_ = false;
    ++generation_;
}
void Session::devices_changed() {
    swap_shortcut_.cancel();
    join_since_.fill(0);
    recovery_neutral_.fill(false);
    // A generic device broadcast is not controller loss and must not turn an
    // ongoing held gameplay action into a synthetic release. Preserve any
    // preexisting menu/recall barrier; actual copied loss/reset still revokes
    // ownership in update().
    if(reserved_p1_>=0)release_recovery_=true;
}
Routing Session::update(const std::array<DeviceSample, 4>& pads, std::uint64_t now,
                        bool offline, bool gameplay, bool focused, std::uint64_t world,bool menu_pause) {
    if (initialized_ && world_ != world) {
        world_changed(world);
    }
    world_ = world;
    initialized_ = true;
    // Native keyboard/mouse is present independently of controller topology.
    // No physical Start may claim P1 in this optional mode.
    if(p1_keyboard_mouse_ && p1_!=keyboard_mouse_role) {
        p1_=keyboard_mouse_role;reserved_p1_=-1;++generation_;
    }
    auto lost = [&](int slot) {
        if (!controller_slot(slot)) return false;
        const auto i = static_cast<unsigned>(slot);
        // XInput exposes slots, not durable hardware IDs. Packet wrap is allowed.
        return !pads[i].connected || (previous_[i].connected &&
            pads[i].packet < previous_[i].packet && previous_[i].packet - pads[i].packet < 0x80000000u);
    };
    const bool p1_lost = lost(p1_);
    // A retired actor must not hide disconnect/reset of its remembered device.
    const bool p2_lost = lost(desired_p2_);
    if (p1_lost) {
        const auto former_p1=p1_;
        invalidate();
        // A P2 rejoin must not silently become the Arisen after P1 loss. Keep
        // the most recent intentional mapping, including deliberate swaps.
        reserved_p1_=former_p1;
        release_recovery_=true;
    }
    else if (p2_lost) release_pawn();
    // Explicit leave also works while the pawn is absent or recovery is gated.
    if (desired_p2_ >= 0 && (pads[static_cast<unsigned>(desired_p2_)].buttons & (start_button | back_button)) == (start_button | back_button)) {
        release_pawn();
    }
    bool reclaimed{};
    if (pawn_recovery_pending() && p1_ >= 0 && offline && gameplay && focused &&
        controls_neutral(pads[static_cast<unsigned>(desired_p2_)], false)) {
        p2_ = desired_p2_;
        ++generation_;
        reclaimed = true;
        release_recovery_ = false;
        recovery_neutral_.fill(false);
        join_since_.fill(0);
    }
    for (unsigned i = 0; i < pads.size(); ++i) {
        const bool start = pads[i].connected && (pads[i].buttons & start_button) != 0;
        const bool packet_reset = previous_[i].connected && pads[i].packet < previous_[i].packet &&
            previous_[i].packet - pads[i].packet < 0x80000000u;
        const bool edge = start && previous_[i].connected && !packet_reset && !(previous_[i].buttons & start_button);
        // Require a release after first observation/connection. A held button on
        // a newly enumerated device must not silently claim an actor.
        if (p1_ < 0 && reserved_p1_<0 && focused && edge && !p1_lost) { p1_ = static_cast<int>(i); suppress_start_=true; ++generation_; }
        // Initial joins have the same neutral-control and device-identity
        // requirements as rejoining. Never carry a hold across a reset or a
        // conflicting input; a new Start edge is required to try again.
        if (static_cast<int>(i) != p1_ && p2_ < 0 && desired_p2_ < 0 &&
            (packet_reset || !controls_neutral(pads[i], true))) {
            recovery_neutral_[i] = false;
            join_since_[i] = 0;
            continue;
        }
        if (release_recovery_ && static_cast<int>(i) != p1_) {
            if (!pads[i].connected) {
                recovery_neutral_[i] = false;
                join_since_[i] = 0;
                continue;
            }
            if (packet_reset) {
                recovery_neutral_[i] = false;
                join_since_[i] = 0;
                continue;
            }
            if (!recovery_neutral_[i]) {
                if (!controls_neutral(pads[i], false)) {
                    join_since_[i] = 0;
                    continue;
                }
                recovery_neutral_[i] = true;
            } else if (!controls_neutral(pads[i], true)) {
                recovery_neutral_[i] = false;
                join_since_[i] = 0;
                continue;
            }
        }
        if(p1_<0 && reserved_p1_>=0) {
            const bool retained=static_cast<int>(i)==reserved_p1_;
            // Only the remembered P1 gets the ordinary fresh-Start assignment.
            // Replacing it from another slot is explicit and longer than a P2
            // join, and is available only while the remembered slot is absent.
            const bool replacement=!retained && !pads[static_cast<unsigned>(reserved_p1_)].connected;
            if(!focused || !start || (pads[i].buttons&back_button) || p1_lost ||
               (join_since_[i] && now<join_since_[i]) ||
               (!retained && (!replacement || !offline || !gameplay))) {
                join_since_[i]=0;
                continue;
            }
            if(edge)join_since_[i]=now;
            if((edge && retained) || (!retained && join_since_[i] && now>=join_since_[i] && now-join_since_[i]>=3000)) {
                p1_=static_cast<int>(i);reserved_p1_=-1;suppress_start_=true;
                ++generation_;join_since_.fill(0);
                // P2 still needs its own released controls and fresh join.
            }
            continue;
        }
        if (static_cast<int>(i) == p1_ || !start || (pads[i].buttons & back_button) || !focused || !offline || !gameplay) {
            join_since_[i] = 0;
            continue;
        }
        if (edge && p1_ >= 0 && p2_ < 0 && desired_p2_ < 0 && !p1_lost && !p2_lost) join_since_[i] = now;
        if (p2_ < 0 && desired_p2_ < 0 && join_since_[i] && now >= join_since_[i] && now - join_since_[i] >= join_hold_ms_) {
            p2_ = desired_p2_ = static_cast<int>(i); ++generation_; join_since_.fill(0);
            release_recovery_ = false;
            recovery_neutral_.fill(false);
        }
    }
    std::array<SwapPad,2> swap_pads{};
    const bool swap_eligible=!p1_keyboard_mouse_ && p1_>=0 && p2_>=0 && focused && offline && gameplay &&
        !reclaimed && !pawn_neutral_required_;
    const std::array<int,2> roles{p1_,p2_};
    for(unsigned role=0;role<roles.size();++role) {
        if(!controller_slot(roles[role])) {swap_pads[role].neutral=true;continue;}
        const auto& raw=pads[static_cast<unsigned>(roles[role])];
        auto stripped=raw;
        const bool prefix=(raw.buttons&swap_prefix_buttons)==swap_prefix_buttons && !(raw.buttons&start_button);
        if(prefix) {
            stripped.buttons &= static_cast<std::uint16_t>(~swap_buttons);
            // Clicking a stick often tilts it. Both clicks explicitly reserve
            // this controller's axes and both routed streams are neutralized
            // during the valid hold. Keep other buttons/triggers and the other
            // controller's active input as conflicts; release still uses the
            // configured gameplay deadzones on the complete original sample.
            stripped.lx=stripped.ly=stripped.rx=stripped.ry=0;
        }
        swap_pads[role]={
            prefix,
            (raw.buttons&swap_buttons)==swap_buttons,
            !raw.connected || controls_neutral(raw,false),controls_neutral(stripped,false)};
    }
    const auto swap=swap_shortcut_.update(swap_pads,now,swap_eligible);
    if(swap.swap) {
        forget_menu();
        const auto former_p1=p1_;
        p1_=p2_;
        p2_=desired_p2_=former_p1;
        // Invalidate every outstanding pawn action/camera frame. Device packet
        // history stays attached to physical slots; future loss uses new roles.
        ++generation_;
        join_since_.fill(0);
        recovery_neutral_.fill(false);
        blocked_buttons_=0;
        suppress_start_=false;
    }
    Routing out{};
    out.controllers_swapped=swap.swap;
    out.swap_input_consumed=swap.consume || swap.mask_shortcut[0] || swap.mask_shortcut[1];
    out.swap_neutral_required=swap.release_required;
    out.p1 = p1_; out.p2 = p2_; out.generation = generation_;
    const bool active = p1_ >= 0 && p2_ >= 0 && focused && offline && gameplay;
    const bool resumable_menu=!gameplay && menu_pause && p1_>=0 && p2_>=0 && focused && offline &&
        !pawn_neutral_required_ && !swap.consume && !swap.release_required && (active_ || menu_paused_);
    if(resumable_menu) {
        if(!menu_paused_)for(unsigned role=0;role<2;++role)menu_controls_[role].begin(last_gameplay_[role]);
        menu_paused_=true;
        for(unsigned role=0;role<2;++role)menu_controls_[role].observe(role_sample(pads,role?p2_:p1_));
        out.menu_suspended=true;
    } else if(active && menu_paused_) {
        for(unsigned role=0;role<2;++role)menu_controls_[role].observe(role_sample(pads,role?p2_:p1_));
        out.menu_resumed=true;
        menu_paused_=false;
    } else if(!active) {
        // Focus, health, uncertain native state, identity or safety interruption
        // discards continuity. An overlapping menu cannot weaken that barrier.
        menu_paused_=false;
    }
    if(p2_>=0) {
        const auto buttons=pads[static_cast<unsigned>(p2_)].buttons;
        if(!active && !resumable_menu) { blocked_buttons_=buttons; pawn_neutral_required_=true; }
        else blocked_buttons_ &= buttons; // held through a pause needs a release
    } else blocked_buttons_=0;
    out.neutralize = active_ && !active;
    active_ = active;
    out.state = p1_ < 0 ? SessionState::awaiting_p1 : p2_ < 0 ? SessionState::solo : active ? SessionState::joined : SessionState::suspended;
    if (p1_ >= 0 && focused) {
        out.arisen = role_sample(pads,p1_);
        if (!(out.arisen.buttons & start_button)) suppress_start_=false;
        if (suppress_start_) out.arisen.buttons &= ~start_button;
    }
    if (active) {
        out.pawn = pads[static_cast<unsigned>(p2_)];
        out.pawn.buttons &= ~blocked_buttons_;
        if(reclaimed) out.pawn=DeviceSample{true};
        if(pawn_neutral_required_) {
            if(controls_neutral(pads[static_cast<unsigned>(p2_)],false))pawn_neutral_required_=false;
            out.pawn=DeviceSample{true};
        }
    }
    if(active) {
        // Held gameplay controls retain their existing action; controls first
        // pressed (or released and pressed again) inside a menu are quarantined
        // individually. Returning movement never depends on another control.
        menu_controls_[0].filter(out.arisen);
        menu_controls_[1].filter(out.pawn);
    }
    if(swap.consume) {
        // Include P1 native XInput and P2 camera/movement/buttons. No shortcut
        // release or previously held action may reach either actor on handoff.
        if(out.arisen.connected)out.arisen=DeviceSample{true};
        if(out.pawn.connected)out.pawn=DeviceSample{true};
    } else {
        if(swap.mask_shortcut[0])out.arisen.buttons &= static_cast<std::uint16_t>(~swap_buttons);
        if(swap.mask_shortcut[1])out.pawn.buttons &= static_cast<std::uint16_t>(~swap_buttons);
    }
    previous_ = pads;
    if(active && !swap.consume)last_gameplay_={out.arisen,out.pawn};
    return out;
}
}

