#include "coop/settings.hpp"
#include <algorithm>
#include <charconv>
#include <cmath>
#include <fstream>
#include <set>

namespace coop {
namespace {
std::string_view trim(std::string_view s) {
    const auto first=s.find_first_not_of(" \t\r");
    if(first==s.npos)return {};
    return s.substr(first,s.find_last_not_of(" \t\r")-first+1);
}
std::string lower(std::string_view s) {
    std::string out(s);
    for(auto& c:out)if(c>='A' && c<='Z')c=static_cast<char>(c-'A'+'a');
    return out;
}
bool number(std::string_view text,float& out,float minimum,float maximum) {
    float v{};
    const auto result=std::from_chars(text.data(),text.data()+text.size(),v);
    if(result.ec!=std::errc{} || result.ptr!=text.data()+text.size() || !std::isfinite(v) || v<minimum || v>maximum)return false;
    out=v;return true;
}
bool boolean(std::string_view text,bool& out) {
    if(text!="0" && text!="1")return false;
    out=text=="1";return true;
}
}
SettingsResult parse_settings(std::string_view text) {
    SettingsResult out;
    auto error=[&](unsigned line,std::string_view message) {
        out.valid=false;
        if(out.diagnostics.size()<32)out.diagnostics.push_back("line "+std::to_string(line)+": "+std::string(message));
    };
    if(text.size()>16384 || text.find('\0')!=text.npos) {
        error(0,"settings must be plain UTF-8 text, at most 16 KiB");return out;
    }
    if(text.starts_with("\xef\xbb\xbf"))text.remove_prefix(3);
    std::string section;
    std::set<std::string> seen;
    unsigned line{};
    while(!text.empty()) {
        ++line;
        const auto end=text.find('\n');
        auto row=trim(text.substr(0,end));
        text=end==text.npos?std::string_view{}:text.substr(end+1);
        row=trim(row.substr(0,row.find_first_of(";#")));
        if(row.empty())continue;
        if(row.front()=='[') {
            if(row.back()!=']'){error(line,"malformed section");continue;}
            section=lower(trim(row.substr(1,row.size()-2)));
            if(section!="coop" && section!="input" && section!="camera" && section!="feedback" && section!="recovery")error(line,"unknown section: "+section);
            continue;
        }
        const auto equal=row.find('=');
        if(equal==row.npos){error(line,"expected key=value");continue;}
        const auto key=section+"."+lower(trim(row.substr(0,equal)));
        const auto v=trim(row.substr(equal+1));
        if(!seen.insert(key).second){error(line,"duplicate setting: "+key);continue;}
        auto& s=out.values;
        bool good{};
        if(key=="coop.enabled")good=boolean(v,s.enabled);
        else if(key=="coop.online_mode")good=boolean(v,s.online_mode);
        else if(key=="coop.p2_npc_interaction")good=boolean(v,s.p2_npc_interaction);
        else if(key=="coop.developer_input")good=boolean(v,s.developer_input);
        else if(key=="coop.experimental_mage")good=boolean(v,s.experimental_mage);
        else if(key=="coop.max_distance")good=number(v,s.max_distance,1000.0f,20000.0f);
        else if(key=="coop.distance_action") {
            const auto value=lower(v);
            if(value=="ai"){s.distance_action=DistanceAction::ai;good=true;}
            else if(value=="teleport"){s.distance_action=DistanceAction::teleport;good=true;}
        }
        else if(key=="feedback.status_caption")good=boolean(v,s.status_caption);
        else if(key=="feedback.skill_hud")good=boolean(v,s.skill_hud);
        else if(key=="feedback.partner_sigils")good=boolean(v,s.partner_sigils);
        else if(key=="feedback.shared_life_hud")good=boolean(v,s.shared_life_hud);
        else if(key=="feedback.p2_enemy_health_bars")good=boolean(v,s.p2_enemy_health_bars);
        else if(key=="feedback.p2_ally_health_bars")good=boolean(v,s.p2_ally_health_bars);
        else if(key=="recovery.full_health_revive")good=boolean(v,s.full_health_revive);
        else if(key=="recovery.shared_lives")good=boolean(v,s.shared_lives);
        else if(key=="recovery.endless_lives")good=boolean(v,s.endless_lives);
        else if(key=="recovery.shared_life_count") {
            unsigned value{};
            const auto r=std::from_chars(v.data(),v.data()+v.size(),value);
            good=r.ec==std::errc{} && r.ptr==v.data()+v.size() && value<=99;
            if(good)s.shared_life_count=value;
        }
        else if(key=="input.p1_keyboard_mouse")good=boolean(v,s.p1_keyboard_mouse);
        else if(key=="input.join_hold_ms") {
            unsigned value{};
            const auto r=std::from_chars(v.data(),v.data()+v.size(),value);
            good=r.ec==std::errc{} && r.ptr==v.data()+v.size() && value>=500 && value<=3000;
            if(good)s.join_hold_ms=value;
        }
        else if(key=="input.movement_deadzone")good=number(v,s.movement_deadzone,0.05f,0.45f);
        else if(key=="input.camera_deadzone")good=number(v,s.camera_deadzone,0.05f,0.45f);
        else if(key=="camera.horizontal_sensitivity")good=number(v,s.camera_horizontal,0.25f,3.0f);
        else if(key=="camera.vertical_sensitivity")good=number(v,s.camera_vertical,0.25f,3.0f);
        else if(key=="camera.invert_horizontal")good=boolean(v,s.invert_horizontal);
        else if(key=="camera.invert_vertical")good=boolean(v,s.invert_vertical);
        else if(key=="camera.field_of_view")good=number(v,s.camera_fov,40.0f,75.0f);
        else if(key=="camera.distance")good=number(v,s.camera_distance,0.0f,380.0f) && (s.camera_distance==0 || s.camera_distance>=160.0f);
        else if(key=="camera.split_layout") {
            const auto value=lower(v);
            if(value=="vertical"){s.split_layout=SplitLayout::vertical;good=true;}
            else if(value=="horizontal"){s.split_layout=SplitLayout::horizontal;good=true;}
        }
        else {error(line,"unknown setting: "+key);continue;}
        if(!good)error(line,"invalid value for "+key);
    }
    // A typo cannot silently activate a partly understood control configuration.
    if(!out.valid)out.values=Settings{};
    return out;
}
SettingsResult read_settings(const std::filesystem::path& path) {
    std::ifstream input(path,std::ios::binary);
    if(!input)return {Settings{},false,{"ddcoop.ini is missing or unreadable; co-op disabled"}};
    std::string text(16385,'\0');
    input.read(text.data(),static_cast<std::streamsize>(text.size()));
    text.resize(static_cast<std::size_t>(input.gcount()));
    if(input.bad())return {Settings{},false,{"could not read ddcoop.ini; co-op disabled"}};
    return parse_settings(text);
}
float camera_axis(std::int16_t raw,float deadzone,float sensitivity,bool invert) {
    const float v=std::clamp(static_cast<float>(raw)/32767.0f,-1.0f,1.0f);
    if(std::abs(v)<=deadzone)return 0;
    return std::copysign((std::abs(v)-deadzone)/(1.0f-deadzone),v)*sensitivity*(invert?-1.0f:1.0f);
}
bool movement_outside_deadzone(std::int16_t x,std::int16_t y,float deadzone) {
    const float nx=std::clamp(static_cast<float>(x)/32767.0f,-1.0f,1.0f);
    const float ny=std::clamp(static_cast<float>(y)/32767.0f,-1.0f,1.0f);
    return nx*nx+ny*ny>deadzone*deadzone;
}
}

