// Exact native discovery bootstrap. Attach only publishes a bounded forwarding
// IAT bridge; runtime loading and initialization remain outside loader callbacks.
#include <windows.h>
#include <xinput.h>
#include <bcrypt.h>
#include <tlhelp32.h>
#include <intrin.h>
#include <array>
#include <atomic>
#include <cstdio>
#include <cstring>
#include <string>
#include <new>
#include "coop/loader_status.hpp"
#include "coop/supported_build.hpp"
#include "coop/system_xinput.hpp"
#include "coop/input_boundary.hpp"

#if !defined(_M_IX86)
