// Mapped-header/thunk identity only. Full file SHA256 and runtime checks run at
// the first verified native discovery call before logical behavior is enabled.
// Unknown headers, foreign IAT entries, or altered thunk bytes cause no writes.
bool boundary_image(void* image,unsigned mapped_size) noexcept {
    if(!image || mapped_size<23117824u)return false;
    __try {
        const auto base=static_cast<const unsigned char*>(image);
        const auto dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if(dos->e_magic!=IMAGE_DOS_SIGNATURE || dos->e_lfanew!=312)return false;
        const auto nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(base+312);
        const auto& file=nt->FileHeader;const auto& opt=nt->OptionalHeader;
        if(nt->Signature!=IMAGE_NT_SIGNATURE || file.Machine!=IMAGE_FILE_MACHINE_I386 ||
           file.NumberOfSections!=5 || file.TimeDateStamp!=1513180209u ||
           file.SizeOfOptionalHeader!=224 || file.Characteristics!=291 ||
           opt.Magic!=IMAGE_NT_OPTIONAL_HDR32_MAGIC || opt.ImageBase!=0x400000 ||
           opt.SizeOfImage!=23117824u || opt.SizeOfHeaders!=1024 ||
           opt.SectionAlignment!=4096 || opt.FileAlignment!=512 ||
           opt.NumberOfRvaAndSizes<=IMAGE_DIRECTORY_ENTRY_IMPORT ||
           opt.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].VirtualAddress!=19001224u ||
           opt.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].Size!=400)return false;
        constexpr unsigned thunk_rvas[]{0xee1b96,0xee1b9c,0xee1b90};
        constexpr unsigned slot_vas[]{0x139d40c,0x139d408,0x139d410};
        const FARPROC expected[]{reinterpret_cast<FARPROC>(raw_boundary.get),
            reinterpret_cast<FARPROC>(raw_boundary.caps),reinterpret_cast<FARPROC>(raw_boundary.rumble)};
        for(unsigned i=0;i<3;++i) {
            const auto thunk=base+thunk_rvas[i];
            if(thunk[0]!=0xff || thunk[1]!=0x25 ||
               *reinterpret_cast<const unsigned*>(thunk+2)!=slot_vas[i] ||
               *reinterpret_cast<FARPROC const*>(base+slot_vas[i]-0x400000)!=expected[i])return false;
        }
        const auto descriptor=reinterpret_cast<const IMAGE_IMPORT_DESCRIPTOR*>(base+19001384u);
        if(descriptor->OriginalFirstThunk!=19002652u || descriptor->Name!=19004146u ||
           descriptor->FirstThunk!=16372740u)return false;
        constexpr char import_name[]="XINPUT1_3.dll";
        for(unsigned i=0;i<sizeof(import_name);++i)
            if(base[19004146u+i]!=static_cast<unsigned char>(import_name[i]))return false;
        constexpr unsigned lookup[]{0x80000005,0x80000004,0x80000002,0x80000003,0};
        for(unsigned i=0;i<5;++i)
            if(reinterpret_cast<const unsigned*>(base+19002652u)[i]!=lookup[i])return false;
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER){return false;}
}
bool install_boundary(void* image,unsigned mapped_size,int fail_after=-1) noexcept {
    if(boundary_ready.load(std::memory_order_acquire) || !boundary_image(image,mapped_size))return false;
    auto base=static_cast<unsigned char*>(image);
    const unsigned slot_rvas[]{0xf9d40c,0xf9d408,0xf9d410};
    const FARPROC originals[]{reinterpret_cast<FARPROC>(raw_boundary.get),
        reinterpret_cast<FARPROC>(raw_boundary.caps),reinterpret_cast<FARPROC>(raw_boundary.rumble)};
    const FARPROC bridges[]{reinterpret_cast<FARPROC>(&boundary_get),
        reinterpret_cast<FARPROC>(&boundary_caps),reinterpret_cast<FARPROC>(&boundary_rumble)};
    DWORD protection{};
    if(!VirtualProtect(base+0xf9d408,12,PAGE_READWRITE,&protection))return false;
    unsigned changed{};
    for(;changed<3;++changed) {
        if(fail_after==static_cast<int>(changed))break;
        auto slot=reinterpret_cast<void* volatile*>(base+slot_rvas[changed]);
        if(InterlockedCompareExchangePointer(slot,reinterpret_cast<void*>(bridges[changed]),
            reinterpret_cast<void*>(originals[changed]))!=reinterpret_cast<void*>(originals[changed]))break;
    }
    DWORD ignored{};
    bool ok=changed==3;
    if(ok && !VirtualProtect(base+0xf9d408,12,protection,&ignored))ok=false;
    if(!ok) {
        // Only revert pointers this transaction actually installed. A foreign
        // writer's changed entry is never overwritten by rollback.
        while(changed) {
            --changed;auto slot=reinterpret_cast<void* volatile*>(base+slot_rvas[changed]);
            InterlockedCompareExchangePointer(slot,reinterpret_cast<void*>(originals[changed]),
                reinterpret_cast<void*>(bridges[changed]));
        }
        VirtualProtect(base+0xf9d408,12,protection,&ignored);
        return false;
    }
    boundary_ready.store(true,std::memory_order_release);
    return true;
}
