bool outside_callback() noexcept {
    const bool outside=coop::system_xinput::outside_loader_callback();
    if(!outside)++callbacks;
    return outside;
}
bool cache_backend() noexcept {
    if(backend.load(std::memory_order_acquire))return true;
    // A cold attach-time caller receives unavailable. It must not load a DLL or
    // wait for another resolver which may itself be waiting for the loader lock.
    if(!outside_callback())return false;
#if defined(DDCOOP_XINPUT_PROXY_TEST)
    // Pause before module work and before admission; other resolvers must be
    // able to finish without depending on this unadmitted caller.
    const HANDLE entered=test_cache_entered.exchange(nullptr);
    if(entered){SetEvent(entered);WaitForSingleObject(test_cache_release.load(),5000);}
#endif
    HMODULE real=coop::system_xinput::resolve();
    if(!real){last_error=GetLastError();return false;}
    for(unsigned i=0;i<names.size();++i) {
        FARPROC p=coop::system_xinput::symbol(names[i]);
        if(!p){last_error=ERROR_PROC_NOT_FOUND;return false;}
        entries[i].store(p,std::memory_order_release);
    }
    for(unsigned i=0;i<opaque_entries.size();++i)
        opaque_entries[i].store(coop::system_xinput::symbol(static_cast<WORD>(100+i)),std::memory_order_release);
    backend.store(real,std::memory_order_release);
    return true;
}
struct Admission {
    bool held{};
    Admission() noexcept {
        unsigned value=admission.load(std::memory_order_acquire);
        while(!(value&1u)) {
            if(admission.compare_exchange_weak(value,value+2,std::memory_order_acq_rel)) {
                held=true;++admitted_depth;return;
            }
        }
        ++gated;
        if(admitted_depth || owner.load()==GetCurrentThreadId())++reentries;
    }
    ~Admission() {if(held){--admitted_depth;admission.fetch_sub(2,std::memory_order_release);}}
    Admission(const Admission&)=delete;
    Admission& operator=(const Admission&)=delete;
};
bool drain() noexcept {
    admission.fetch_or(1u,std::memory_order_acq_rel);
    const auto deadline=GetTickCount64()+1000;
    while(admission.load(std::memory_order_acquire)!=1u) {
        if(GetTickCount64()>=deadline)return false;
        Sleep(0);
    }
    return true;
}
bool hash_matches(const wchar_t* file,const char* expected) {
    HANDLE input=CreateFileW(file,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
    if(input==INVALID_HANDLE_VALUE)return false;
    BCRYPT_ALG_HANDLE alg{};BCRYPT_HASH_HANDLE hash{};
    bool ok=BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,0)>=0;
    if(ok)ok=BCryptCreateHash(alg,&hash,nullptr,0,nullptr,0,0)>=0;
    std::array<unsigned char,65536> buffer{};DWORD read{};
    while(ok) {
        if(!ReadFile(input,buffer.data(),static_cast<DWORD>(buffer.size()),&read,nullptr)){ok=false;break;}
        if(!read)break;
        ok=BCryptHashData(hash,buffer.data(),read,0)>=0;
    }
    std::array<unsigned char,32> digest{};
    if(ok)ok=BCryptFinishHash(hash,digest.data(),static_cast<ULONG>(digest.size()),0)>=0;
    if(hash)BCryptDestroyHash(hash);
    if(alg)BCryptCloseAlgorithmProvider(alg,0);
    CloseHandle(input);
    char hex[65]{};
    for(unsigned i=0;i<digest.size();++i)std::snprintf(hex+i*2,3,"%02x",digest[i]);
    return ok && !std::strcmp(hex,expected);
}
bool module_path(HMODULE module,std::wstring& path) {
    wchar_t file[MAX_PATH]{};
    const DWORD length=GetModuleFileNameW(module,file,MAX_PATH);
    if(!length || length>=MAX_PATH)return false;
    path.assign(file,length);return true;
}
