bool native_chain(PVOID const* frames,unsigned count) noexcept {
    if(count>32)return false;
    for(unsigned i=0;i<count;++i) {
        const auto frame=reinterpret_cast<std::uintptr_t>(frames[i]);
        // The overlay's real frame records this verified native call return.
        // DDDA then uses EBP as its object pointer, so the x86 OS walker can
        // legitimately stop here without returning the outer constructor frame.
        if(frame==discovery_return)return true;
    }
    return false;
}
unsigned capture_stack(PVOID* frames) noexcept {
    // Windows stack walker, not an ESP/EBP scan or guessed overlay offsets.
    // An x86 FPO chain may be incomplete: absence keeps bootstrap inert.
    __try {return CaptureStackBackTrace(0,32,frames,nullptr);}
    __except(EXCEPTION_EXECUTE_HANDLER){return 0;}
}
void sample_capture(PVOID const* frames,unsigned count,bool native) noexcept {
    auto& claimed=native?native_capture_claimed:first_capture_claimed;
    bool expected=false;
    if(!claimed.compare_exchange_strong(expected,true))return;
    auto& stored=native?native_frames:first_frames;
    for(unsigned i=0;i<count;++i)stored[i].store(static_cast<unsigned>(reinterpret_cast<std::uintptr_t>(frames[i])),std::memory_order_relaxed);
    (native?native_capture_count:first_capture_count).store(count,std::memory_order_release);
}
bool duplicate_runtime(const std::wstring& canonical) {
    HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE,GetCurrentProcessId());
    if(snapshot==INVALID_HANDLE_VALUE)return true; // Cannot establish uniqueness.
    MODULEENTRY32W entry{};entry.dwSize=sizeof(entry);
    bool duplicate=false;
    if(!Module32FirstW(snapshot,&entry)){CloseHandle(snapshot);return true;}
    do {
        // The old runtime has these two distinctive public APIs even before the
        // new identity export existed. Never call a foreign initializer.
        if(GetProcAddress(entry.hModule,"CoopInitialize") && GetProcAddress(entry.hModule,"CoopGetStatus") &&
           _wcsicmp(entry.szExePath,canonical.c_str())) {duplicate=true;break;}
    } while(Module32NextW(snapshot,&entry));
    CloseHandle(snapshot);return duplicate;
}
void initialize_native(std::uintptr_t caller) {
    if(bootstrap.load(std::memory_order_acquire)!=0)return;
    // This predicate is a fail-closed Windows internal callout check, not an
    // arbitrary-thread loader-lock ownership query. Native startup stack/order
    // evidence remains part of acceptance for the declared supported profile.
    if(!outside_callback())return;
    std::array<PVOID,32> frames{};
    const unsigned count=capture_stack(frames.data());
    sample_capture(frames.data(),count,false);
    const bool captured_native=native_chain(frames.data(),count);
    if(caller!=discovery_return && !captured_native)return;
    if(captured_native)sample_capture(frames.data(),count,true);
    ++discoveries;
    if(admitted_depth){++reentries;return;}
    int expected=0;
    if(!bootstrap.compare_exchange_strong(expected,1,std::memory_order_acq_rel))return;
    owner=GetCurrentThreadId();++attempts;
    if(!drain()) {
        last_error=ERROR_TIMEOUT;bootstrap=-8;admission.fetch_and(~1u,std::memory_order_release);return;
    }
    int result=-1;
    struct Publication {
        int& result;
        ~Publication() {
            bootstrap.store(result,std::memory_order_release);
            admission.fetch_and(~1u,std::memory_order_release);
        }
    } publication{result};
    try {
    std::wstring exe,self,canonical;
#if defined(DDCOOP_XINPUT_PROXY_TEST)
    if(test_exception.exchange(false))throw std::bad_alloc();
#endif
    HMODULE me{};
    const bool self_found=GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(&initialize_native),&me)!=FALSE;
#if defined(DDCOOP_XINPUT_PROXY_TEST)
    // Only the separately compiled fixture exposes an explicit bootstrap call.
    // Production has no test export and always requires this exact game hash.
    if(!module_path(nullptr,exe))goto finished;
#else
    if(!discovery_bytes() || !module_path(nullptr,exe) || !hash_matches(exe.c_str(),coop::build::sha256))goto finished;
#endif
    {
        const auto separator=exe.find_last_of(L"\\/");
        if(separator==std::wstring::npos || !self_found || !module_path(me,self)){result=-9;goto finished;}
        const auto directory=exe.substr(0,separator+1);
        if(_wcsicmp(self.c_str(),(directory+L"xinput1_3.dll").c_str())){result=-9;goto finished;}
        canonical=directory+L"ddcoop_runtime.dll";
        if(hash_matches((directory+L"dinput8.dll").c_str(),legacy_proxy_hash) || duplicate_runtime(canonical)){
            result=-6;goto finished;
        }
    }
    if(!cache_backend()){result=-2;goto finished;}
    {
        HMODULE runtime=LoadLibraryExW(canonical.c_str(),nullptr,LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR|LOAD_LIBRARY_SEARCH_SYSTEM32);
        if(!runtime){result=-3;last_error=GetLastError();goto finished;}
        // Retain even an inert runtime reference. A failing runtime may have
        // callbacks, transport hooks or trampolines that must survive to exit.
        runtime_module.store(runtime,std::memory_order_release);
        std::wstring loaded;
        if(!module_path(runtime,loaded) || _wcsicmp(loaded.c_str(),canonical.c_str())){result=-9;goto finished;}
        const auto identity=reinterpret_cast<unsigned(__cdecl*)()>(GetProcAddress(runtime,"CoopRuntimeBuildIdentity"));
        const auto state=reinterpret_cast<StateFn>(GetProcAddress(runtime,"CoopInitializationState"));
        const auto start=reinterpret_cast<int(__cdecl*)()>(GetProcAddress(runtime,"CoopInitialize"));
        if(!identity || !state || !start){result=-5;goto finished;}
        if(identity()!=runtime_identity){result=-4;goto finished;}
        runtime_state.store(state,std::memory_order_release);
        const int prior=state();
        if(prior!=0){result=prior==1?-10:-6;goto finished;}
        CoopRawGetState routed_get{};CoopRawGetCapabilities routed_caps{};CoopRawSetState routed_rumble{};
        if(boundary_ready.load(std::memory_order_acquire)) {
            const auto configure=reinterpret_cast<CoopConfigureInputBoundaryFn>(GetProcAddress(runtime,"CoopConfigureInputBoundary"));
            routed_get=reinterpret_cast<CoopRawGetState>(GetProcAddress(runtime,"CoopXInputGetState"));
            routed_caps=reinterpret_cast<CoopRawGetCapabilities>(GetProcAddress(runtime,"CoopXInputGetCapabilities"));
            routed_rumble=reinterpret_cast<CoopRawSetState>(GetProcAddress(runtime,"CoopXInputSetState"));
            if(!configure || !routed_get || !routed_caps || !routed_rumble ||
               configure(&raw_boundary,sizeof(raw_boundary))!=1){result=-5;goto finished;}
        }
        const int success=start();
        result=success==1 && state()==2?2:-7;
        if(result==2 && routed_get) {
            logical_get.store(routed_get,std::memory_order_release);
            logical_caps.store(routed_caps,std::memory_order_release);
            logical_rumble.store(routed_rumble,std::memory_order_release);
        }
