    // No forwarding caller can straddle the hook transaction: the closed bit
    // precedes the drain and stays closed through failure rollback/publication.
    // Publication also reopens it when a C++ exception interrupts startup;
    // loaded module references and existing transport blocking are retained.
    ;
}
