DWORD boundary_get_native(DWORD index,XINPUT_STATE* out,std::uintptr_t caller) {
    // A broken wrapper which calls the game IAT while being polled must never
    // recursively enter logical routing (which owns the runtime adapter lock).
    if(boundary_depth){if(out)*out={};return out?ERROR_DEVICE_NOT_CONNECTED:ERROR_BAD_ARGUMENTS;}
    BoundaryScope scope;
    if(boundary_ready.load(std::memory_order_acquire))initialize_native(caller);
    Admission ticket;if(!ticket.held)return neutral_state(index,out);
    const auto route=logical_get.load(std::memory_order_acquire);
    return bootstrap.load(std::memory_order_acquire)==2 && route?route(index,out):raw_boundary.get(index,out);
}
__declspec(noinline) DWORD WINAPI boundary_get(DWORD index,XINPUT_STATE* out) {
    return boundary_get_native(index,out,reinterpret_cast<std::uintptr_t>(_ReturnAddress()));
}
DWORD WINAPI boundary_caps(DWORD index,DWORD flags,XINPUT_CAPABILITIES* out) {
    if(boundary_depth){if(out)*out={};return out?ERROR_DEVICE_NOT_CONNECTED:ERROR_BAD_ARGUMENTS;}
    BoundaryScope scope;Admission ticket;if(!ticket.held)return neutral_caps(index,out);
    const auto route=logical_caps.load(std::memory_order_acquire);
    return bootstrap.load(std::memory_order_acquire)==2 && route?route(index,flags,out):raw_boundary.caps(index,flags,out);
}
DWORD WINAPI boundary_rumble(DWORD index,XINPUT_VIBRATION* value) {
    if(boundary_depth)return value?ERROR_DEVICE_NOT_CONNECTED:ERROR_BAD_ARGUMENTS;
    BoundaryScope scope;Admission ticket;
    if(!ticket.held)return !value?ERROR_BAD_ARGUMENTS:index?ERROR_DEVICE_NOT_CONNECTED:ERROR_SUCCESS;
    const auto route=logical_rumble.load(std::memory_order_acquire);
    return bootstrap.load(std::memory_order_acquire)==2 && route?route(index,value):raw_boundary.rumble(index,value);
