BOOL WINAPI DllMain(HINSTANCE,DWORD reason,LPVOID reserved){
    // Only the initial implicit import load can publish before native discovery.
    // No file/hash I/O, module load, MinHook, worker, wait or runtime call here.
    if(reason==DLL_PROCESS_ATTACH && reserved &&
       reinterpret_cast<std::uintptr_t>(GetModuleHandleW(nullptr))==0x400000)
        install_boundary(reinterpret_cast<void*>(0x400000),23117824u);
    return TRUE;
