extern "C" int __cdecl CoopLoaderGetStatus(CoopLoaderStatus* out,unsigned size) {
    if(!out || size!=sizeof(*out))return 0;
    CoopLoaderStatus value;
    value.bootstrap=bootstrap.load(std::memory_order_acquire);
    const auto state=runtime_state.load(std::memory_order_acquire);value.runtime=state?state():0;
    value.backend=reinterpret_cast<unsigned>(backend.load(std::memory_order_acquire));
    value.runtime_module=reinterpret_cast<unsigned>(runtime_module.load(std::memory_order_acquire));
    value.getstate_entry=reinterpret_cast<unsigned>(entries[0].load(std::memory_order_acquire));
    value.bootstrap_thread=owner.load();value.getstate_calls=calls.load();
    value.first_getstate_return=first_caller.load();value.last_getstate_return=last_caller.load();
    value.native_discovery_calls=discoveries.load();value.initialization_attempts=attempts.load();
    value.callback_calls=callbacks.load();value.reentry_calls=reentries.load();value.gated_calls=gated.load();
    const unsigned gate=admission.load();value.inflight_calls=gate>>1;value.gate_closed=gate&1;
    value.last_error=last_error.load();
    const unsigned matched=native_capture_count.load(std::memory_order_acquire);
    value.captured_count=matched?matched:first_capture_count.load(std::memory_order_acquire);
    const auto& frames=matched?native_frames:first_frames;
    for(unsigned i=0;i<value.captured_count;++i)value.captured_frames[i]=frames[i].load(std::memory_order_relaxed);
    *out=value;return 1;
}
