// Unknown ordinal ABIs must preserve the caller's original stack/registers.
// They never bootstrap. Their unchanged backend code is outside the named/game
// input admission contract. A missing backend has no ABI-safe synthetic return.
extern "C" FARPROC __cdecl ProxyXInputOpaqueTarget(unsigned ordinal) noexcept {
    cache_backend();
    const auto target=opaque_entries[ordinal-100].load(std::memory_order_acquire);
    if(!target)__fastfail(FAST_FAIL_FATAL_APP_EXIT);
    return target;
}
#define OPAQUE_THUNK(number) \
extern "C" __declspec(naked) void ProxyXInputOrdinal##number() { \
    __asm { pushfd } \
    __asm { pushad } \
    __asm { mov ebp,esp } \
    __asm { sub esp,512 } \
    __asm { and esp,0xfffffff0 } \
    __asm { fxsave [esp] } \
    __asm { cld } \
    __asm { push number } \
    __asm { call ProxyXInputOpaqueTarget } \
    __asm { add esp,4 } \
    __asm { mov [ebp+12],eax } \
    __asm { fxrstor [esp] } \
    __asm { mov esp,ebp } \
    __asm { popad } \
    __asm { popfd } \
    __asm { jmp dword ptr [esp-24] } \
}
OPAQUE_THUNK(100)
OPAQUE_THUNK(101)
OPAQUE_THUNK(102)
OPAQUE_THUNK(103)
#undef OPAQUE_THUNK

