'use strict';
// Run with node tests/performance_status_reader_tests.js. Mock buffer only;
// no Frida process, game, IPC, timers, or collection acceptance claim.
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const vm=require('node:vm');
const source=fs.readFileSync(path.join(__dirname,'../research/performance_status.js'),'utf8');
const SIZE=2448,VERSION=1;
const CHANNELS=['move_before','buttons_before','move_after','buttons_after','camera_before','camera_after','hud_after'];
const CATEGORIES=['self','native_helper','graphics','lock_wait'];
const UPPER=[0,50,100,250,500,1000,2000,5000,10000,50000,100000,2000000,null];
const results=[];
function fillFixture(b) {
 b.fill(0);const u=(o,v)=>b.writeUInt32LE(v>>>0,o),q=(o,v)=>b.writeBigUInt64LE(BigInt(v),o);
 u(0,SIZE);u(4,VERSION);u(8,2);u(12,127);
 [9007199254740993n,41n,37n,4n,3n,2n].forEach((v,i)=>q(16+i*8,v));
 const base=64;
 [10000000n,5n,1n,2n,3n,4n,5n,6n,7n,8n].forEach((v,i)=>q(base+i*8,v));
 for(let ci=0;ci<7;ci++) {
  const c=base+80+ci*328;
  for(let i=0;i<5;i++)q(c+i*8,BigInt((ci+1)*100+i));
  for(let i=0;i<4;i++){q(c+40+i*8,BigInt((ci+1)*10+i));q(c+72+i*8,BigInt((ci+1)*20+i));}
  for(const h of [c+104,c+216]) {
   for(let i=0;i<13;i++)q(h+i*8,(1n<<53n)+BigInt(ci*20+i));
   q(h+104,ci+9);
  }
 }
 u(base+2376,1);
}
function environment(options={}) {
 let moduleReads=0,allocations=0,statusCalls=0,beginCalls=0,sealCalls=0;
 class Pointer {constructor(buffer,offset=0){this.buffer=buffer;this.offset=offset;}add(n){return new Pointer(this.buffer,this.offset+n);}
  readU32(){return this.buffer.readUInt32LE(this.offset);}
  readU64(){if(options.numericOffset===this.offset)return Number(this.buffer.readBigUInt64LE(this.offset));return this.buffer.readBigUInt64LE(this.offset);}
  readPointer(){throw Error('Raw pointer reads are forbidden');}}
 const context={
  Process:{arch:options.arch||'ia32',pointerSize:options.pointerSize??4,getModuleByName(name){
   ++moduleReads;assert.equal(name,'ddcoop_runtime.dll');if(options.moduleError)throw Error('Module unavailable');
   return {getExportByName(exportName){if(options.missing===exportName)throw Error('Missing '+exportName);return exportName;}};
  }},
  Memory:{alloc(size){++allocations;assert.equal(size,SIZE);return new Pointer(Buffer.alloc(size));}},
  NativeFunction:function(address,result,args,abi){
   assert.equal(result,'int');assert.equal(abi,'mscdecl');
   if(address==='CoopGetPerformanceStatus') {
    assert.deepEqual(Array.from(args),['pointer','uint']);
    return (p,size)=>{++statusCalls;assert.equal(size,SIZE);if(options.throwStatus)throw Error('Status exception');
     (options.fill||fillFixture)(p.buffer);return options.refuse?0:1;};
   }
   assert.ok(['CoopBeginPerformance','CoopSealPerformance'].includes(address));assert.deepEqual(Array.from(args),[]);
   return ()=>{if(address==='CoopBeginPerformance'){++beginCalls;return options.beginResult??1;}++sealCalls;return options.sealResult??1;};
  }
 };
 vm.createContext(context);vm.runInContext(source,context);
 return {context,get moduleReads(){return moduleReads;},get allocations(){return allocations;},get statusCalls(){return statusCalls;},get beginCalls(){return beginCalls;},get sealCalls(){return sealCalls;}};
}
const test=(name,fn)=>{fn();results.push({name,passed:true});};
test('definitions are inert; reads cache one export and never start or seal',()=>{
 const e=environment();assert.equal(typeof e.context.readPerformanceStatus,'function');
 assert.equal(typeof e.context.beginPerformanceSession,'function');assert.equal(typeof e.context.sealPerformanceSession,'function');
 assert.equal(e.moduleReads,0);assert.equal(e.allocations,0);assert.equal(e.statusCalls,0);
 assert.equal(e.beginCalls,0);assert.equal(e.sealCalls,0);assert.doesNotMatch(source,/setInterval|setTimeout/);
 e.context.readPerformanceStatus();e.context.readPerformanceStatus();
 assert.equal(e.moduleReads,1);assert.equal(e.allocations,1);assert.equal(e.statusCalls,2);
 assert.equal(e.beginCalls,0);assert.equal(e.sealCalls,0);
});
test('decodes header, all batch and channel fields, mappings, and exact uint64 strings',()=>{
 const s=environment().context.readPerformanceStatus();assert.equal(s.size,SIZE);assert.equal(s.version,VERSION);
 assert.equal(s.state,2);assert.equal(s.coverage_mask,127);assert.equal(s.frequency,'9007199254740993');
 assert.equal(s.admitted_roots,'41');assert.equal(s.completed_roots,'37');assert.equal(s.active_roots,'4');
 assert.equal(s.clock_failures,'3');assert.equal(s.start_failures,'2');
 const b=s.totals;assert.equal(b.frequency,'10000000');assert.equal(b.valid_roots,'5');
 assert.equal(b.invalid_roots,'1');assert.equal(b.overflows,'2');assert.equal(b.mismatches,'3');
 assert.equal(b.clock_failures,'4');assert.equal(b.rollbacks,'5');assert.equal(b.invalid_channels,'6');
 assert.equal(b.invalid_categories,'7');assert.equal(b.configuration_failures,'8');assert.equal(b.saturated,1);
 assert.deepEqual(Object.keys(b.channels),CHANNELS);
 for(let ci=0;ci<CHANNELS.length;ci++) {
  const c=b.channels[CHANNELS[ci]];assert.equal(c.calls,String((ci+1)*100));
  assert.equal(c.wall_ticks,String((ci+1)*100+1));assert.equal(c.child_ticks,String((ci+1)*100+2));
  assert.equal(c.max_wall_ticks,String((ci+1)*100+3));assert.equal(c.max_self_ticks,String((ci+1)*100+4));
  assert.deepEqual(Object.keys(c.category_ticks),CATEGORIES);assert.deepEqual(Object.keys(c.category_entries),CATEGORIES);
  for(let i=0;i<4;i++){assert.equal(c.category_ticks[CATEGORIES[i]],String((ci+1)*10+i));assert.equal(c.category_entries[CATEGORIES[i]],String((ci+1)*20+i));}
  for(const h of [c.wall_us,c.self_us]) {
   assert.deepEqual(Array.from(h.upper_us),UPPER);assert.equal(h.bins.length,13);
   assert.equal(h.bins[0],String((1n<<53n)+BigInt(ci*20)));assert.equal(h.bins[12],String((1n<<53n)+BigInt(ci*20+12)));
   assert.equal(h.count,String(ci+9));
  }
 }
 assert.match(s.coverage.elapsed,/not CPU execution/);assert.match(s.coverage.channels,/HUD after/);
 assert.match(s.coverage.lifecycle,/explicit beginPerformanceSession/);
});
test('explicit controls resolve and run only when called; status reads remain separate',()=>{
 const e=environment();assert.equal(e.context.beginPerformanceSession(),true);assert.equal(e.beginCalls,1);
 assert.equal(e.context.beginPerformanceSession(),true);assert.equal(e.beginCalls,2);
 assert.equal(e.context.sealPerformanceSession(),true);assert.equal(e.sealCalls,1);
 assert.equal(e.statusCalls,0);assert.equal(e.allocations,0);
});
test('control refusal is reported as false without implicit retries or reads',()=>{
 const e=environment({beginResult:0,sealResult:-1});assert.equal(e.context.beginPerformanceSession(),false);
 assert.equal(e.context.sealPerformanceSession(),false);assert.equal(e.beginCalls,1);assert.equal(e.sealCalls,1);
 assert.equal(e.statusCalls,0);
});
test('wrong status ABI size/version and rejected export are refused',()=>{
 for(const [field,value] of [['size',SIZE-8],['version',2]]) {
  const e=environment({fill(b){fillFixture(b);b.writeUInt32LE(value,field==='size'?0:4);}});
  assert.throws(()=>e.context.readPerformanceStatus(),/size\/version mismatch/);
 }
 assert.throws(()=>environment({refuse:true}).context.readPerformanceStatus(),/refused diagnostic ABI/);
});
test('missing module or exports and unsupported host ABI fail closed',()=>{
 for(const options of [{moduleError:true},{missing:'CoopGetPerformanceStatus'},
  {missing:'CoopBeginPerformance'},{missing:'CoopSealPerformance'},
  {arch:'x64',pointerSize:8}]) {
  const e=environment(options);
  if(options.missing==='CoopGetPerformanceStatus'||options.moduleError||options.arch)
   assert.throws(()=>e.context.readPerformanceStatus());
  else if(options.missing==='CoopBeginPerformance')assert.throws(()=>e.context.beginPerformanceSession());
  else assert.throws(()=>e.context.sealPerformanceSession());
 }
});
test('thrown status export and unsafe numeric uint64 values surface errors',()=>{
 assert.throws(()=>environment({throwStatus:true}).context.readPerformanceStatus(),/Status exception/);
 assert.throws(()=>environment({numericOffset:16}).context.readPerformanceStatus(),/Unsafe uint64/);
});
console.log(JSON.stringify({passed:results.length,failed:0,scope:'Mocked performance ABI buffer only; no game/Frida/IPC or collection acceptance claim.',tests:results},null,2));

